fun solve(reader: LineReader, writer: PrintWriter) {
    val (year, month, day) = reader.readLine().split(':').map(String::toInt)
    val (year2, month2, day2) = reader.readLine().split(':').map(String::toInt)
    val start = Calendar.getInstance().apply { set(year + 400, month, day) }
    val end = Calendar.getInstance().apply { set(year2 + 400, month2, day2) }
    val result = abs(end.timeInMillis - start.timeInMillis + 1) / 1000
    writer.println(result / 3600 / 24)
}

