fun maxProduct(input: Int): Long {
    if (input < 10) return input.toLong()

    val inputDigits = splitDigits(input)

    var max: Long = 0
    val nines = generateNines(inputDigits)
    for (digits in nines) {
        val prod = product(digits)
        if (prod > max) {
            max = prod
        }
    }
    return max
}

fun generateNines(digits: List<Int>): List<List<Int>> {
    val nines: MutableList<List<Int>> = ArrayList(digits.size)

    for (i in 0 until digits.size) {
        val tail = Collections.nCopies(i, 9)
        val head = splitDigits(digits.subList(0, digits.size - i).joinToString("").toInt() - 1)
        nines.add(head + tail)
    }

    return nines
}

