class FastScanner(s: InputStream) {
    val br = BufferedReader(InputStreamReader(s))
    var st = StringTokenizer("")
    fun next(): String {
        if (!st.hasMoreTokens())
            st = StringTokenizer(br.readLine())
        return st.nextToken()
    }

    fun nextInt() = next().toInt()
    fun nextLong() = next().toLong()
}

