    fun recursion(sb: StringBuilder, fours: Int, sevens: Int): String? {
        if (fours == 0 && sevens == 0) {
            if (sb.toString().toInt() >= nInt) return sb.toString()
            else return null
        } else {
            if (fours > 0) {
                sb.append('4')
                val option1 = recursion(sb, fours - 1, sevens)
                if (option1 != null) return option1
                sb.deleteCharAt(sb.lastIndex)
            }
            if (sevens > 0) {
                sb.append('7')
                val option2 = recursion(sb, fours, sevens - 1)
                if (option2 != null) return option2
                sb.deleteCharAt(sb.lastIndex)
                return null
            }
            return null
        }
    }

    for (length in n.length .. n.length + 2) {
        if (length % 2 == 1) continue
        val sb = StringBuilder()
        val sol = recursion(sb, length / 2, length / 2)
        if (sol != null) return print(sol)
    }
}

