fun <T: Comparable<T>> List<T>.windowedMins(len: Int): Sequence<T> = sequence {
    var l = len
    val deq = ArrayDeque<T>()
    for(i in indices) {
        val n = get(i)
        while(deq.isNotEmpty() && deq.last > n) deq.removeLast()
        deq.addLast(n)
        if(i >= len && get(i-len) == deq.first) deq.removeFirst()
        if(i+1 >= len) yield(deq.first)
    }
}

fun <T, R> List<T>.virtualMap(func: (T) -> R): List<R> = VirtualMapList(this, func)

class VirtualMapList<T, R>(val delegate: List<T>, val mapFunc: (T) -> R): AbstractList<R>() {
    override val size: Int
        get() = delegate.size

    override fun get(index: Int): R = mapFunc(delegate[index])
}

