class Window(@JvmField val len: Int) {
    @JvmField val eleQ = ArrayDeque<Int>(len)
    @JvmField val minQ = ArrayDeque<Int>(len)

    inline fun add(item: Int) {
        if(eleQ.size == len && eleQ.pollFirst() == minQ.first) minQ.pollFirst()
        eleQ.addLast(item)
        while(minQ.isNotEmpty() && minQ.last > item) minQ.pollLast()
        minQ.addLast(item)
    }

    inline val min: Int get() = minQ.first
}

