import java.util.*
import kotlin.math.min

fun main() {
    val jin = Scanner(System.`in`)
    val n = jin.nextInt()
    val m = jin.nextInt()
    val a = jin.nextInt()
    val b = jin.nextInt()
    var g = jin.nextLong()
    val x = jin.nextLong()
    val y = jin.nextLong()
    val z = jin.nextLong()
    var before = Array(n) { LongArray(m) {
        val res = g
        g = ((g * x) + y) % z
        res
    }}
    /*for (i in 0 until n) {
        for (j in 0 until m) {
            println("array[" + i + "][" + j + "] = " + before[i][j])
        }
    }*/
    var after = Array(n) { LongArray(m) }
    var alpha = 1
    while ((2 * alpha) <= a) {
        for (i in 0 until n) {
            for (j in 0 until m) {
                after[i][j] = min(before[i][j], before[(i + alpha) % n][j])
            }
        }
        val temp = before
        before = after
        after = temp
        alpha *= 2
    }
    var beta = 1
    while ((2 * beta) <= b) {
        for (i in 0 until n) {
            for (j in 0 until m) {
                after[i][j] = min(before[i][j], before[i][(j + beta) % m])
            }
        }
        val temp = before
        before = after
        after = temp
        beta *= 2
    }
    //println("a = " + a + ", b = " + b + ", alpha = " + alpha + ", beta = " + beta)
    var answer: Long = 0
    for (i in 0..n - a) {
        for (j in 0..m - b) {
            val delta = min(
                    min(before[i][j], before[i][j + b - beta]),
                    min(before[i + a - alpha][j], before[i + a - alpha][j + b - beta])
            )
            //println("delta[" + i + "][" + j + "] = " + delta)
            answer += delta
        }
    }
    println(answer)
}

