fun solve(values: List<Int>, length: Int, sum: Int, initialPos: Int): Boolean {
    var otherSum = 0
    for (pos in initialPos until length) {
        otherSum += values[pos]
        if (otherSum == sum) {
            otherSum = 0
        } else if (otherSum > sum) {
            return false
        }
    }
    return otherSum == 0
}

