class B {
    fun start(ins: InputStream) {
        val field = Array(3) { Array(3) { Array(3) { Array(3) { '.' } } } }

        for (i in 0..2) {
            for (j in 0..2) {
                for (k in 0..2) {
                    for (t in 0..2) {
                        field[i][j][k][t] = ins.read().toChar()
                    }
                    ins.read()
                }
            }
        }

        val scanner = Scanner(ins)
        val x = scanner.next().toInt()
        val y = scanner.next().toInt()

        val sx = if (x % 3 == 0) 2 else (x - 1) % 3
        val sy = if (y % 3 == 0) 2 else (y - 1) % 3

        var isCan = false
        for (i in field[sx])
            for (j in i[sy].indices) {
                if (i[sy][j] == '.') {
                    isCan = true
                    i[sy][j] = '!'
                }
            }
        if (!isCan) {
            for (i in field) {
                for (j in i) {
                    for (k in j) {
                        for (t in k.indices) {
                            if (k[t] == '.')
                                k[t] = '!'
                        }
                    }
                }
            }
        }

        for (i in 0..2) {
            for (j in 0..2) {
                for (k in 0..2) {
                    for (t in 0..2) {
                        print(field[i][j][k][t])
                    }
                    print(' ')
                }
                print("\n")
            }
            print("\n")
        }
    }
}

