class Parser(`in`: InputStream) {
    private val BUFFER_SIZE = 1 shl 16
    private val din: DataInputStream
    private val buffer: ByteArray
    private var bufferPointer: Int = 0
    private var bytesRead: Int = 0

    init {
        din = DataInputStream(`in`)
        buffer = ByteArray(BUFFER_SIZE)
        bytesRead = 0
        bufferPointer = bytesRead
    }

    fun nextString(maxSize: Int): String {
        val ch = ByteArray(maxSize)
        var point = 0
        try {
            var c = read()
            while (c == ' '.toByte() || c == '\n'.toByte() || c == '\r'.toByte())
                c = read()
            while (c != ' '.toByte() && c != '\n'.toByte() && c != '\r'.toByte()) {
                ch[point++] = c
                c = read()
            }
        } catch (e: Exception) {}

        return String(ch, 0, point)
    }

    fun nextInt(): Int {
        var ret = 0
        val neg: Boolean
        try {
            var c = read()
            while (c <= ' '.toByte())
                c = read()
            neg = c == '-'.toByte()
            if (neg)
                c = read()
            do {
                ret = ret * 10 + c - '0'.toInt()
                c = read()
            } while (c > ' '.toByte())

            if (neg) return -ret
        } catch (e: Exception) {}
        return ret
    }

    fun nextLong(): Long {
        var ret: Long = 0
        val neg: Boolean
        try {
            var c = read()
            while (c <= ' '.toByte())
                c = read()
            neg = c == '-'.toByte()
            if (neg)
                c = read()
            do {
                ret = ret * 10 + c - '0'.toLong()
                c = read()
            } while (c > ' '.toByte())

            if (neg) return -ret
        } catch (e: Exception) {}

        return ret
    }

    fun nextDouble(): Double
            = nextString(10000).toDouble()

    private fun fillBuffer() {
        try {
            bytesRead = din.read(buffer, 0, BUFFER_SIZE)
        } catch (e: Exception) {}
        if (bytesRead == -1) buffer[0] = -1
    }

    private fun read(): Byte {
        if (bufferPointer == bytesRead) fillBuffer()
        return buffer[bufferPointer++]
    }
}
class Scanner(s: InputStream) {
    var st: StringTokenizer? = null
    var br: BufferedReader = BufferedReader(InputStreamReader(s))
    @Throws(IOException::class)
    operator fun next(): String {
        while (st == null || !st!!.hasMoreTokens())
            st = StringTokenizer(br.readLine())
        return st!!.nextToken()
    }
    @Throws(IOException::class)
    fun nextInt(): Int {
        return Integer.parseInt(next())
    }
    @Throws(IOException::class)
    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }
    @Throws(IOException::class)
    fun nextLine(): String {
        return br.readLine()
    }
    @Throws(IOException::class)
    fun nextDouble(): Double {
        return java.lang.Double.parseDouble(next())
    }
    @Throws(IOException::class)
    fun ready(): Boolean {
        return br.ready()
    }
}
