public class Main {

    public companion object {

        private val vowels = HashSet(arrayListOf('a', 'e', 'i', 'o', 'u'))
        private val noRestrictions = HashSet(arrayListOf('a', 'e', 'i', 'o', 'u', 'n'))

        private fun isCorrect(str: String): Boolean {
            str.forEachIndexed() { ind, c ->
                if (!noRestrictions.contains(c)) {
                    if (ind == str.length - 1) return false
                    else if (!vowels.contains(str[ind + 1])) return false
                }
            }

            return true
        }

        @JvmStatic
        public fun main(args: Array<String>) {
            val scan = Scanner(System.`in`)

            val str = scan.nextLine().trim()

            println(if (isCorrect(str)) "YES" else "NO")
        }
    }
}

