fun main() {
    var n = readLine()!!.toInt()

    var set = (1..n).toMutableSet()
    var array = readLine()!!.split(" ").map { it.toInt() }.toIntArray()

    if(array.all { it == 0 }) {
        println(1)
        return
    }

    for (item in array) {
        set.remove(item)
    }

    var s = set.map { it % 2 == 0 }.toList()
    var countFalse = s.count { !it }
    var countTrue = s.count { it }

    var answerArray = array.map { if (it == 0) null else it % 2 == 0 }.toTypedArray()

    var sections = mutableListOf<Section>()

    var startIndex: Int? = null
    for (index in answerArray.indices) {
        if (answerArray[index] == null) {
            continue
        }

        if (startIndex == null) {
            startIndex = index
            continue
        }

        if (startIndex + 1 != index && answerArray[startIndex] == answerArray[index]) {
            sections.add(Section(startIndex, index, answerArray[startIndex]!!))
        }

        startIndex = index
    }

    sections.sortBy { it.end - it.start }

    for (sec in sections) {
        if (sec.isTrue && countTrue >= sec.size()
            || !sec.isTrue && countFalse >= sec.size()
        ) {
            for (i in sec.start + 1 until sec.end) {
                answerArray[i] = sec.isTrue
            }

            if (sec.isTrue) {
                countTrue -= sec.size()
            } else {
                countFalse -= sec.size()
            }
        }
    }

    if(answerArray.first() == null) {
        for(i in answerArray.indices) {
            if(answerArray[i] != null) {
                if(answerArray[i]!! && countTrue >= i
                    || !answerArray[i]!! && countFalse >= i) {
                    for(j in 0 until i) {
                        answerArray[j] = answerArray[i]
                    }

                    if(answerArray[i]!!) {
                        countTrue -= i
                    } else {
                        countFalse -= i
                    }
                }
                break
            }
        }
    }

    if(answerArray.last() == null) {
        for(i in answerArray.size - 1 downTo 0) {
            if(answerArray[i] != null) {
                var size = answerArray.size - i - 1
                if(answerArray[i]!! && countTrue >= size || !answerArray[i]!! && countFalse >= size) {
                    for(j in i + 1 until answerArray.size) {
                        answerArray[j] = answerArray[i]
                    }

                    if(answerArray[i]!!) {
                        countTrue -= size
                    } else {
                        countFalse -= size
                    }
                }
                break
            }
        }
    }

    var index = 0
    while (index < answerArray.size) {
        if (answerArray[index] != null) {
            index++
            continue
        }

        var left = if (index > 0) answerArray[index - 1] else null
        var right = if (index < answerArray.size - 1) answerArray[index + 1] else null

        if(left == null && right == null) {
            index++
            continue
        }

        if((left == true || right == true || countFalse == 0) && countTrue > 0) {
            answerArray[index] = true
            countTrue--
        } else {
            if((left == false || right == false || countTrue == 0) && countFalse > 0) {
                answerArray[index] = false
                countFalse--
            }
        }

        if(index > 0 && left == null && right != null) {
            index--
        } else {
            index++
        }
    }


    var answer = 0
    for (i in 0 until answerArray.size - 1) {
        if (answerArray[i] != answerArray[i + 1]) {
            answer++
        }
    }

    println(answer)
//    println(answerArray.joinToString(" "))
}

