private class Task {
    fun solve(input: InputReader, output: PrintWriter) {
        val n = input.nextInt()

        val a = input.nextInt()
        val b = input.nextInt()
        val c = input.nextInt()

        var max = 0

        for (i in 0..(n / a)) {
            for (j in 0..(n / b)) {
                for (k in 0..(n / c)) {
                    if (i * a + j * b + k * c == n && i + j + k > max) max = i + j + k
                }
            }
        }

        output.println(max)
    }
}


