val getM0 = Mint(0)
val getM1 = Mint(1)
val getM2 = Mint(2)

val getMOD: Long = 998244353
val getMOD_TOTIENT = (getMOD - 1).toInt()

fun mint(num: Long) = Mint(num % getMOD)
fun mint(num: Int) = Mint(num % getMOD)

inline class Mint(val num: Long) {

    operator fun plus(k: Mint) = mint(num + k.num)
    operator fun minus(k: Mint) = mint(num + getMOD - k.num)
    operator fun times(k: Mint) = mint(num * k.num)
    operator fun div(k: Mint) = this * (k pow -1)

    operator fun unaryMinus() = mint(getMOD - num)
    operator fun inc() = this + getM1
    operator fun dec() = this - getM1

    infix fun pow(power: Int): Mint {
        var e = power
        e %= getMOD_TOTIENT
        if (e < 0) {
            e += getMOD_TOTIENT
        }
        if (e == 0 && num == 0L) {
            return this
        }
        var b = this
        var res = Mint(1)
        while (e > 0) {
            if (e and 1 != 0) {
                res *= b
            }
            b *= b
            e = e shr 1
        }
        return res
    }

    override fun toString(): String = num.toString()
}

