class FastScanner(s: InputStream) {
    private var st = StringTokenizer("")
    private val br = BufferedReader(InputStreamReader(s))

    fun next(): String {
        while (!st.hasMoreTokens()) st = StringTokenizer(br.readLine())

        return st.nextToken()
    }

    fun nextInt() = next().toInt()
    fun nextLong() = next().toLong()
    fun nextLine() = br.readLine()
    fun nextDouble() = next().toDouble()
    fun ready() = br.ready()
}

fun main(args: Array<String>) {
    val fac: (Int) -> Int = {n -> var res = 1; for (p in 1 .. n) res *= p; res}

    fun d(n: Int): Int {
        val i: Int
        var res = 0

        for (i in 0 .. n) {
            val sign = {it: Int -> if (it % 2 == 0) 1 else -1}(i)
            res += sign * fac(n) / fac(i)
        }
        return res
    }

    fun c(n: Int, m: Int): Int{
        var p = 1
        for (i in (n - m + 1) .. n) {
            p *= i
        }
        return p / fac(m)
    }

    val s = readLine()!!.split(" ").map { it -> it.toInt() }
    val n = s[0]
    val k = s[1]
    println((0 .. k).map { m -> c(n, m) * d(m) }.sum())
}

