fun factorize(a: Long): List<Pair<Long, Int>> {
  val res = mutableListOf<Pair<Long, Int>>()
  var x = a
  var i = 2
  while(i * i <= x) {
    var cnt = 0
    while (x % i == 0L) {
      cnt++
      x /= i
    }
    if (cnt > 0) res += Pair(i.toLong(), cnt)
    i++
  }
  if (x > 1) res += Pair(x, 1)
  return res
}
