    var min = 105

    for (i in 0 until (n - 3)) {
        var count = 0
        if (c[i] != 'A') {
            val num = (c[i] - 64).toInt()
            val n1 = Math.abs(27 - num)
            val n2 = Math.abs(1 - num)

            count += if (n1 <= n2)
                n1
            else
                n2
        }

        if (c[i + 1] != 'C') {
            val num = (c[i + 1] - 64).toInt()
            val n1 = Math.abs(29 - num)
            val n2 = Math.abs(3 - num)

            count += if (n1 <= n2)
                n1
            else
                n2
        }

        if (c[i + 2] != 'T') {
            val num = (c[i + 2] - 64).toInt()
            val n1 = Math.abs(6 + num)
            val n2 = Math.abs(20 - num)

            count += if (n1 <= n2)
                n1
            else
                n2
        }

        if (c[i + 3] != 'G') {
            val num = (c[i + 3] - 64).toInt()
            val n1 = Math.abs(33 - num)
            val n2 = Math.abs(7 - num)

            count += if (n1 <= n2)
                n1
            else
                n2
        }

        min = Math.min(count, min)
        pw.println(count)
    }

    pw.println(min)

}

class Reader(stream: InputStream) {
    private val reader: BufferedReader = BufferedReader(InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer? = null

    init {
        tokenizer = null
    }

    operator fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens())
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        return tokenizer!!.nextToken()
    }

    fun nextLine(): String? {
        val fullLine: String
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                fullLine = reader.readLine()
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

            return fullLine
        }
        return null
    }

    fun toArray(): Array<String> {
        return nextLine()!!.split(" ".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextDouble(): Double {
        return java.lang.Double.parseDouble(next())
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

}

