private fun String.diff(s: String) = (0 until length).map { s[it].diff(get(it)) }.sum()

private fun Char.diff(c: Char): Int {
  val a: MutableList<Int> = mutableListOf()
  a.addIfNotNegative(this - c)
  a.addIfNotNegative(c - this)
  a.addIfNotNegative(('Z' - this) + (c - 'A') + 1)
  a.addIfNotNegative((this - 'A') + ('Z' - this) + 1)
  return a.min()!!
}

private fun MutableList<Int>.addIfNotNegative(e: Int) {
  if (e >= 0) add(e)
}

