    tailrec fun reachableNumbersAcc(n: Int, f: (Int) -> Int, acc: List<Int>): List<Int> {
        if (f(n) in acc) return acc
        val m = f(n)
        return reachableNumbersAcc(m, f, acc + listOf(m))
    }
    return reachableNumbersAcc(n, f, listOf(n)).sorted()
}

