fun calc2(A: IntArray): Boolean {
  val dp = Array(A[0] + 1) { BooleanArray(A[1] + 1) }
  for (i in 0..A[0]) {
    for (j in 0..A[1]) {
      var win = false
      for (l in 0 until i) {
        if (!dp[l][j]) win = true
      }
      for (l in 0 until j) {
        if (!dp[i][l]) win = true
      }
      for (l in 1..min(i, j)) {
        if (!dp[i - l][j - l]) win = true
      }
      dp[i][j] = win
    }
  }
  return dp[A[0]][A[1]]
}











































