fun solve(input: InputStream, output: OutputStream) {
    val reader = Reader(input) //Reader(FileInputStream(File("portals.in")))
    val writer = PrintWriter(BufferedOutputStream(output)) //PrintWriter(FileOutputStream(File("output.txt")))

