import java.util.*
import kotlin.system.exitProcess

fun main(args: Array <String>) {

    var scanner : Scanner = Scanner(System.`in`)
    var n = scanner.nextInt()
    var k = scanner.nextInt()

    var a : ArrayList<Int> = ArrayList<Int>()

    var sum : Double = 0.0
    for (i in 1 .. n) {
        var x = scanner.nextInt()
        a.add(x)
        sum += x
    }
    sum /= n
    if (sum + 0.5 >= k) {
        println(0)
        exitProcess(1)
    }
    var cntK : Int = 0
    for (i in 0 .. n - 1)
        if (a[i] == k) cntK++;

    var need : Int = 0
    for (i in 0 .. n - 1) {
        if (a[i] < k) {
            var cnt : Int = k - 1 - a[i]
            a[i] += Math.min(cnt, cntK)
            cntK -= Math.min(cnt, cntK)
            need += k - 1 - a[i]
        }
    }

    println(n + 2 * need)
}

