fun solveA(data: List<Int>): Int {
    val middle = data.dropWhile { it == 0 }.dropLastWhile { it == 1 }
    val beginAndEndCount = data.size - middle.size
    val zeroesCount = middle.count { it == 0 }
    val onesCount = middle.size - zeroesCount
    return beginAndEndCount + Math.max(zeroesCount, onesCount)
}

