fun solve(reader: InputReader, writer: PrintWriter) {
    val n = reader.nextInt()
    val a = reader.nextArrayInt(n)
    var ans = 0
    for (i in 0 until n) {
        val x0 = a.filterIndexed { index, value -> index in 0..i && value == 0 }.count()
        val x1 = a.filterIndexed { index, value -> index in i + 1 until n && value == 1 }.count()
        ans = max(ans, x0 + x1)
    }
    writer.println(ans)
}

