  internal class InputReader(stream:InputStream) {
    private val stream:InputStream
    private val buf = ByteArray(1024)
    private val curChar:Int = 0
    private val numChars:Int = 0
    private val filter:InputReader.SpaceCharFilter
    init{
      this.stream = stream
    }
    fun read():Int {
      if (numChars == -1)
      {
        throw InputMismatchException()
      }
      if (curChar >= numChars)
      {
        curChar = 0
        try
        {
          numChars = stream.read(buf)
        }
        catch (e:IOException) {
          throw InputMismatchException()
        }
        if (numChars <= 0)
        {
          return -1
        }
      }
      return buf[curChar++].toInt()
    }
    fun nextInt():Int {
      val c = read()
      while (isSpaceChar(c))
      {
        c = read()
      }
      val sgn = 1
      if (c == '-'.toInt())
      {
        sgn = -1
        c = read()
      }
      val res = 0
      do
      {
        if (c < '0'.toInt() || c > '9'.toInt())
        {
          throw InputMismatchException()
        }
        res *= 10
        res += c - '0'.toInt()
        c = read()
      }
      while (!isSpaceChar(c))
      return res * sgn
    }
    fun isSpaceChar(c:Int):Boolean {
      if (filter != null)
      {
        return filter.isSpaceChar(c)
      }
      return isWhitespace(c)
    }
    interface SpaceCharFilter {
      fun isSpaceChar(ch:Int):Boolean
    }
    companion object {
      fun isWhitespace(c:Int):Boolean {
        return c == ' '.toInt() || c == '\n'.toInt() || c == '\r'.toInt() || c == '\t'.toInt() || c == -1
      }
    }
  }
}

