fun <T : Number> T.digitSum() = this.toString().fold(0) { acc, next -> acc + next.toInt() - '0'.toInt() }

fun solve(inp: InputReader) {
    val (n, s) = inp.nextLine().split(" ").map(String::toInt)
    var current = s
    while (current <= n && current - current.digitSum() < s) {
        current += 1
    }
    val res = max(n - current + 1, 0)
    println(res)
}


