private class FScanner internal constructor(inputStream: InputStream = System.`in`) {
    internal val br = BufferedReader(InputStreamReader(inputStream))
    internal var st = StringTokenizer("")

    internal fun hasNext(): Boolean {
        while (!st.hasMoreTokens())
            st = StringTokenizer(br.readLine() ?: return false)
        return true
    }

    internal operator fun next() =
            if (hasNext()) st.nextToken()!!
            else throw RuntimeException("No tokens")

    internal fun nextInt() = next().toInt()

    internal fun nextLong() = next().toLong()

    internal fun nextLine() =
            if (hasNext()) st.nextToken("\n")
            else throw RuntimeException("No tokens")

    internal fun nextIntArray(n: Int) = IntArray(n, { nextInt() })

    internal fun nextLongArray(n: Int) = LongArray(n, { nextLong() })
}


