                rev += Triple(s[inv], b[inv], s[it])
                sum -= b[it]
            } else {
                remChar[s[inv].toByte() - 'a'.toByte()]++
                rev += Triple(s[it], b[it], s[inv])
                sum -= b[inv]
            }
        } else {
            rev += Triple(s[it], b[it], s[inv])
            rev += Triple(s[inv], b[inv], s[it])
        }
    }

    val remStat = PriorityQueue<Pair<Char, Int>>(compareBy<Pair<Char, Int>> { -it.second })
    remChar
            .forEachIndexed { index, i ->
                if (i > 0) {
                    remStat += Pair((index + 'a'.toByte()).toChar(), i)
                }
            }

//    println(remStat.joinToString(" "))
//    println(sum)

    if (remStat.isNotEmpty()) {
        var x = remStat.poll()
        var xleft = x.second
        while (remStat.isNotEmpty()) {
            val y = remStat.poll()
            if (y.second <= xleft) {
                xleft -= y.second
            } else {
                xleft = y.second - xleft
                x = y
            }
        }
//        println("Need remove ${x.first} $xleft")
//        println(rev.joinToString(" "))
        //find different x
        while (xleft > 0) {
            val re = rev.poll()
            if (re.first != x.first && re.third != x.first) {
//                println("Remove $re")
                xleft--
                sum -= re.second
            }
        }
    }



    println(sum)
}

