private fun merge(aPos: List<Int>, bPos: List<Int>, n: Int): List<IntPair> {
    val merged = ArrayList<IntPair>(aPos.size + bPos.size + 2)
    if (aPos[0] != 0 && bPos[0] != 0) {
        merged.add(IntPair(0, 0))
    }

    var i = 0
    var j = 0
    while (i < aPos.size || j < bPos.size) {
        if (j >= bPos.size || (i < aPos.size && aPos[i] < bPos[j])) {
            merged.add(IntPair(1, aPos[i++]))
        } else {
            merged.add(IntPair(-1, bPos[j++]))
        }
    }
    if (merged.last().index != n - 1) {
        merged.add(IntPair(0, n - 1))
    }
    return merged
}


