fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val p = Array(n) { sc.nextInt() }
    var even = n / 2
    var odd = (n + 1) / 2
    for (i in 0 until n) {
        if (p[i] != 0) {
            if (p[i] % 2 == 0) even--
            else odd--
        }
    }
    var ans = 0
    val ee = mutableListOf<Int>()
    val eo = mutableListOf<Int>()
    val oo = mutableListOf<Int>()
    val e = mutableListOf<Int>()
    val o = mutableListOf<Int>()
    var streak = 0
    for (i in 0 until n) {
        if (p[i] == 0) streak++
        else {
            if (streak == i) {
                if (p[i] % 2 == 0) e.add(streak)
                else o.add(streak)
            } else {
                val j = i - streak - 1
                if (p[i] % 2 == 0 && p[j] % 2 == 0) ee.add(streak)
                else if (p[i] % 2 == 1 && p[j] % 2 == 1) oo.add(streak)
                else eo.add(streak)
            }
            streak = 0
        }
    }
    if (streak > 0) {
        val j = n - streak - 1
        if (p[j] % 2 == 0) e.add(streak)
        else o.add(streak)
    }
    for (s in ee) {
        if (s == 0) continue
        even -= s
        if (even < 0) ans += 2
    }
    for (s in oo) {
        if (s == 0) continue
        odd -= s
        if (odd < 0) ans += 2
    }
    for (s in e) {
        if (s == 0) continue
        even -= s
        if (even < 0) ans++
    }
    for (s in o) {
        if (s == 0) continue
        odd -= s
        if (odd < 0) ans++
    }
    ans += eo.count()
    println(ans)
}

