    private val br = BufferedReader(InputStreamReader(s))

    fun next(): String {
        while (!st.hasMoreTokens()) st = StringTokenizer(br.readLine())

        return st.nextToken()
    }

    fun nextInt() = next().toInt()
    fun nextLong() = next().toLong()
    fun nextLine() = br.readLine()
    fun nextDouble() = next().toDouble()
    fun ready() = br.ready()
}

import java.util.*

data class Row(var left: Int = -1, var right: Int = -1, var length: Int = 0)

fun main(args: Array<String>){
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    if (n==1){
        println(0)
        return
    }
    var even = n/2 + n%2
    var odd = n/2
    val rows = arrayListOf<Row>()
    var left = -1
    var right = -1
    var answer = 0
    var length = 0
    for (i in 0 until n){
        var a = scanner.nextInt()
        if (a==0){
            length++
            continue
        }

        if (length==0){
            a%=2
            if (a!=left && left!=-1){
                answer++
            }
            left=a
            if (a==0){
                odd--
            }
            else{
                even--
            }
        }
        else{
            right = a%2
            rows.add(Row(left, right, length))
            left = right
            right=-1
            length=0
            if (a%2==0){
                odd--
            }
            else{
                even--
            }
        }
    }
    if (length!=0){
        rows.add(Row(left, right, length))
    }
    rows.sortBy { it.length }
    for (row in rows){
        if (row.left ==-1 && row.right==-1){
            answer+=1
            continue
        }
        if (row.left ==-1 || row.right==-1){
            if (row.left+row.right+1==0){
                if (row.length<=odd){
                    odd-=row.length
                }
                else{
                    answer+=1
                }
            }
            else{
                if (row.length<=even){
                    even-=row.length
                }
                else{
                    answer+=1
                }
            }
            continue
        }

        if (row.left!=row.right){
            answer++
        }
        else{
            if (row.left==0){
                if (row.length<=odd){
                    odd-=row.length
                }
                else{
                    answer+=2
                }
            }
            else{
                if (row.length<=even){
                    even-=row.length
                }
                else{
                    answer+=2
                }
            }
        }
    }
    println(answer)
}

