class A1113 {
    fun run() {
        val sc = Scanner(systemIn())
        val n=sc.nextInt()
        val v=sc.nextInt()

        var ans=minFuel(n, v)
        println("$ans")
    }

    fun minFuel(n:Int, v:Int):Int {
        if(n-1<=v)
            return n-1   // tank as much as needed in first city
        else {
            // make take full, drive as long as possible
            var ans=v
            var x=(n-1)%v+1 // first tank stop
            //log("first tankstop: $x")
            ans+=(x*(x-1))
            x+=v
            while(x<n) {
                ans+=x*v;
                x+=v
            }
            return ans
        }
    }

    companion object {
        var inputStr: String? = null

        fun systemIn(): InputStream {
            if (inputStr != null)
                return ByteArrayInputStream(inputStr!!.toByteArray())
            else
                return System.`in`
        }

        var printLog = false
        fun log(str: String) {
            if (printLog)
                println(str)
        }
    }
}

