private fun isAliceTurn(turnNumber: Int) = turnNumber % 2 != 0

private fun eatCandy(sweets: LinkedList<Int>, removeFun: () -> Int): Int? =
    if (sweets.isNotEmpty()) removeFun() else null

private fun turn(eatCandy: () -> Int?, prevScore: Int): Int {
    var score = 0
    while (score <= prevScore) {
        score += eatCandy() ?: return score
    }

    return score
}

