data class CandyStat(
    val aTotal: Int = 0,
    val bTotal: Int = 0,
    val last: Int = 0,
    val forward: Boolean = true,
    val steps: Int = 0
)

fun f(candies: List<Int>): List<Int> {

    fun recur(list: List<Int>, stat: CandyStat): List<Int> {
        return when {
            list.isEmpty() -> {
                listOf(stat.steps, stat.aTotal, stat.bTotal)
            }
            stat.forward -> {
                val (newList, sum) = if (list.sum() <= stat.last) listOf<Int>() to list.sum()
                else {
                    var temp = listOf(list.first())
                    while (temp.sum() <= stat.last) {
                        temp = list.take(temp.size + 1)
                    }
                    list.drop(temp.size) to temp.sum()
                }

                recur(newList, stat.copy(
                    aTotal = stat.aTotal + sum,
                    forward = false,
                    steps = stat.steps + 1,
                    last = sum
                ))
            }
            else -> {
                val (newList, sum) = if (list.sum() <= stat.last) listOf<Int>() to list.sum()
                else {
                    var temp = listOf(list.last())
                    while (temp.sum() <= stat.last) {
                        temp = list.takeLast(temp.size + 1)
                    }
                    list.dropLast(temp.size) to temp.sum()
                }

                recur(newList, stat.copy(
                    bTotal = stat.bTotal + sum,
                    forward = true,
                    steps = stat.steps + 1,
                    last = sum
                ))
            }
        }
    }

    return recur(candies.drop(1), CandyStat(
        aTotal = candies.first(),
        last = candies.first(),
        steps = 1,
        forward = false
    ))
}

