data class Player(var lastValueEaten: Int = 0, var totalEaten: Int = 0){
    fun eatCandy(candyValue: Int){
        lastValueEaten += candyValue
        totalEaten += candyValue
    }
}

class Game(private var candies: List<Int>) {
    private var numberOfTurn: Int = 0
    private val alice = Player()
    private val bob = Player()

    private var lastPlayer = bob
    private var currentPlayer = alice

    fun play(): Game {
        while (candies.isNotEmpty()) {
            candies = candies.dropWhile { candyValue ->
                val res = currentPlayer.lastValueEaten <= lastPlayer.lastValueEaten

                if (res) { currentPlayer.eatCandy(candyValue) }

                res
            }

            prepareNextTurn()
        }

        return this
    }

    fun displayResult() = println("$numberOfTurn ${alice.totalEaten} ${bob.totalEaten}")

    private fun prepareNextTurn() {
        numberOfTurn++

        lastPlayer.lastValueEaten = 0

        val tmp = lastPlayer
        lastPlayer = currentPlayer
        currentPlayer = tmp

        candies = candies.reversed()
    }
}

