class Game(private var candies: List<Int>) {
    private var numberOfTurn: Int = 0
    private val alice = Player(index = 0)
    private val bob = Player(index = candies.lastIndex)

    private var lastPlayer = bob
    private var currentPlayer = alice

    fun play(): Game {
        while (alice.index <= bob.index) {
            while (currentPlayer.lastValueEaten <= lastPlayer.lastValueEaten && (alice.index <= bob.index)){
                currentPlayer.eatCandy(candies[currentPlayer.index])
                moveIndex()
            }

            prepareNextTurn()
        }

        return this
    }

    private fun moveIndex(){
        when(currentPlayer){
            alice -> currentPlayer.index++
            bob -> currentPlayer.index--
        }
    }

    fun displayResult() = println("$numberOfTurn ${alice.totalEaten} ${bob.totalEaten}")

    private fun prepareNextTurn() {
        numberOfTurn++

        lastPlayer.lastValueEaten = 0

        val tmp = lastPlayer
        lastPlayer = currentPlayer
        currentPlayer = tmp
    }
}

