fun candies(C: MutableList<Int>) {
    var moves = 0
    var aliceTot = 0
    var bobTot = 0
    var prev = 0
    var aOrB = true
    var curr : Int
    while (C.isNotEmpty()) {
        curr = 0
        do {
            if (aOrB) {
                curr += C.removeAt(0)
            } else {
                curr += C.removeAt(C.size - 1)
            }
        } while (curr <= prev && C.isNotEmpty())

        if (aOrB) {
            aliceTot += curr
        } else {
            bobTot += curr
        }

        prev = curr
        aOrB = !aOrB
        moves++
    }
    println("$moves $aliceTot $bobTot")
}

