fun solve(n: Int, arr: IntArray): Triple<Int, Int, Int> {
	val cumsum_1 = IntArray(n)
	val cumsum_2 = IntArray(n)
	cumsum_1[0] = arr[0]
	cumsum_2[n - 1] = arr[n - 1]
	for (i in 1..(n - 1)) {
		cumsum_1[i] = cumsum_1[i - 1] + arr[i]
		cumsum_2[n - 1 - i] = cumsum_2[n - i] + arr[n - 1 - i]
	}
	var a = 0
	var index_1 = -1
	var b = 0
	var index_2 = n
	var prv = 0
	var turn = 0
	while (index_2 - index_1 > 1) {
		turn += 1
		if (turn % 2 == 1) {
			val base = if (index_1 == -1) { 0 } else { cumsum_1[index_1] }
			val index = binary_search(prv + base, index_1 + 1, index_2 - 1, cumsum_1)
			if (index == null) {
				prv = cumsum_1[index_2 - 1] - base
				a += prv
				index_1 = index_2 - 1
			} else {
				prv = cumsum_1[index] - base
				a += prv
				index_1 = index
			}
		} else {
			val base = if (index_2 == n) { 0 } else { cumsum_2[index_2] }
			val index = binary_search(prv + base, index_2 - 1, index_1 + 1, cumsum_2)
			if (index == null) {
				prv = cumsum_2[index_1 + 1] - base
				b += prv
				index_2 = index_1 + 1
			} else {
				prv = cumsum_2[index] - base
				b += prv
				index_2 = index
			}
		}
	}
	return Triple(turn, a, b)
}

fun binary_search(x: Int, s: Int, e: Int, arr: IntArray): Int? {
	if (arr[e] <= x) {
		return null
	}
	if (arr[s] > x) {
		return sz
	}
	var l = s
	var r = e
	while (abs(r - l) > 1) {
		val mid = (l + r) / 2
		if (arr[mid] > x) {
			r = mid
		} else {
			l = mid
		}
	}
	return r
}

