fun solve(a: Int, b: MutableList<Int>) {
    var alice = 0
    var aliceSum = 0
    var bob = 0
    var bobSum = 0
    var rounds = 0
    var aliceRound = true
    while (b.size > 0) {
        when (aliceRound) {
            true -> {
                do {
                    alice += b.removeFirst()
                } while (alice <= bob && b.isNotEmpty())
                aliceSum += alice
                bob = 0
                aliceRound = false
                rounds++
            }
            false -> {
                do {
                    bob += b.removeLast()
                } while (bob <= alice && b.isNotEmpty())
                bobSum += bob
                alice = 0
                aliceRound = true
                rounds++
            }
        }
    }
    println("$rounds $aliceSum $bobSum")
}

