fun moveA(list: MutableList<Int>): MutableList<Int>{
    steps +=1
    return if(bMove == 0){
        aTotal += list[0]
        aMove = list[0]
        list.removeAt(0)
        list
    }
    else{
        var aValTemp = 0
        while(aValTemp <= bMove && list.size >=0){
            aValTemp += list[0]
            aTotal += list[0]
            list.removeFirst()
        }
        aMove = aValTemp
        list
    }
}
fun moveB(list: MutableList<Int>): MutableList<Int>{
    steps +=1
    var bValTemp = 0
    while(bValTemp <= aMove && list.size > 0){
        bValTemp += list[list.size - 1]
        bTotal += list[list.size - 1]
        list.removeLast()
    }
    bMove = bValTemp
    return list
}

