        if (cum >= k) break
        if (dnum < m && dnum < n) {
            ++nds
        } else if (dnum >= m){
            --nds
        }
        cum += nds
        ++dnum
    }
    cum -= nds

    val startl: Int; val startr: Int; val numiter: Int
    if (dnum <= m) {
        startl = 1
        startr = dnum
        numiter = min(n, dnum)
    } else {
        startl = dnum - m + 1
        startr = m
        numiter = min(m - (dnum - m), n - (dnum - m))
    }
    val arr = mutableListOf<Long>()
    for (i in 0..numiter-1) {
        arr.add((startl + i) * (startr - i).toLong())
    }
    arr.sort()
    val idx = k - cum -1
    bw.write("${arr[idx.toInt()]}\n")
    bw.close()
}

