val MOD: Long = 1000000000 + 7
var fibs: HashMap<Int, Long> = HashMap<Int, Long>()

fun countFib(n: Int): Long {
    if (fibs.containsKey(n)) {
        return fibs[n]!!
    }
    if (n <= 0) {
        fibs[n] = 1
        return 1
    }

    fibs[n] = countFib(n - 1) + countFib(n - 2)
    return fibs[n]!!
}

fun F(n: Int, m: Int) : Long {
    // n >= m
    if (m == 1) {
        return (countFib(n - 1) + countFib(n - 1)) % MOD
    }

    var ans: Long = 0
    ans = (ans + countFib(m - 3)) % MOD
    ans = (ans + countFib(n - 3)) % MOD
    for (i in 2 until n) {
        ans = (ans + countFib(n - i - 2)) % MOD
    }

    ans = (ans + countFib(m - 2)) % MOD
    return (ans + ans) % MOD
}

