fun tDepth(depth: Int, i: Int, k: Int): Int = if (i <= k) depth + i else depth - (i - k)

fun solve(k: Int, l: Int, ds: List<Int>): Boolean {
    val n = ds.size
    val w = 2*k
    var s = Array(w) { true }

    for (p in n-1 downTo 0) {
        val depth = ds[p]

        var ns = Array(w) { true }
        for (i in 0 until w) {
            ns[i] = tDepth(depth, i, k) <= l && (s[(i + 1) % w])
        }
        for (i in w-1 downTo 0) {
            ns[i] = ns[i] || (tDepth(depth, i, k) <= l && ns[(i + 1) % w])
        }

        s = ns
        if (debug) println("p=$p, s=${s.contentToString()}, depth=$depth")
    }

    return s.any { it }
}

