data class XOD(var x: Int, var d: Int) {
    operator fun plusAssign(xod: XOD) {
        x += xod.x
        d += xod.d
    }

    fun test() = x == 5 || (x == 4 && d == 1)
}

fun convert(board: Array<CharArray>, x: Int, y: Int) = when {
    x < 0 || 9 < x -> XOD(0, 0)
    y < 0 || 9 < y -> XOD(0, 0)
    else -> when (board[x][y]) {
        'X' -> XOD(1, 0)
        '.' -> XOD(0, 1)
        else -> XOD(0, 0)
    }
}

