enum class SetType {
    EMPTY,
    LINE,
    WHOLE_FIELD
}

typealias Line = Triple<Int, Int, Int>

fun Line.setType(): SetType {
    if (first == 0 && second == 0 && third == 0) return SetType.WHOLE_FIELD
    if (first == 0 && second == 0) return SetType.EMPTY
    return SetType.LINE
}

fun calcDet(line1: Line, line2: Line) = line1.first * line2.second - line1.second * line2.first

fun calcIntersections(line1: Line, line2: Line): Int {
    if (line1.setType() == SetType.EMPTY || line2.setType() == SetType.EMPTY) return 0
    if (line1.setType() == SetType.WHOLE_FIELD || line2.setType() == SetType.WHOLE_FIELD) return -1
    val det = calcDet(line1, line2)
    return if (calcDet(line1, line2) != 0) 1 else 0
}


