typealias DataInputStream = java.io.DataInputStream

internal class Reader {

    private val BUFFER_SIZE = 1 shl 16
    private val din: DataInputStream = DataInputStream(System.`in`)
    private val buffer: ByteArray = ByteArray(BUFFER_SIZE)
    private var bytesRead: Int = 0
    private var bufferPointer: Int = bytesRead

    private val stop: Byte = -1

    private fun read(): Byte {
        if (bufferPointer == bytesRead) {
            fillBuffer()
        }
        return buffer[bufferPointer++]
    }

    private fun fillBuffer() {
        bufferPointer = 0
        bytesRead = din.read(buffer, bufferPointer, BUFFER_SIZE)
        if (bytesRead == -1) {
            buffer[0] = stop
        }
    }

    fun nextLine(): String {
        val buf = ByteArray(64) // line length
        var cnt = 0
        var c: Byte
        do {
            c = read().takeUnless { it == '\n'.toByte() } ?: break
            buf[cnt++] = c
        } while (c != stop)

        return String(buf, 0, cnt)
    }

    fun nextInts(n: Int): IntArray {
        val arr = IntArray(n) { 0 }
        for (i in 0 until n) {
            arr[i] = nextInt()
        }
        return arr
    }

    fun nextInt(): Int {
        var ret = 0
        var c = read()
        while (c <= ' '.toByte()) c = read()
        val neg = c == '-'.toByte()
        if (neg) c = read()
        do {
            ret = ret * 10 + c - '0'.toInt()
            c = read()
        } while (c >= '0'.toByte() && c <= '9'.toByte())

        return if (neg) -ret else ret
    }

    fun nextLong(): Long {
        var ret = 0L
        var c = read()
        while (c <= ' '.toByte()) c = read()
        val neg = c == '-'.toByte()
        if (neg) c = read()
        do {
            ret = ret * 10 + c - '0'.toInt()
            c = read()
        } while (c >= '0'.toByte() && c <= '9'.toByte())

        return if (neg) -ret else ret
    }

    fun nextDouble(): Double {
        var ret = 0.0
        var div = 1.0
        var c = read()
        while (c <= ' '.toByte()) c = read()
        val neg = c == '-'.toByte()
        if (neg) c = read()
        do {
            ret = ret * 10 + c - '0'.toDouble()
            c = read()
        } while (c >= '0'.toByte() && c <= '9'.toByte())

        if (c == '.'.toByte()) {
            c = read()
            while (c >= '0'.toByte() && c <= '9'.toByte()) {
                div *= 10
                ret += (c - '0'.toByte()) / div
                c = read()
            }
        }

        return if (neg) -ret else ret
    }
}

