fun IntArray.shakeForMeBaby(): Int {
    var left = 0
    var right = min(this[1], this[2])
    while (left + 1 < right) {
        val mid = (left + right) / 2
        when {
            this[1] / mid + this[2] / mid < this[0] -> right = mid
            else -> left = mid
        }
    }
    return left
}

