        A[i] = (B[i-1] + C[i-1] + D[i-1])%p
        B[i] = (A[i-1] + C[i-1] + D[i-1])%p
        C[i] = (B[i-1] + A[i-1] + D[i-1])%p
        D[i] = (B[i-1] + C[i-1] + A[i-1])%p

    }
