fun num_paths(n : Int) : Long {
  val modulo = 1000000007L
  val path_count = Array(n + 1, {_ -> LongArray(4)})
  path_count[0][3] = 1L
  for (i in 0 .. (n - 1)) {
    val i_plus_1 = i + 1
    for (j in 0 .. 3) {
      for (k in 0 .. 3) {
        if (j == k) {
          // Do nothing ...
        } else {
          path_count[i_plus_1][j] = 
            (path_count[i_plus_1][j] + path_count[i][k]) % modulo
        }
      }
    }
  }
  return path_count[n][3]
}

