// red > blue > yellow exactly 1 is great christmas ornament
class ChristmasOrnament : ProblemSolver() {
    var totalRed: Int = 0
    var totalBlue: Int = 0
    var totalYellow: Int = 0

    fun input() {
        val args = mutableListOf<Ornament>()
        val ornaments = readLine()!!.split(" ").map { it.toInt() }
        totalYellow = ornaments[0]
        totalBlue = ornaments[1]
        totalRed = ornaments[2]
        args.add(Ornament(totalRed, 0))
        args.add(Ornament(totalRed, 1))
        args.add(Ornament(totalRed, 2))
        output(args)
    }

    fun output(args: List<Any>) {
        val ornaments = args.map { it as Ornament }
        val christmasOrnaments = decrease(ornaments[0], ornaments[1], ornaments[2])
        val totalOrnaments = christmasOrnaments.reduce { acc, i -> acc + i }
        println(totalOrnaments)
    }

    private fun decrease(red: Ornament, blue: Ornament, yellow: Ornament): List<Int> {
        return if (blue.get() <= totalBlue && yellow.get() <= totalYellow) listOf(red.get(), blue.get(), yellow.get())
        else decrease(
            Ornament(red.get() - 1, offset = 0),
            Ornament(blue.get() - 1, offset = 1),
            Ornament(yellow.get() - 1, offset = 2)
        )
    }
}

