fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val _k = sc.nextLong()
    if (_k >= n) {
        println(0)
        return
    }
    val k = _k.toInt()
    if (k == 0) {
        var ans = ModInt(1L)
        for (i in 1..n) {
            ans *= ModInt(i.toLong())
        }
        println(ans)
        return
    }
    val dp = Array(n + 1) { Array(k + 1) { ModInt(0) } }
    dp[0][0] = ModInt(2)
    for (i in 1..n) {
        for (j in 0..k) {
            if (j > i) break
            dp[i][j] = dp[i - 1][j] * ModInt(n - i + j + 1L)
            if (j != 0) {
                dp[i][j] += dp[i - 1][j - 1] * ModInt((i - j).toLong())
            }
        }
    }
    println(dp[n][k])
}

