fun readword(): String {
    val b = StringBuilder()
    var c: Int
    val space = ' '.toInt()
    c = `in`.read()
    while (c in 0..space)
        c = `in`.read()
    if (c < 0)
        return ""
    while (c > space.toInt()) {
        b.append(c.toChar())
        c = `in`.read()
    }
    return b.toString()
}

