import java.util.*

class Program {
    companion object {
        fun calculateSize(length: Long, width: Long, flagstoneSize: Long): Long {
            var flagstones: Long = 0
            flagstones += ((length / flagstoneSize) * (width / flagstoneSize))
            if (length % flagstoneSize > 0)
                flagstones += width / flagstoneSize
            if (width % flagstoneSize > 0)
                flagstones += length / flagstoneSize
            if ((length % flagstoneSize > 0) && (width % flagstoneSize > 0))
                flagstones += 1
            return flagstones
        }
    }
}

