}

private class Task {
    fun solve(input: InputReader, output: PrintWriter) {
        val m = input.nextLong()
        val n = input.nextLong()
        val a = input.nextLong()

        if (m % a == 0L && n % a == 0L) {
            output.print(m / a * n / a)
            return
        }

        var rowCount = 0L
        var collCount = 0L
        var sum = 0L

        while (sum < n || sum < m) {
            if (sum < m) rowCount++
            if (sum < n) collCount++
            sum += a
        }

        output.print(rowCount * collCount)
    }
}


