fun printLeastAndGreatest(l: List<Int>) {
    if (l.isEmpty()) {
        println("-1 -1")
        return
    }

    val theGreatest = l.toMutableList()
    val theLeast = l.toMutableList()

    for (i in theLeast.size-1 downTo 1) {
        if (theLeast[i] > 0) {
            val v = theLeast.removeAt(i)
            theLeast.add(0, v)
            break
        }
    }

    var pos = 1
    for (i in theLeast.size - 1 downTo 1) {
        val v = theLeast.removeAt(theLeast.size - 1)
        theLeast.add(pos, v)
        pos++
    }

