fun findSumToN_iterative(m: Int, s: Int) : List<Int> {
    var currentList = mutableListOf<Int>()
    while (currentList.sum() < s) {
        val totalLeft = s - currentList.sum()
        currentList.add(
            when{
                totalLeft > 9 -> 9
                else -> totalLeft
            }
        )
    }
    if (currentList.size > m) return emptyList<Int>()

    while (currentList.size < m) {
        currentList.add(0)
    }
    return currentList
}

fun findSumToN_recursive(m: Int, s: Int, numbersSoFar: List<Int>) : Unit {
    val currentTotal = numbersSoFar.sum()
    val nNumbers = numbersSoFar.size
    if (currentTotal > s || nNumbers > m)
        return
    else if (currentTotal == s) {
        var newNumbersSoFar = numbersSoFar.toMutableList()
        while (newNumbersSoFar.size < m) {
            newNumbersSoFar.add(0)
        }
        println(newNumbersSoFar)
    } else {
        val lastNum = if (numbersSoFar.isEmpty()) 9 else numbersSoFar.last()
        for (i in lastNum downTo 1) {
            val newNumbersSoFar = numbersSoFar.toMutableList()
            newNumbersSoFar.add(i)
            findSumToN_recursive(s, m, newNumbersSoFar)
        }
    }
}

