import java.io.*
import java.util.*

class C {
    fun solve(input : InputStream, output : OutputStream) {
        val reader = InputReader(BufferedInputStream(input))
        val writer = PrintWriter(BufferedOutputStream(output))

        val first = reader.next()
        val second = reader.next()

        writer.println(solve(first, second))

        writer.close()
    }

    fun solve(first : String, second : String) : String {
        val digits = Array(10, {_ -> 0})
        for (char in first) {
            digits[char - '0']++
        }
        return trySolve(digits, second, second.length - first.length, first.length == second.length)!!
    }

    fun trySolve(digits : Array<Int>, number : String, pos : Int, eq : Boolean) : String? {
        if (pos == number.length) {
            return ""
        }

        if (!eq) {
            for (x in (0..9).reversed()) {
                if (digits[x] > 0) {
                    digits[x]--
                    val result = trySolve(digits, number, pos + 1, eq)
                    digits[x]++
                    if (result == null) {
                        return result
                    }
                    return x.toString() + result
                }
            }
        }

        // try with the same number
        val current = number[pos] - '0'
        if (digits[current] > 0) {
            digits[current]--
            val result = trySolve(digits, number, pos + 1, eq)
            digits[current]++
            if (result != null) {
                return current.toString() + result
            }
        }

        // or try with lower
        for(x in (0 until current).reversed()) {
            if (digits[x] > 0) {
                digits[x]--
                val result = trySolve(digits, number, pos + 1, false)
                digits[x]++
                if (result == null) {
                    return result
                }
                return x.toString() + result
            }
        }

        // should never happen
        throw IllegalStateException()
    }

    private class InputReader(stream: InputStream) {
        var reader: BufferedReader
        var tokenizer: StringTokenizer? = null

        init {
            reader = BufferedReader(InputStreamReader(stream), 32768)
            tokenizer = null
        }

        operator fun next(): String {
            while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
                try {
                    tokenizer = StringTokenizer(reader.readLine())
                } catch (e: IOException) {
                    throw RuntimeException(e)
                }

            }
            return tokenizer!!.nextToken()
        }

        fun nextInt(): Int {
            return Integer.parseInt(next())
        }

        fun nextLong(): Long {
            return java.lang.Long.parseLong(next())
        }
    }
}

fun main(args : Array<String>) {
    C().solve(System.`in`, System.out)
}

import java.util.*

data class ArrayViewer(val pos: Int, val array: IntArray) {

    fun empty() = pos >= array.size
    fun head() = array[pos]
    fun tail() = ArrayViewer(pos + 1, array)

}

fun IntArray.viewer() = ArrayViewer(0, this)

fun main(args: Array<String>) = with(Scanner(System.`in`)) {

    val a = nextLine()!!.map { it.toInt() - '0'.toInt() }.toIntArray()
    val b = nextLine()!!.map { it.toInt() - '0'.toInt() }.toIntArray()

    val counts = countDigits(a)

    if (a.size < b.size) {
        print(maxPossible(counts).fold("") { str, digit ->
            str + digit.toString() })
        return
    } else {
        print(makeLess(counts, b.viewer())!!.fold("") {
                str, digit ->
            str + digit.toString() })
    }

}

fun makeLess(counter: IntArray, value: ArrayViewer): List<Int>? {
    if (value.empty()) {
        return List<Int>(0){0}
    }

    val digit = value.head()
    val rest = value.tail()

    if (counter[digit] != 0) {
        var counterWithout = counter
        counterWithout[digit] -= 1

        val other = makeLess(counterWithout, rest)
        if (other != null) {
            return List<Int>(1){digit} + other
        }

        counterWithout[digit] += 1
    }

    for (nextDigit in digit downTo 0) {
        if (counter[nextDigit] != 0) {
            var counterWithout = counter
            counterWithout[nextDigit] -= 1

            val other = maxPossible(counterWithout)
            return List<Int>(1){nextDigit} + other
        }
    }

    return null

}

fun maxPossible(counter: IntArray): List<Int> {
    var c = List<Int>(0) {0}

    for (digit in 9 downTo 0) {
        for (i in 1..counter[digit]) {
            c += digit
        }
    }

    return c
}

fun countDigits(array: IntArray): IntArray {
    var counter = IntArray(10){0}

    for (digit in array) {
        counter[digit] += 1
    }

    return counter
}

