    val zero = 9
    val MAX = 19
    val INF = 1e9.toInt()
    val dp = Array(N + 1){IntArray(MAX){INF} }
    dp[0][zero] = 0
    for (i in 0 until N) {
      val target = S[N - 1 - i] - '0'
      for (next in 0 until MAX) {
        for (pre in 0 until MAX) {
          if (dp[i][pre] == INF) continue
          val roll = abs((next - zero) + target) // この桁まで
          val rollback = abs(next - pre - roll) // 前の桁を戻す
          val cost = roll * (i + 1) + rollback * i
          dp[i + 1][next] = min(dp[i + 1][next], dp[i][pre] + cost)
        }
      }
    }
