import kotlin.math.min

val ones = ArrayList<Long>()

fun lowerBound(n: Long): Int{
    var(lo, hi) = 0 to ones.size - 1
    while(lo < hi){
        val mid = (lo + hi) / 2 + (lo + hi) % 2
        if(ones[mid] < n)
            lo = mid
        else
            hi = mid - 1
    }
    return lo
}

fun rec(n: Long): Long{
    when {
        n == 0L -> return 0L
        n <= 6L -> return n
        n <= 11L -> return 13 - n
    }
    val bs = lowerBound(n)
    if(ones[bs + 1] == n)
        return (bs + 2).toLong()
    var ans = Long.MAX_VALUE
    if(n - ones[bs] < n)
        ans = min(ans, rec(n - ones[bs]) + bs + 1)
    if(ones[bs + 1] - n < n)
        ans = min(ans, rec(ones[bs + 1] - n) + bs + 2)
    return ans
}

