private typealias Point = Pair<Long, Long>

private class B {
    var st = StringTokenizer("")
    val reader = BufferedReader(InputStreamReader(System.`in`))

    fun next(): String {
        while (!st.hasMoreTokens()) {
            st = StringTokenizer(reader.readLine())
        }
        return st.nextToken()
    }

    fun nextInt() = next().toInt()
    fun nextLong() = next().toLong()
    fun nextDouble() = next().toDouble()
    fun nextLongPair() = nextLong() to nextLong()


    class Walker(var cur: Point, var t: Long) {
        fun dist(p1: Point, p2: Point): Long = abs(p1.first - p2.first) + abs(p1.second - p2.second)

        var res = 0
        fun goNext(p: Point) {
            if (t >= 0) {
                t -= dist(cur, p)
                cur = p
            }
            if (t >= 0) res++
        }

        fun walk(points: List<Point>) = points.forEach { goNext(it) }
    }

    fun tryIndex(start: Point, points: List<Point>, t: Long, i: Int): Int {
        val left = points.slice(0 until i).reversed()
        val right = points.slice(i until points.size)
        var max = 0
        for (i in 0..right.size) {
            for (j in 0..left.size) {
                val w1 = Walker(start, t)
                w1.walk(right.take(i) + left.take(j))
                max = maxOf(w1.res, max)
                val w2 = Walker(start, t)
                w2.walk(left.take(j) + right.take(i))
                max = maxOf(w2.res, max)
            }
        }
        return max
    }

    fun run() {
        val seed = nextLongPair()
        val (ax, ay) = nextLongPair()
        val (bx, by) = nextLongPair()
        val points = generateSequence(seed) { (x, y) ->
            val nx = x * ax + bx
            val ny = y * ay + by
            if (nx > 3 * 1e16 || ny > 3 * 1e16) null else nx to ny
        }.toList()
        println(points)
        val start = nextLongPair()
        val t = nextLong()
        println((0..points.size).map { tryIndex(start, points, t, it) }.max())
    }
}

