fun qpowmod(ta:Long, tb:Long, mod:Long):Long {
	var a = ta
	var b = tb
	var res=1L
	while(b>0) {
		if(b%2==1L)
			res=res*a
		b/=2
		a=a*a%mod
	}
	return res
}

