data class GameResult(
        val moves: Int,
        val leftWeight: Int,
        val rightWeight: Int
)

fun game(sweets: MutableList<Int>): GameResult {
    var moves = 0
    var leftWeight = 0
    var rightWeight = 0

    while (sweets.isNotEmpty()) {
        leftWeight += eatLeft(rightWeight, sweets)
        moves++

        if (sweets.isEmpty())
            break

        rightWeight += eatRight(leftWeight, sweets)
        moves++
    }

    return GameResult(moves, leftWeight, rightWeight)
}

fun eatLeft(min: Int, sweets: MutableList<Int>): Int {
    var eaten = 0
    do {
        eaten += sweets.removeAt(0)
    } while (eaten < min && sweets.isNotEmpty())

    return eaten
}

fun eatRight(min: Int, sweets: MutableList<Int>): Int {
    var eaten = 0
    do {
        eaten += sweets.removeAt(sweets.size - 1)
    } while (eaten < min && sweets.isNotEmpty())

    return eaten

