import java.util.*

fun findMin(n: Int, sum: Int): String {

	if ( sum == 0 ) return if ( n == 1 ) "0" else "-1"
	if ( sum > 9*n ) return "-1"

	val firstDigit = Math.max(1, sum - 9*(n-1))
	var left = sum - firstDigit

	val r = StringBuilder()
	r.append ( firstDigit )
	for ( i in n-2 downTo 0 ) {
		val d = Math.max ( 0, left - 9*i )
		r.append(d)
		left -= d
	}

	return r.toString()
}

fun findMax(n: Int, sum: Int): String {

	if ( sum == 0 ) return if ( n == 1 ) "0" else "-1"
	if ( sum > 9*n ) return "-1"

	val firstDigit = Math.min(9, sum)
	var left = sum - firstDigit

	val r = StringBuilder()
	r.append(firstDigit)
	for ( i in n-2 downTo 0 ) {
		val d = Math.min( 9, left )
		r.append(d)
		left -= d
	}

	return r.toString()
}

