fun find (c:Array<Int>,W:Int):Long {
    if (W == 0) return 0
    val amount = Array(c.size){ max(1,W shr it) }
    val rem = amount.mapIndexed { index, m -> max(0,W - (m shl index)) }
    val ans = rem.mapIndexed { index,remain -> find(c,remain) + c[index]*amount[index].toLong() }
    return ans.min()!!
}

