fun search(l: Int, r: Int, n: Int, m: Long, a: LongArray): Int {
    if (l > r) {
        return -1
    }
    val x = (l + r) / 2
    if (check(x, n, m, a)) {
        val t = search(l, x - 1, n, m, a)
        return if (t != -1) t else x
    }
    return search(x + 1, r, n, m, a)
}

fun check(x: Int, n: Int, m: Long, a: LongArray): Boolean {
    val a1 = a.filter { it >= n / x }
    val n1 = a1.size
    val k1 = n1 / x
    val r1 = n1 % x
    val count = a1.sum() - x * k1 * (k1 - 1) / 2 - k1 * r1
    return count >= m
}


class InputReader(stream: InputStream) {
    private val reader = BufferedReader(InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer? = null

    operator fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        }
        return tokenizer!!.nextToken()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

    fun nextArrayInt(count: Int): IntArray {
        return nextArrayInt(0, count)
    }

    fun nextArrayInt(start: Int, count: Int): IntArray {
        val a = IntArray(start + count)
        for (i in start until start + count) {
            a[i] = nextInt()
        }
        return a
    }

    fun nextArrayLong(count: Int): LongArray {
        val a = LongArray(count)
        repeat(count) { a[it] = nextLong() }
        return a
    }
}

