fun binmult(a : Long, b : Long, m : Long) : Long {
    if (a == 0L)
        return 0

    if (a % 2 == 1L) {
        val prev = binmult(a - 1, b, m)
        return (prev + b) % m
    } else {
        val half = binmult(a / 2, b, m)
        return (half + half) % m
    }
}

fun binpow(a: Long, n: Long, mod: Long): Long {
    var a = a
    var n = n
    var res: Long = 1
    while (n > 0) {
        if (n and 1 == 1L) {
            res = binmult(res, a, mod)
            res %= mod
            n--
        } else {
            a = binmult(a, a, mod)
            a %= mod
            n = n shr 1
        }
    }
    return res % mod
}

inline fun phi(n: Int): Int {
    var n = n
    var result = n
    var i = 2
    while (i * i <= n) {
        if (n % i == 0) {
            while (n % i == 0)
                n /= i;
            result -= result / i
        }
        ++i
    }
    if (n > 1)
        result -= result / n
    return result
}

