fun solve(k: Int, s: String, t: String): Int {
    val c = s.toCharArray()
    var res = calc(c, t)

    for (i in 0 until k) {
        val first = c.indexOfFirst { it != t[0] }
        val last = c.indexOfLast { it != t[1] }

        if (first > -1 && last > -1) {
            val firstC = c[first]
            c[first] = t[0]
            val firstRes = calc(c, t)
            c[first] = firstC

            val lastC = c[last]
            c[last] = t[1]
            val lastRes = calc(c, t)
            c[last] = lastC

            if (firstRes > lastRes) {
                c[first] = t[0]
                res = maxOf(firstRes, res)
            } else {
                c[last] = t[1]
                res = maxOf(lastRes, res)
            }
            continue
        }
        if (first != -1) {
            c[first] = t[0]
            val firstRes = calc(c, t)
            res = maxOf(res, firstRes)
            continue
        }
        if (last != -1) {
            c[last] = t[1]
            val lastRes = calc(c, t)
            res = maxOf(res, lastRes)
            continue
        }
    }
    return res
}

fun calc(c: CharArray, t: String): Int {
    var res = 0
    for (i in c.indices) {
        if (c[i] == t[0]) {
            res += c.takeLast(c.size - i - 1).count { it == t[1] }
        }
    }
    return res
}

