fun solve(p: Int, s: String, t: String): Int {
    val c = s.toCharArray()
    var res = calc(c, t)
    var k = p
    while (k > 1) {
        var (left, right) = -1 to -1
        for (l in s.indices) {
            if (c[l] == t[0]) {
                continue
            }
            for (r in s.lastIndex downTo l + 1) {
                if (c[r] == t[1]) {
                    continue
                }
                val first = c[l]
                val last = c[r]
                c[l] = t[0]
                c[r] = t[1]
                val calc = calc(c, t)
                if (calc > res) {
                    res = calc
                    left = l
                    right = r
                }
                c[l] = first
                c[r] = last
            }
        }
        if (left > -1) {
            if (c[left] != t[0]) {
                c[left] = t[0]
                k--
            }
            if (c[right] != t[1]) {
                c[right] = t[1]
                k--
            }
        } else {
            break
        }
    }

    if (k > 0) {
        for (i in s.indices) {
            for (v in listOf(t[0], t[1])) {
                val prev = c[i]
                c[i] = v
                res = maxOf(res, calc(c, t))
                c[i] = prev
            }
        }
    }

    return res
}

fun calc(c: CharArray, t: String): Int {
    var res = 0
    for (i in c.indices) {
        if (c[i] == t[0]) {
            res += c.takeLast(c.size - i - 1).count { it == t[1] }
