const val INF = 99

fun solve() {

    val a = next().toCharArray().map { it.toInt() - 48 }
    val n = a.size - 1

    fun ans(x: Int, y: Int): Int {
        val xInd = a.lastIndexOf(x)
        val yInd = a.lastIndexOf(y)
        if (xInd == -1 || yInd == -1) {
            return INF
        }
        if (xInd == 0 && a[1] == 0) {
            return INF
        }

        return if (xInd < yInd) {
            (n - yInd) + (n-1 - xInd)
        } else {
            (n - yInd) + (n - xInd)
        }
    }

    fun ans00(): Int {
        val count0 = a.count { it == 0 }
        if (count0 < 2) {
            return INF
        }

        val yInd = a.lastIndexOf(0)
        val xInd = a.subList(0, yInd).lastIndexOf(0)

        return (n - yInd) + (n-1 - xInd)
    }

    val ans00 = ans00()
    val ans25 = ans(2 ,5)
    val ans50 = ans(5, 0)
    val ans75 = ans(7, 5)

    val ans = min(min(ans00, ans25), min(ans50, ans75))
    println(if (ans != INF) ans else -1)
}




