fun winPlaces(s: Int): List<Int> {
  val places = arrayListOf<Int>()
  var i = (s / 50) % 475
  for (j in 1..25) {
    i = (i * 96 + 42) % 475
    places.add(26 + i)
  }
  require(places.size == 25)
  return places
}

fun solve(input: InputReader, output: PrintWriter) {
  val p = input.nextInt()
  val x = input.nextInt()
  val y = input.nextInt()

  var losed = x
  while (losed >= y) {
    if (winPlaces(losed).contains(p)) {
      output.print(0)
      return
    }
    losed -= 50
  }


  var successfulBreaks = 1
  while (true) {
    val noFails = x + successfulBreaks * 100
    val oneFail = x + successfulBreaks * 100 - 50
    if (winPlaces(noFails).contains(p) || winPlaces(oneFail).contains(p)) {
      output.print(successfulBreaks)
      return
    }
    successfulBreaks += 1
  }
}

