import kotlin.math.sqrt

fun prime (n: Int): Boolean {
    if (n == 1 || n == 2 || n == 3) return true
    else {
        var isPrime = true
        var i = 2
        while (i <= sqrt(n.toFloat()).toInt() && isPrime) {
            if (n % i == 0) {
                isPrime = false
            } else {
                i++
            }
        }
        return isPrime
    }
}

