fun checkNeighborSame(str : String) : Int {

    var res = 0;
    var charArr = str.toCharArray()
    var arr = arrayListOf<Char>()
    for (i in 0..charArr.size-1){
        arr.add(charArr.get(i))
    }
    var i = 0
    while (i < arr.size-1){
        if(arr.get(i) == arr.get(i+1)) {
            arr.removeAt(i+1)
            res++
        }else
            i++
    }
    return res

}

