import java.util.*


fun main(args: Array<String>) {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val a = scanner.nextInt()
    val b = scanner.nextInt()
    val list = mutableListOf<Int>()
    while (scanner.hasNextInt()) {
        list.add(scanner.nextInt())
    }
    var first = 0
    var last = 0
    var sum = 0

    for (i in 0 until list.size / 2) {
        first = list[i]
        last = list[list.size - i - 1]
        sum += updateSum(first, last, a, b)
    }
    if (list[list.size / 2] == 2) {
        sum += minOf(a, b)
    }
    print(sum)

}

private fun updateSum(first: Int, last: Int, a: Int, b: Int): Int {
    var sum = 0
    if (first != 2 && last != 2 && first != last) {
        print(-1)
        System.exit(0)
    } else if (first == last && last == 2) {
        sum += minOf(a, b) * 2
    } else if (first == 2) {

        sum += if (last == 0) a else b
    } else if (last == 2) {
        sum += if (first == 0) a else b
    }
    return sum
}

