    while (++left < --right)
        sol += when {
            colors[left] != 2 && colors[right] != 2 && colors[left] != colors[right] -> return print(-1)
            colors[left] != 2 && colors[right] != 2 -> 0
            colors[left] == 2 && colors[right] == 2 -> min(whiteSuitCost, blackSuitCost)
            colors[left] == 0 || colors[right] == 0 -> whiteSuitCost
            else -> blackSuitCost
        }
    if (left == right && colors[left] == 2 && colors[right] == 2) sol += min(whiteSuitCost, blackSuitCost)
    print(sol)
}

