fun main(args: Array<String>) {
    val inputStream = System.`in`
    val outputStream = System.out
    val input = InputReader(inputStream)
    val output = PrintWriter(outputStream)
    val solver = Task()
    solver.solve(input, output)
    output.close()
}

private class Task {
    fun solve(input: InputReader, output: PrintWriter) {
        val allCount = input.nextInt()
        val nextRoundPlace = input.nextInt()

        val participants: MutableList<Int> = ArrayList()

        for (i in 0 until allCount) {
            participants.add(input.nextInt())
        }

        fun scanRight(): Int {
            val participantRating = participants[nextRoundPlace]
            var index = nextRoundPlace

            while (index < allCount && participants[index] == participantRating) {
                index++
            }

            return index
        }

        fun scanLeft(): Int {
            var index = nextRoundPlace

            while (index >= 0 && participants[index] == 0) {
                index--
            }

            return index + 1
        }

        val shouldScanRight = participants[nextRoundPlace] > 0

        output.print(if (shouldScanRight) scanRight() else scanLeft())
    }
}


private class InputReader(stream: InputStream) {
    private var reader: BufferedReader = BufferedReader(InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer? = null


    operator fun next(): String {
        while (tokenizer == null || tokenizer?.hasMoreTokens()?.not() == true) {
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        }
        return tokenizer!!.nextToken()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

}

