fun findStraight(cards: List<String>): Int {
    var straigth = 1
    val firstCard = cards[0]
    var numI = firstCard[0]!!.toInt()
    var typeI = firstCard[1]

    for (i in 1 until 3) {
        val card = cards[i]
        var numC = card[0]!!.toInt()
        val typeC = card[1]

        if (typeC == typeI) {
            if (numC == numI + 1) {
                straigth++
            } else if (numC == numI + 2) {
                return 2
            }
        }

        numI = numC
        typeI = typeC
    }
    return straigth

