fun main() {
    var hand = readLine()!!.split(" ").map { it[0] to it[1] }
    if (hand.distinct().size == 1) {
        // all equal
        println("0")
        return
    }

    // find a suit containing 2 or more cards. If this doesn't exist,
    // then we're out of luck anyway (and need 2 more cards)
    val suited = hand.groupBy { it.second }.filter { (suit,list) -> list.size > 1 }
    if (suited.size > 0) {
        val L = suited.values.first().map { it.first }.sorted() // only numbers
        if (L.size == 3 && L[0] == L[1] - 1 && L[1] == L[2] - 1) {
            // full street
            println("0")
            return
        }
        if (L.size == 3 && L[2] - L[1] <= 2) {
            // second pair close (identical is allowed as well)
            println("1")
            return
        }
        if (L.size == 2 && L[1] - L[0] <= 2) {
            // first pair close (identical is allowed as well)
            println("1")
            return
        }
    }
    println("2")
    return
}

