import kotlin.math.min
import kotlin.math.sqrt

fun main() {
    fun readLong() = readLine()!!.toLong()

    fun Long.factors(): MutableSet<Long> {
        val output = mutableSetOf<Long>()
        val endLoop = sqrt(this.toDouble()).toLong()
        for (i in 2L..min(endLoop, this - 1)) {
            if (this % i == 0L) {
                output.add(i)
                output.add(this / i)
            }
        }
        return output
    }

    val n = readLong()
    val factors = n.factors()
    val minFactor = factors.min()!!
    val toRemove = mutableSetOf<Long>()
    for (factor in factors)
        if (factor != minFactor) {
            var ff = factor
            while (ff % minFactor == 0L)
                ff /= minFactor
            if (ff == 1L) toRemove.add(factor)
        }
    factors.removeAll(toRemove)
    print(
        when {
            factors.isEmpty() -> n
            factors.size == 1 -> factors.first()
            else -> 1
        }
    )
}

