private fun readLn() = readLine()!! // string line
private fun readInt() = readLn().toInt() // single int
private fun readStrings() = readLn().split(" ") // list of strings
private fun readInts() = readStrings().map { it.toInt() } // list of ints

val ids = Array(410) { ArrayList<Int>() }
val adj = Array(410) { ArrayList<Int>() }
val mem = HashMap<Pair<Int, Int>, IntArray>()
val nex = HashMap<Pair<Int, Int>, ArrayList<IntArray>>()
var ops = 0
fun dfs(u: Int, p: Int = -1): IntArray {
    if (mem.containsKey(Pair(p, u))) {
        return mem[Pair(p, u)]!!
    }
    var ans = intArrayOf(0)
    var bes = ArrayList<IntArray>()
    for (v in adj[u]) {
        if (v == p) {
            bes.add(IntArray(0))
            continue
        }
        var t = dfs(v, u)
        var nAns = IntArray(ans.size + t.size - 1) { 1000000 }
        bes.add(IntArray(nAns.size))
        for (i in 0 until ans.size) {
            for (j in 0 until t.size) {
                ops++
                if (ans[i] + t[j] <= nAns[i + j]) {
                    nAns[i + j] = min(nAns[i + j], ans[i] + t[j])
                    bes[bes.size - 1][i + j] = j
                }
            }
        }
        ans = nAns
    }
    val ret = ans.toMutableList()
    ret.add(0, 1)
    val retArray = ret.toIntArray()
    mem[Pair(p, u)] = retArray
    nex[Pair(p, u)] = bes
    return retArray
}


fun build(u: Int, p: Int, k: Int, ans: ArrayList<Int>) {
    if (k == 0) return
    var kk = k - 1
    val bes = nex[Pair(p, u)]!!
    for(i in adj[u].size - 1 downTo  0) {
        val v = adj[u][i]
        if (v == p) continue
        val b = bes[i][kk]
        if (b == 0) {
            ans.add(ids[u][i])
        } else {
            build(v, u, b, ans)
            kk -= b
        }
    }
}

fun main() {
    val r = Random.Default
    val (N, K) = readInts()
    for (i in 0 until N - 1) {
        var (u, v) = readInts()
//        var (u, v) = intArrayOf(r.nextInt(i + 1) + 1, i + 2)
//        var (u, v) = intArrayOf(i + 1, i + 2)
        u--
        v--
        ids[u].add(i)
        ids[v].add(i)
        adj[u].add(v)
        adj[v].add(u)
    }
    for (i in 0 until N) {
        dfs(i)
    }
    val bn = (IntStream.range(0, N).boxed().min { a, b -> dfs(a)[K].compareTo(dfs(b)[K]) }).get()
    val ans = ArrayList<Int>()
    build(bn, -1, K, ans)
    ans.sort()
    println(ans.size)
    for (i in ans) {
        print(i + 1)
        print(" ")
    }
    println()

}

