class InputReader(stream: InputStream) {
  private val reader: BufferedReader = BufferedReader(InputStreamReader(stream), 32768)
  private var tokenizer: StringTokenizer?
  operator fun next(): String {
    while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
      tokenizer = try { StringTokenizer(reader.readLine()) }
      catch (e: IOException) { throw RuntimeException(e) }
    }
    return tokenizer!!.nextToken()
  }
  fun ll(): Long { return next().toLong() }
  fun int(): Int { return next().toInt() }
  init { tokenizer = null }
}

