fun findNextDistinct(input: Int): Int{
	var no = input +1;
	while(true){
		no+=1
		if(isDistinct(no)){
			return no
		}
	}
}

fun isDistinct(no: Int): Boolean{
	val set = hashSetOf<Int>()
	set.add(no % 10)
	set.add((no/10) % 10)
	set.add((no/100) % 10)
	set.add((no/1000) % 10)
	return set.size == 4
}

