fun main(args: Array<String>) {
    val onlineJudge = System.getProperty("ONLINE_JUDGE") == "true"
    val input = if (onlineJudge) System.`in`.bufferedReader() else File("input.txt").bufferedReader()
    val output = if (onlineJudge) PrintWriter(System.out.writer(), true) else PrintWriter(File("output.txt"))

    solve(input, output)

    output.flush()
    output.close()
}

private fun solve(input: BufferedReader, output: PrintWriter) {
    val (l1, r1, l2, r2, k) = input.readLine().split(" ").map { it.toInt() }

    val start = Math.max(l1, l2)
    val end = Math.min(r1, r2)

    val answer = when {
        start > end -> 0
        else -> (end - start + 1).let { if (k in start..end) it - 1 else it }
    }

    output.println(answer)
}

