class Solver(input: InputStream, output: OutputStream) {

    companion object {
        private const val MAX_N = (1e6 + 10).toInt()
        private const val INF = (1e9 + 7).toInt()
        private const val MOD = (1e9 + 7).toInt()
        private const val INF_F = 1e-6
    }

    private val reader = Reader(input)
    private val writer = Writer(output)

    fun solve() {
        val p1 = reader.readPoint()
        val p2 = reader.readPoint()
        val p1_1 = Point(p1.x, p2.y)
        val p2_1 = Point(p2.x, p1.y)

        val p3 = reader.readPoint()
        val p4 = reader.readPoint()
        val p5 = reader.readPoint()
        val p6 = reader.readPoint()

        when {
            !inRect(p3, p4, p1) && !inRect(p5, p6, p1)
                    || !inRect(p3, p4, p2) && !inRect(p5, p6, p2)
                    || !inRect(p3, p4, p1_1) && !inRect(p5, p6, p1_1)
                    || !inRect(p3, p4, p2_1) && !inRect(p5, p6, p2_1) -> writer.println("YES")
            p4.x < p5.x || p6.x < p3.x
                    || p4.y < p5.y || p6.y < p3.y -> writer.println("YES")
            else -> writer.println("NO")
        }
    }

    fun clear() {
        writer.close()
    }

    private fun Reader.readPoint() = Point(nextInt(), nextInt())

    private fun inRect(p1: Point, p2: Point, p: Point) =
            p.x in p1.x..p2.x && p.y in p1.y..p2.y

    data class Point(val x: Int, val y: Int)
}

private fun IntArray.gcd(): Int {
    var g = first()
    forEach { g = gcd(g, it) }
    return g
}

private fun LongArray.gcd(): Long {
    var g = first()
    forEach { g = gcd(g, it) }
    return g
}

private fun gcd(a: Int, b: Int): Int {
    return if (b == 0) a else gcd(b, a % b)
}

private fun gcd(a: Long, b: Long): Long {
    return if (b == 0L) a else gcd(b, a % b)
}

class Reader(input: InputStream) {
    private val reader = BufferedReader(InputStreamReader(BufferedInputStream(input)), 32768)
    private var tokenizer: StringTokenizer? = null

    fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }
        }
        return tokenizer!!.nextToken()
    }

    fun nextInt() = next().toInt()

    fun nextLong() = next().toLong()

    fun nextStringArray(count: Int): Array<String> {
        return Array<String>(count) { next() }
    }

    fun nextArrayInt(count: Int): IntArray {
        return nextArrayInt(0, count)
    }

    fun nextArrayInt(start: Int, count: Int): IntArray {
        val a = IntArray(start + count)
        for (i in start until start + count) {
            a[i] = nextInt()
        }
        return a
    }

    fun nextArrayLong(count: Int): LongArray {
        val a = LongArray(count)
        for (i in 0 until count) {
            a[i] = nextLong()
        }
        return a
    }

    fun nextIntPair(): Pair<Int, Int> {
        val x = nextInt()
        val y = nextInt()
        return x to y
    }
}

class Writer(output: OutputStream) {
    private val writer = PrintWriter(BufferedOutputStream(output))

    fun <T> print(t: T) = writer.print(t)
    fun println() = writer.println()
    fun <T> println(t: T) = writer.println(t)

    fun printBooleanArray(array: BooleanArray) = printIntArray(array.map { if (it) 1 else 0 }.toIntArray())
    fun printIntArray(array: IntArray) = array.joinToString(" ").let(writer::println)
    fun printLongArray(array: LongArray) = array.joinToString(" ").let(writer::println)
    fun printCharArray(array: CharArray) = array.joinToString("").let(writer::println)

    fun close() = writer.close()
    fun flush() = writer.flush()
}

