operator fun IntRange.contains(other: IntRange) = start <= other.start && endInclusive >= other.endInclusive

fun IntRange.coveredBy(_r1: IntRange, _r2: IntRange): Boolean {
    var r1 = _r1
    var r2 = _r2
    if(r1.start > r2.start) r1 = r2.also { r2 = r1 }
    return when(r1.endInclusive.compareTo(r2.start)) {
        -1 -> false
        0 -> this in r1.start..r2.endInclusive
        else -> this in r1.start..maxOf(r1.endInclusive, r2.endInclusive)
    }
}

