fun factorList(a: Int): MutableList<Int> {
    var a = a
    var b = 2
    val res = mutableListOf<Int>()
    while (b * b <= a) {
        if (a % b == 0) {
            res.add(b)
            a = a / b
            b = 2
        } else ++b
    }
    if (a > 1) res.add(a)
    return res
}

