class Main {
    internal class TaskA {
        fun solve(inp: InputReader, out: PrintWriter) {
            var a: Long = inp.nextInt().toLong()
            var b: Long = inp.nextInt().toLong()
            var c: Long = inp.nextInt().toLong()
            var d: Long = inp.nextInt().toLong()
            var e: Long = inp.nextInt().toLong()
            var f: Long = inp.nextInt().toLong()
            var ans = 0L
            if (e >= f) {
                val min = minOf(a, d)
                ans += min * e
                d -= min
            }
            if (d > 0) {
                val min = minOf(b, c, d)
                ans += min * f
                d -= min
            }
            if (d > 0)
                ans += minOf(a, d) * e
            out.println(ans)
        }
    }

    internal class InputReader(stream: InputStream) {
        private var reader: BufferedReader = BufferedReader(InputStreamReader(stream), 32768)
        private var tokenizer: StringTokenizer? = null

        init {
            tokenizer = null
        }

        operator fun next(): String {
            while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
                try {
                    tokenizer = StringTokenizer(reader.readLine())
                } catch (e: IOException) {
                    throw RuntimeException(e)
                }
            }
            return tokenizer!!.nextToken()
        }

        fun nextInt(): Int {
            return Integer.parseInt(next())
        }
    }
}

