import kotlin.math.max

data class Input(val a: Int, val b: Int, val c: Int, val d: Int,
                 val firstTypeCost: Int, val secondTypeCost: Int)

class Memoized {
    val mem = mutableMapOf<Input, Int>()

    fun getMaxTotalCost(input: Input): Int {
        if (mem.containsKey(input))
            return mem[input]!!

        var firstCost = 0
        var secondCost = 0

        val (a, b, c, d, firstTypeCost, secondTypeCost) =
            input

        if (a>0 && d>0) {
            firstCost = firstTypeCost + getMaxTotalCost(Input(a-1, b, c, d-1,
                firstTypeCost, secondTypeCost))
        }

        if (b>0 && c>0 && d>0) {
            secondCost = secondTypeCost + getMaxTotalCost(Input(a, b-1, c-1, d-1,
                firstTypeCost, secondTypeCost))
        }

        mem[input] = max(firstCost, secondCost)
        return mem[input]!!
    }
}

