object programkt {
    internal class FastScanner(inpStr: InputStream, var br: BufferedReader = BufferedReader(InputStreamReader(inpStr)), var stok: StringTokenizer? = null){
        fun nextToken(): String? {
            while (stok == null || !stok!!.hasMoreTokens()) {
                val s = br.readLine() ?: return null
                stok = StringTokenizer(s)
            }
            return stok!!.nextToken()
        }

        fun nextInt() = nextToken()!!.toInt()
        fun nextLong() = nextToken()!!.toLong()
        fun nextDouble() = nextToken()!!.toDouble()
        fun nextChar() = br.read().toChar()
        fun nextLine() = br.readLine()
        fun nextBigInteger() = BigInteger(nextToken()!!)
        fun nextBigDecimal() = BigDecimal(nextToken()!!)
    }

    @JvmStatic fun main(args: Array<String>) {
        val scanner = FastScanner(System.`in`)
        val str = scanner.nextLine()

        var cnt = 0
