tailrec fun subtract(num: Int, times: Int): Int {
    if(times == 0)
        return num

    if(num % 10 == 0) {
        return subtract(num/10, times.minus(1))
    } else {
        return subtract(num.minus(1), times.minus(1))
    }
}

