    var bb1 = b1
    var bb2 = b2
    var bb3 = b3

    val max = Math.min(aa1, bb2) + Math.min(aa2, bb3) + Math.min(aa3, bb1)

    IO.write("${Math.max(0, aa1 - bb1 - bb3) + Math.min(0, aa2 - bb1 - bb2) + Math.min(0, aa3 - bb2 - bb3)} $max")

    IO.flushOutput()
    IO.closeOutput()
}

fun factorize(n: Int, primes: MutableList<Int>): MutableList<Pair<Int, Int>> {
    val factors = mutableListOf<Pair<Int, Int>>()
    var nn = n
    primes.forEach {
        var power = 0
        while (nn % it == 0) {
            nn /= it
            power++
        }
        if (power != 0) {
            factors.add(Pair(it, power))
        }
    }
    if (nn != 1) {
        factors.add(Pair(nn, 1))
    }
    return factors
}


fun generateDivisors(index: Int, factors: MutableList<Pair<Int, Int>>): List<Int> {
    if (index == factors.size - 1) {
        var cur = 1
        val list = mutableListOf<Int>()
        for (i in 0 until factors[index].second + 1) {
            list.add(cur)
            cur *= factors[index].first
        }
        return list
    }
    val list = generateDivisors(index + 1, factors)
    val newList = mutableListOf<Int>()
    var cur = 1
    for (i in 0 until factors[index].second + 1) {
        list.forEach {
            newList.add(it * cur)
        }
        cur *= factors[index].first
    }
    return newList
}


class ArrayUtils {

    fun lowerBound(arr: Array<Int>, value: Int): Int {
        val pos = arr.binarySearch(value)
        if (pos < 0) return -1 * pos - 1
        var low = 0
        var high = arr.size
        while (low < high) {
            val middle = low + (high - low) / 2
            if (value > arr[middle]) {
                low = middle + 1
            } else {
                high = middle
            }
        }
        return low
    }
}

class InputReader(private val stream: InputStream) {
    private val buf = ByteArray(1024)
    private var curChar: Int = 0
    private var numChars: Int = 0
    private val filter: SpaceCharFilter? = null

    fun read(): Int {
        if (numChars == -1)
            throw InputMismatchException()
        if (curChar >= numChars) {
            curChar = 0
            try {
                numChars = stream.read(buf)
            } catch (e: IOException) {
                throw InputMismatchException()
            }

            if (numChars <= 0)
                return -1
        }
        return buf[curChar++].toInt()
    }

    fun readInt(): Int {
        var c = read()
        while (isSpaceChar(c))
            c = read()
        var sgn = 1
        if (c == '-'.toInt()) {
            sgn = -1
            c = read()
        }
        var res = 0
        do {
            if (c < '0'.toInt() || c > '9'.toInt())
                throw InputMismatchException()
            res *= 10
            res += c - '0'.toInt()
            c = read()
        } while (!isSpaceChar(c))
        return res * sgn
    }

    fun readLong(): Long {
        var c = read()
        while (isSpaceChar(c)) {
            c = read()
        }
        var sgn: Long = 1
        if (c == '-'.toInt()) {
            sgn = -1
            c = read()
        }
        var number: Long = 0
        do {
            number *= 10L
            number += (c - '0'.toInt()).toLong()
            c = read()
        } while (!isSpaceChar(c))
        return number * sgn
    }

    fun readString(): String {
        var c = read()
        while (isSpaceChar(c))
            c = read()
        val res = StringBuilder()
        do {
            res.appendCodePoint(c)
            c = read()
        } while (!isSpaceChar(c))
        return res.toString()
    }

    fun isSpaceChar(c: Int): Boolean {
        return filter?.isSpaceChar(c)
                ?: (c == ' '.toInt() || c == '\n'.toInt() || c == '\r'.toInt() || c == '\t'.toInt() || c == -1)
    }

    operator fun next(): String {
        return readString()
    }

    interface SpaceCharFilter {
        fun isSpaceChar(ch: Int): Boolean
    }
}

