class FF(val n: Int) {

	var adj = Array(n){ IntArray(n) }
	var seen = BooleanArray(n)

	fun add(u: Int, v: Int, cap: Int) {
		adj[u][v] += cap
	}

	fun dfs(u: Int, low: Int, t: Int): Int {
		if (u == t)
			return low

		seen[u] = true;

		for (v in 0..n-1) {
			if (adj[u][v] != 0 && !seen[v]) {
				var flow = dfs(v, min(adj[u][v], low), t)

				if (flow > 0) {
					adj[u][v] -= flow
					adj[v][u] += flow
					seen[u] = false
					return flow
				}
			}
		}

		seen[u] = false
		return 0
	}

	fun flow(s: Int, t: Int): Int {
		var flow = 0

		while (true) {
			var here = dfs(s, 100000000, t)
			if (here == 0)
				break
			flow += here
		}

		return flow
	}
}

