fun solve(a: Int, b: Int, c: Int, d: Int): Long {
    var res = 0L
    for (k in a + b..b + c) {
        val k0 = k - a - b
        val t = min(k0, b - a) + min(k0, c - b) - k0 + 1
        if (t > 0)
            if (k > d) {
                res += t * (d - c + 1)
            } else if (k > c) {
                res += t * (k - c)
            }
    }
    return res;
}


