fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
    val percent = ModInt(100).inverse()

    val n = readInt()
    val pipes = List(n) { Pipe(readInt(), readInt(), percent * readInt()) }

    val tree = SegmentTree(n-1, null, nullIdentityCombiner(Seg::plus))

    tree.build { i ->
        Seg(
            ll = pipes[i].p.not() * pipes[i+1].p.not(),
            lr = pipes[i].p.not() * pipes[i+1].p,
            rl = pipes[i].p * pipes[i+1].p.not(),
            rr = pipes[i].p * pipes[i+1].p
        )
    }

    val cols = ArrayList<Collision>(2*n)

    for(i in 0 until n-1) {
        val a = pipes[i]
        val b = pipes[i+1]

        val d = b.x - a.x
        cols.add(Collision(i, RL, d, a.v + b.v))
        if(a.v > b.v) cols.add(Collision(i, RR, d, a.v - b.v))
        else if(a.v < b.v) cols.add(Collision(i, LL, d, b.v - a.v))
    }

    cols.sortWith(Collision.comparator)

    var currProb = ModInt(1)
    var ans = ModInt(0)
    for((a, t, d, v) in cols) {
        tree[a] = tree[a]!!.ban(t)
        val prob = tree[0, tree.size]!!.sum
        ans += (currProb - prob) * d / v
        currProb = prob
    }

    println(ans.int)
}

