private fun solve(scanner: Scanner, out: PrintWriter) {
    var first = scanner.nextInt()
    var second = scanner.nextInt()

    var totalTime = 0

    while (first > 0 && second > 0) {
        if (first > second) {
            first -= 2
            second++
        } else {
            second -= 2
            first++
        }
        totalTime++
    }
    out.println(totalTime)
}

