fun getMaximumLength(aStrCount: Long, bStrCount: Long, abStrCount: Long): Long {

    if (aStrCount == bStrCount) {
        return aStrCount + bStrCount + (abStrCount * 2)
    }

    return if (aStrCount > bStrCount) {
        val restOfA = aStrCount - bStrCount

        if (restOfA < abStrCount) {
            (aStrCount - bStrCount) + bStrCount + (abStrCount * 2) + (abStrCount - restOfA)
        } else {
            (aStrCount - bStrCount) + bStrCount + (abStrCount * 2) + (restOfA - abStrCount)
        }
    } else {

        (aStrCount * 2) + 1 + (abStrCount * 2)
    }
}

