            cost += ps
        } else {
            needC = true
            cost += pc
        }
    }

    if (needB) {
        r += nb * pb
    }
    if (needS) {
        r += ns * ps
    }
    if (needC) {
        r += nc * pc
    }

    val ans = r / cost
    println(ans)
}

