val M = 1000000007L
val N = 100005
var fact = LongArray(N)
var ifact = LongArray(N)
var t = 0


fun main(args : Array<String>) {
    val (n, m, g) = readLine().toString().split(' ').map { it.toInt() }
    t = g
    init()

    // case when there are no ones
    if (m == 0) {
        val res = if (ok(n)) 1 else 0
        println(res)
        return
    }

    var ans = 0L
    // number of zeroes before first one position
    for (i in 0..n) {
        var k = ok(i + 1)
        if (m == 1 && i == n) k = ok(i)
        if (!k) continue
        ans = (ans + C(n - i + m - 1, m - 1)) % M
    }
    println(ans)
}

fun init() {
    fact[0] = 1L
    ifact[0] = 1L
    for (i in 1..(N - 1)) {
        fact[i] = (fact[i - 1] * i) % M
        ifact[i] = binpow(fact[i], M - 2)
    }
}

fun binpow(n : Long, deg : Long) : Long {
    if (deg == 0L) return 1L
    return if (deg % 2L == 1L) {
        n * binpow(n, deg - 1) % M
    } else {
        val b = binpow(n, deg / 2L)
        b * b % M
    }
}

fun C(n : Int, k : Int) : Long {
    return if (n < k) 0
    else fact[n] * ifact[k] % M * ifact[n - k] % M
}

fun ok(zeroes : Int) = (1 - zeroes % 2 == t)

fun fastPow(a: Long, b: Long): Long {
    if (b==0L)
        return 1

    if (b==1L)
        return a

    if (b%2==0L)
        return fastPow((a*a)%1000000007, b/2)

    return a*fastPow(a, b-1)%1000000007
}

