class Node constructor(var key: Int) {
    var prior: Int = 0
    var cnt: Int = 0
    var pushing: Boolean = false
    var left: Node? = null
    var right: Node? = null

    init {
        this.prior = rnd.nextInt()
        right = null
        left = right
        this.cnt = 1
        this.pushing = false
    }
}

private var out: PrintWriter = PrintWriter(System.out);

private val rnd = Random()

fun getCnt(t: Node?): Int {
    return t?.cnt ?: 0
}

fun update(t: Node?) {
    if (t != null) {
        t.cnt = 1 + getCnt(t.left) + getCnt(t.right)
    }
}

fun push(t: Node?) {
    if (t != null && t.pushing) {

        t.pushing = false
    }
}

fun pushAll(t: Node?) {
    if (t != null) {
        push(t)
        if (t.left != null) {
            pushAll(t.left)
        }
        if (t.right != null) {
            pushAll(t.right)
        }
    }
}

// [0,K),[K,N)
fun split(t: Node?, key: Int): Pair<Node?, Node?> {
    if (t == null) return Pair(null, null)
    push(t)
    if (key > t.key) {
        val p = split(t.right, key)
        t.right = p.first
        update(t)
        return Pair(t, p.second)
    } else {
        val p = split(t.left, key)
        t.left = p.second
        update(t)
        return Pair(p.first, t)
    }
}

//SPLIT ПО НЕЯВНОМУ КЛЮЧУ
// [0,K),[K,N)
fun split(t: Node?, key: Int, add: Int = 0): Pair<Node?, Node?> {
    if (t == null) return Pair(null, null);
    push(t)
    val curKey = add + getCnt(t.left)
    if (key > curKey) { //идем в правое поддерево
        val p = split(t.right, key, curKey + 1)
        t.right = p.first
        update(t)
        return Pair(t, p.second)
    } else { //идем в левое поддерево
        val p = split(t.left, key, add)
        t.left = p.second
        update(t)
        return Pair(p.first, t)
    }
}

//Все ключи в первом дереве должны быть меньше ключей во втором
fun merge(t1: Node?, t2: Node?): Node? {
    push(t1)
    push(t2)
    if (t1 == null) return t2
    if (t2 == null) return t1
    if (t1.prior > t2.prior) {
        t1.right = merge(t1.right, t2)
        update(t1)
        return t1
    } else {
        t2.left = merge(t1, t2.left)
        update(t2)
        return t2
    }
}

fun insert(t: Node?, newNode: Node): Node? {
    var t = t
    push(t)
    if (t == null) {
        t = newNode
    } else {
        val p = split(t, newNode.key, 0)
        t = merge(p.first, newNode)
        t = merge(t, p.second)
    }
    update(t)
    return t
}

//Объединяет 2 разных дерева
fun unite(t1: Node?, t2: Node?): Node? {
    var t1 = t1
    var t2 = t2
    if (t1 == null) return t2
    if (t2 == null) return t1
    push(t1)
    push(t2)
    if (t1.prior < t2.prior) {
        val c = t1
        t1 = t2
        t2 = c
    }
    val split1 = split(t2, t1.key)
    t1.left = unite(t1.left, split1.first)
    t1.right = unite(t1.right, split1.second)
    return t1
}

fun remove(t: Node?, key: Int): Node? {
    var t: Node? = t ?: return null
    if (t!!.key == key) {
        t = merge(t.left, t.right)
    } else {
        if (key < t.key) {
            t.left = remove(t.left, key)
        } else {
            t.right = remove(t.right, key)
        }
    }
    update(t)
    return t
}

fun find(t: Node?, key: Int): Node? {
    push(t)
    if (t == null) return null
    if (t.key == key) return t
    return if (t.key < key) {
        find(t.right, key)
    } else {
        find(t.left, key)
    }
}

fun get(t: Node?, key: Int, add: Int = 0): Node? {
    push(t)
    if (t == null) return null
    val curKey = add + getCnt(t.left)
    if (curKey == key) return t
    return if (key > curKey) { //идем в правое поддерево
        get(t.right, key, curKey + 1)
    } else {
        get(t.left, key, add)
    }
}

/**
 * Вырезает отрезок от i до j и вставляет в позицию k нового массива
 * (при k = 0 вставляет вначало)
 *
 * @param t Корень дерева
 * @param i Начало отрезка (включительно)
 * @param j Конец отрезка (включительно)
 * @param k Позиция вставки
 * @return Новое дерево
 */
fun replaceSegment(t: Node, i: Int, j: Int, k: Int): Node? {
    //Вырезаем отрезок и склеиваем
    val split1 = split(t, i, 0)
    val split2 = split(split1.second, j - i + 1, 0)
    val merge1 = merge(split1.first, split2.second)
    val removedSegment = split2.first

    //      out.println("Array without removed:" + getString(merge1));
    //      out.println("Removed Segment:" + getString(removedSegment));

    //разделяем и вставляем
    val split3 = split(merge1, k, 0)
    val merge2 = merge(split3.first, removedSegment)

    return merge(merge2, split3.second)
}

