        adj[u].add(Pair(v, i))
        adj[v].add(Pair(u, i))
    }
    DP(1, 0)
    var best = -1
    var bestAns = MutableList<Int>(402) {-1}
    for (i in 1..n) {
        if (dp[i][k] == -1) continue
        if (best == -1 || best > dp[i][k]) {
            best = dp[i][k]
            bestAns = dpAns[i][k]
        }
