}

fun readLn(): String = readLine()!!
fun readInt(): Int = readLn().toInt()
fun readInts(): MutableList<Int> = readLn().split(" ").map { it.toInt() }.toMutableList()

typealias Vertex = Int
typealias Index = Int
typealias Vertices = Int
data class Edge(val index: Index, val dst: Vertex)
typealias Graph = MutableMap<Vertex, MutableList<Edge>>
typealias Solution = List<Index>
typealias Results = MutableMap<Vertices, Solution>
typealias ResultsMap = MutableMap<Vertex, Results>

val visited = mutableMapOf<Int, Boolean>()
val graph: Graph = mutableMapOf()
val results: ResultsMap = mutableMapOf()
// val fatherEdge = mutableMapOf<Vertex, Index>()

fun applyIfBetter(next: Results, newVertices: Vertices, newConflicts: Solution) {
    if (newVertices !in next) {
        next[newVertices] = newConflicts
    } else {
        val oldConflictsSize = next[newVertices]!!.size
        if (oldConflictsSize > newConflicts.size) {
            next[newVertices] = newConflicts
        }
    }
}

fun dfs(u: Int) {
    visited[u] = true
    val children = graph[u]!!.filterNot { visited[it.dst]!! }
    children.forEach { dfs(it.dst) }
    val res: Results = mutableMapOf()
    res[1] = children.map { it.index }
    children.forEach { child ->
        // fatherEdge[child]
        val next: Results = mutableMapOf()
        val childResults = results[child.dst]!!
        for ((vertices, conflicts) in res.entries) {
            for ((childVertices, childConflicts) in childResults.entries) {
                val newVertices = vertices + childVertices
                val newConflicts = childConflicts + conflicts - child.index
                // println("$u $newVertices $newConflicts")
                applyIfBetter(next, newVertices, newConflicts)
            }
        }
        for ((nextVertices, nextConflicts) in next.entries) {
            applyIfBetter(res, nextVertices, nextConflicts)
        }
        // println(next)
    }
    results[u] = res
}

fun solve(n: Int, k: Int): Solution {
    val root = 1
    dfs(root)
    // println(results)
    var best: Solution? = null
    for (res in listOf(results[root]!!)) {
        if (k in res) {
            val potentialBest = res[k]!!
            if (best == null || best!!.size > potentialBest.size) {
                best = potentialBest
            }
        }
    }
    return best ?: listOf()
}

fun main(args: Array<String>) {
    val (n, k) = readInts()
    (1..n).forEach {
        graph[it] = mutableListOf<Edge>()
        visited[it] = false
    }
    for (index in 1 until n) {
        val (u, v) = readInts()
        graph.getValue(u).add(Edge(index, v))
        graph.getValue(v).add(Edge(index, u))
    }
    val solution = solve(n, k)
    println("${solution.size}")
    println(solution.joinToString(" "))
}

