class TaskC : Solver() {
    override fun solve() {
        val n = scanner.nextInt()
        val ls = scanner.getIntArray(n)
        val rs = scanner.getIntArray(n)

        val ans = IntArray(n)
        var cur = n
        val visited = BooleanArray(n)
        val touched = BooleanArray(n)
        var count = 0
        while (count < n) {
            var found = false
            touched.fill(false)
            for (i in 0 until n) {
                if (!visited[i] && ls[i] == 0 && rs[i] == 0 && !touched[i]) {
                    found = true
                    ans[i] = cur
                    visited[i] = true
                    count++
                    for (j in 0 until n) {
                        if (j < i) {
                            if (rs[j] > 0) {
                                rs[j]--
                                touched[j] = true
                            }
                        }
                        if (j > i) {
                            if (ls[j] > 0) {
                                ls[j]--
                                touched[j] = true
                            }
                        }
                    }
                }
            }
            if (!found) {
                System.out.print("NO")
                return
            }
            cur--
        }

        System.out.println("YES")
        for (i in ans) {
            System.out.print("$i ")
        }

    }
}

