private class `CF9-D2-A` {
    fun solveTestCase(): String {
        val max = max(readInt(), readInt())
        val prob = (6.0 - max + 1.0) / 6.0
        var numerator: Double = prob
        var denominator = 1

        while(numerator % 10.0 != 0.0) {
            numerator *= 10
            denominator *= 10
        }

        var common = gdc(numerator.toInt(), denominator)
        numerator /= common
        denominator /= common
        return  "${numerator.toInt()}/$denominator"
    }

    fun gdc(a: Int, b :Int) : Int{
        if (a == 0) return b
        if (b == 0) return a
        return gdc(b, a%b)
    }
}

