    val size= chars.size
    val middle = (size - 1) / 2

    var j = size - 1
    var i = 0
    var counter = 1

    var palindrom = true
    while(true){
        val begin =  chars[i]
        val end = chars[j]
        if(begin != end){
            if (counter == 0){
                palindrom = false
                break
            }
            counter--
        }
        if (i == middle){
            break
        }
        i++
        j--
    }
    if(palindrom && counter == 0){
        println("YES")
    } else {
        println("NO")
    }
}

