/**
 * Consumes a size n and then reads n integers into an array.
 */
fun Scanner.nextIntArray(size: Int = -1): IntArray {
    val array = IntArray(if(size > 0) size else nextInt())
    for(i in array.indices){
        array[i] = nextInt()
    }
    return array
}

/**
 * Consumes a number n and then executes the given consumer n times.
 */
fun Scanner.testCases(forEach: Scanner.() -> Unit) {
    val n = nextInt()
    for(i in 1..n){
        forEach(this)
    }
}

