fun handleQ(scan: Scanner) {
    val n = scan.nextInt()
    var listR = ArrayList<Int>()
    var listB = ArrayList<Int>()

    for (i in 1..n) listR.add(scan.nextInt())
    for (i in 1..n) listB.add(scan.nextInt())

    var sumR = 0
    var sumB = 1
    for(i in 0 until n) {
        if(listB[i] == 1 && listR[i] == 0) sumB++;
        if(listR[i] == 1 && listB[i] == 0) sumR++;
    }

    if(sumR == 0) {
        println(-1)
        return
    }

    var res: Int = floor(1.0*sumB/sumR).toInt()
    println(res)
}

