fun solve(r: List<Int>, b: List<Int>): Int {
    var rWins = 0.0
    var bWins = 0.0

    r.zip(b).asSequence().filter { it.first != it.second }.forEach {
        if (it.first == 1) {
            rWins += 1
        } else {
            bWins += 1
        }
    }

    return if (rWins == bWins || rWins == 0.0) {
        when {
            rWins == 0.0 -> {
                -1
            }
            bWins < b.size-1 -> {
                2
            }
            else -> {
                -1
            }
        }
    } else {
        ceil((bWins + 1) / rWins).toInt()
    }
}

