const val mod = 998244353

// Return Pair(Fn, Fn+1)
fun fib(n: Int): Pair<Long, Long> {

    // Base case.
    if (n == 0) return Pair(0, 1)

    val (x, y) = fib(n shr 1)
    val c = (x * (2 * y - x)) % mod
    val d = (y * y + x * x) % mod
    return if (n % 2 == 0) Pair(c, d) else Pair(d, d + c)
}

fun exp(x: Long, p: Long): Long {
    val base = x
    var exp = p
    var time = base
    var res = 1L
    while (exp > 0) {
        if (exp % 2 == 1L) {
            res = res * time % mod
        }
        time = time * time % mod
        exp /= 2
    }
    return res
}

