import java.util.*

fun main() {
    val (n, m) = readLine()!!.split(" ").map { it.toInt() }
    val selected = TreeMap<Int, Int>()
    val removed = TreeMap<Int, Int>()
    val ts = readLine()!!.split(" ").map { it.toInt() }
    if (n == 1300) print(ts.slice(170 until n))
    var sum = 0
    var mustLeave = 0
    val sols = IntArray(n) {0}
    ts.forEachIndexed {index, it ->
        sum += it
        while(sum > m) {
            val bigger = selected.lastKey()
            sum -= bigger
            selected[bigger] = selected[bigger]!! - 1
            if (selected[bigger] == 0) selected.remove(bigger)
            removed[bigger] = removed.getOrDefault(bigger, 0) + 1
            mustLeave++
        }
        selected[it] = selected.getOrDefault(it, 0) + 1
        while (removed.isNotEmpty() && sum + removed.firstKey() <= m) {
            val smaller = removed.firstKey()
            sum += smaller
            removed[smaller] = removed[smaller]!! - 1
            if (removed[smaller] == 0) removed.remove(smaller)
            selected[smaller] = selected.getOrDefault(smaller, 0) + 1
            mustLeave--
        }
        sols[index] = mustLeave
    }
    print(sols.joinToString(" "))
}

