tailrec fun gcd(a: Long, b: Long): Long {
  if (a < b) return gcd(b, a)
  if (b == 0L) return a
  return gcd(b, a % b)
}
class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val T = nl()
    val A = nl()
    val B = nl()

    fun answer(x: Long) {
      val d = gcd(x - 1, T)
      out.println("${(x - 1)/d}/${T/d}")
    }

    if (A == B) {
      answer(T + 1)
      return
    }

    val a = A / gcd(A, B)
    if (a > T / B) {
      answer(min(T + 1, min(A, B)))
      return
    }
    val lcm = a * B
    val size = ((T + 1 + lcm - 1)/ lcm)
    val r = (T + 1) % lcm
    debug{"$lcm $size $r"}
    if (size == 1L) {
      answer(min(T + 1, min(A, B)))
      return
    }

    var ans = 0L
    ans += min(A, B) * (size - 1)
    ans += min(r + 1, min(A, B))
    debug{"$ans"}
    answer(ans)
  }













































