private fun readProblem(readLine: () -> String?): Problem {
    val input = (readLine() + readLine() + readLine())
    return Problem(input.map(::charToPlayer))
}

private fun charToPlayer(c: Char): Player? {
    when (c) {
        'X' -> return Player.X
        '0' -> return Player.O
        else -> return null
    }
}

private class Problem(val board: List<Player?>) {
    override fun toString(): String {
        return board.joinToString(" ")
    }

    fun countX(): Int {
        return board.filter { it == Player.X }.count()
    }

    fun countO(): Int {
        return board.filter { it == Player.O }.count()
    }

    fun hasThreeX(): Boolean {
        val xs = board.map { it == Player.X }
        return isWinning(xs)
    }

    fun hasThreeO(): Boolean {
        val os = board.map { it == Player.O }
        return isWinning(os)
    }

    private fun isWinning(b: List<Boolean>): Boolean {
        return (b[0] && b[1] && b[2])
                || (b[3] && b[4] && b[5])
                || (b[6] && b[7] && b[8])
                || (b[0] && b[3] && b[6])
                || (b[1] && b[4] && b[7])
                || (b[2] && b[5] && b[8])
                || (b[0] && b[4] && b[8])
                || (b[2] && b[4] && b[6])
    }
}

private enum class Player {
    X, O
}

// SOLVE PROBLEM

private fun solve(prob: Problem): Solution {
    // x - it's the first player
    // o - it's the second player
    val xNo = prob.countX()
    val oNo = prob.countO()
    val xWon = prob.hasThreeX()
    val oWon = prob.hasThreeO()

    when {
        (xNo < oNo) -> return Solution.ILLEGAL
        (xNo > (oNo + 1)) -> return Solution.ILLEGAL
        (xWon && oWon) -> return Solution.ILLEGAL
        (xWon && (xNo > oNo)) -> return Solution.FIRST_WON
        (xWon) -> return Solution.ILLEGAL
        (oWon && (xNo == oNo)) -> return Solution.SECOND_WON
        (oWon) -> return Solution.ILLEGAL
        (xNo == oNo) -> return Solution.FIRST
        (xNo > oNo) -> return Solution.SECOND
        else -> return Solution.ILLEGAL
    }
}

