fun POW(N:Int ,P: Int ,mod : Int):Int{
    var x=1
    var n=N
    var p=P
    while (p > 0) {
        if (p%2 == 0) {
            n = n*n %mod
            p /= 2
        } else {
            x = x*n %mod
            p -= 1
        }
    }

    return x
}

