val MAXN = 200000

fun main() {
    val (n, k) = readInts(2)
    val A = readInts(n)
    val Cnt = A.groupingBy { it }.eachCountTo(HashMap())
    val bit = BIT(MAXN)

    var ans = Int.MAX_VALUE

    for((a, cn) in Cnt) bit.add(a, cn)
    cnt@ for((a, cn) in Cnt) {
        var need = k - cn
        var tot = 0
        var l = a
        var delta = 0
        var cost = 0

        while(need > 0) {
            l = l shl 1
            if(l > MAXN) continue@cnt
            cost++
            delta = (delta shl 1) + 1

            val get = minOf(need, bit.sum(l .. l + delta))
            need -= get
            tot += get * cost
        }

        if(tot < ans) ans = tot
    }

    println(ans)
}

class BIT(val size: Int) {
    private val A = IntArray(size + 1)
    private val logn = generateSequence(size) { it shr 1 }.takeWhile { it > 1 }.count()

    // zeroes all the bits except the least significant one
    @Suppress("NOTHING_TO_INLINE")
    private inline fun lsb(i: Int) = i and -i

    fun sum(end: Int): Int {
        var i = minOf(end, size)
        var sum = 0
        while(i > 0) {
            sum += A[i]
            i -= lsb(i)
        }
        return sum
    }

    fun sum(range: IntRange) = sum(range.last) - sum(range.first - 1)

    fun add(index: Int, value: Int) {
        var i = index // BIT is internally 1-indexed
        while(i <= size) {
            A[i] += value
            i += lsb(i)
        }
    }
}

