inline infix fun Int.umod(base: Int) = Math.floorMod(this, base)

tailrec fun gcd(a: Int, b: Int): Int = if(a == 0) abs(b) else gcd(b % a, a)
fun lcm(a: Int, b: Int): Long = a / gcd(a, b) * b.toLong()

fun Int.divisors() = sequence {
    val n = this@divisors
    if(n <= 0) return@sequence
    val tail = mutableListOf<Int>()

    for(p in 1..Int.MAX_VALUE) {
        val sq = p * p
        if(sq > n) break
        if(n % p == 0) {
            yield(p)
            if(sq != n) tail.add(n / p)
        }
    }

    yieldAll(tail.asReversed())
}

inline fun <T, R: Comparable<R>> Sequence<T>.allMinBy(selector: (T) -> R): List<T> {
    val result = mutableListOf<T>()
    var min: R? = null

    for(it in this) {
        val r = selector(it)
        if(min == null || r < min) {
            min = r
            result.clear()
            result.add(it)
        } else if(r.compareTo(min) == 0) { result.add(it) }
    }

    return result
}

