import java.io.*
import java.util.*
import kotlin.math.abs
import kotlin.math.min

class A internal constructor(inputStream: InputStream, val out: PrintWriter) {
    companion object {
        val ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null
    }

    private val br = BufferedReader(InputStreamReader(inputStream))
    private var st = StringTokenizer("")

    internal fun hasNext(): Boolean {
        while (!st.hasMoreTokens()) {
            val readLine = br.readLine() ?: return false
            st = StringTokenizer(readLine)
        }
        return true
    }

    private operator fun next() =
            if (hasNext()) st.nextToken()!!
            else throw RuntimeException("No tokens")

    internal fun nline() = st.nextToken("\n")

    private fun ni(offset: Int = 0) = next().toInt() + offset
    private fun nii(offset: Int = 0) = Pair(ni(offset), ni(offset))
    private fun niii(offset: Int = 0) = Triple(ni(offset), ni(offset), ni(offset))

    private fun nia(n: Int, offset: Int = 0) = IntArray(n) { ni(offset) }
    private fun niaa(m: Int, n: Int, offset: Int = 0) = Array(m) { nia(n, offset) }

    private fun nl(offset: Long = 0L) = next().toLong() + offset
    private fun nll(offset: Long = 0L) = Pair(nl(offset), nl(offset))
    private fun nlll(offset: Long = 0L) = Triple(nl(offset), nl(offset), nl(offset))

    private fun nla(n: Int, offset: Long = 0L) = LongArray(n, { nl(offset) })
    private fun nlaa(m: Int, n: Int, offset: Long = 0L) = Array(m) { nla(n, offset) }

    private fun nd(offset: Double = 0.0) = next().toDouble() + offset
    private fun ndd(offset: Double = 0.0) = Pair(nd(offset), nd(offset))
    private fun nddd(offset: Double = 0.0) = Triple(nd(offset), nd(offset), nd(offset))

    private fun nda(n: Int, offset: Double = 0.0) = DoubleArray(n) { nd(offset) }
    private fun ndaa(m: Int, n: Int, offset: Double = 0.0) = Array(m) { nda(n, offset) }

    inline fun log(name: String, block: () -> Unit) {
        if (!ONLINE_JUDGE) {
            p("#$name: ")
            block()
            flush()
        }
    }

    inline fun log() = log("") { pln() }
    inline fun log(message: Any?, name: String = "") = log(name) { pln(message) }
    inline fun log(arr: IntArray?, name: String = "", range: IntRange? = arr?.indices) = log(name) { pln(arr, range =  range) }
    inline fun log(arr: LongArray?, name: String = "", range: IntRange? = arr?.indices) = log(name) { pln(arr, range =  range) }
    inline fun log(arr: DoubleArray?, name: String = "", range: IntRange? = arr?.indices) = log(name) { pln(arr, range =  range) }
    inline fun <T> log(arr: Array<T>?, name: String = "", range: IntRange? = arr?.indices) = log(name) { pln(arr, range =  range) }
    inline fun <T> log(stack: Stack<T>?, name: String = "", range: IntRange? = stack?.indices) = log(name) { pln(stack, range =  range) }
    inline fun <T> log(list: List<T>?, name: String = "", range: IntRange? = list?.indices) = log(name) { pln(list, range =  range) }

    //prefix print
    inline fun prep(prefix: Boolean, separator: String, message: Any?) {
        if (prefix) {
            p(separator)
        }
        p(message)
    }

    inline fun p(message: Any?) = this.also { out.print(message) }

    inline fun p(arr: IntArray?, separator: String = " ", range: IntRange? = arr?.indices) = this.also {
        range?.forEach { prep(it > 0, separator, arr?.get(it)) }
    }

    inline fun p(arr: LongArray?, separator: String = " ", range: IntRange? = arr?.indices) = this.also {
        range?.forEach { prep(it > 0, separator, arr?.get(it)) }
    }

    inline fun p(arr: DoubleArray?, separator: String = " ", range: IntRange? = arr?.indices) = this.also {
        range?.forEach { prep(it > 0, separator, arr?.get(it)) }
    }

    inline fun <T> p(arr: Array<T>?, separator: String = " ", range: IntRange? = arr?.indices) = this.also {
        range?.forEach { prep(it > 0, separator, arr?.get(it)) }
    }

    inline fun <T> p(list: List<T>?, separator: String = " ", range: IntRange? = list?.indices) = this.also {
        range?.forEach { prep(it > 0, separator, list?.get(it)) }
    }

    inline fun <T> p(stack: Stack<T>?, separator: String = " ", range: IntRange? = stack?.indices) = this.also {
        range?.forEach { prep(it > 0, separator, stack?.get(it)) }
    }

    inline fun pln() = this.also { out.println() }
    inline fun pln(message: Any?) = p(message).pln()
    inline fun pln(arr: IntArray?, separator: String = " ", range: IntRange? = arr?.indices) = p(arr, separator, range).pln()
    inline fun pln(arr: LongArray?, separator: String = " ", range: IntRange? = arr?.indices) = p(arr, separator, range).pln()
    inline fun pln(arr: DoubleArray?, separator: String = " ", range: IntRange? = arr?.indices) = p(arr, separator, range).pln()
    inline fun <T> pln(arr: Array<T>?, separator: String = " ", range: IntRange? = arr?.indices) = p(arr, separator, range).pln()
    inline fun <T> pln(list: List<T>?, separator: String = " ", range: IntRange? = list?.indices) = p(list, separator, range).pln()
    inline fun <T> pln(stack: Stack<T>?, separator: String = " ", range: IntRange? = stack?.indices) = p(stack, separator, range).pln()

    inline fun flush() = out.flush()

    //////////////////////////////////////

    fun run() {
        val n = ni()
        val p = nia(n / 2, -1)
        var chan = 0
        var count = 0
        for (pi in p) {
            chan += abs(pi - count)
            count += 2
        }

        var le = 0
        count = 1
        for (pi in p) {
            le += abs(pi - count)
            count += 2
        }
        pln(min(chan,le))
    }

}

//////////////////////////////////////
fun main(args: Array<String>) {
    val inp = File("A.txt")
    if (A.ONLINE_JUDGE || !inp.isFile) {
        val a = A(System.`in`, PrintWriter(BufferedOutputStream(System.out)))
        a.run()
        a.flush()
        a.out.close()
    } else {
        val t = A(FileInputStream("A.txt"), PrintWriter(BufferedOutputStream(System.out)))
        while (t.hasNext()) {
            val name = t.nline()
            t.log("##### Test $name #####")
            val startTime = System.currentTimeMillis()
            t.run()
            val endTime = System.currentTimeMillis()
            t.log(endTime - startTime, "Total Time")
            t.log()
            t.flush()
        }
    }
}

import java.util.*

fun main(args: Array<String>) = with(Scanner(System.`in`)) {
    val n = nextInt()

    val r = Array(n / 2) { nextInt() }

    val e = Array(n / 2) { 2 + it * 2 }
    val o = Array(n / 2) { 1 + it * 2 }

    val eSum = (0 until n / 2).sumBy { Math.abs(r[it] - e[it]) }
    val oSum = (0 until n / 2).sumBy { Math.abs(r[it] - o[it]) }

    println(Math.min(eSum, oSum))
}

import kotlin.math.absoluteValue
import kotlin.math.min

fun main() {
    fun readInts() = readLine()!!.split(" ").map(String::toInt)

    readLine()
    val positions = readInts()
    var sol = Int.MAX_VALUE
    for (start in 1..2) {
        var target = start
        var oneSol = 0
        for (position in positions) {
            oneSol += (position - target).absoluteValue
            target += 2
        }
        sol = min(sol, oneSol)
    }
    print(sol)
}

