fun solution(ss: String): Boolean {
    val s = ss.trim { it=='0' }
    if (s.length==1) return false
    if (s.all { it==s.first() }) return true
    val ns = s.map { it.toInt() - '0'.toInt() }
    val sum = ns.sum()
    val r =
    when {
        isPrime(sum) -> false
        else -> {
            var canDivide = false
            var l = 0
