                var b: Int
                whileloop@ while (l <= ns.lastIndex) {
                    canDivide=false
                    b=sum/i
                    while (b > 0 && l<=ns.lastIndex) b -= ns[l++]
                    if (b == 0) {
                        canDivide =  true
                        continue@whileloop
                    }
                    else {
                        l=0
                        canDivide = false
                        continue@forloop
                    }
                }

                if (canDivide) break
            }
            canDivide
        }
    }
