fun checkIn(character: Char, maxChar: Char) = character in 'a'..maxChar

fun main() {
    val numberOfRequiredLetters = readLine()?.toInt()
    val pattern = readLine()

    if (numberOfRequiredLetters == null || pattern == null) {
        println("Wrong input")
        return
    }

    val sz = pattern.length
    var free = 0
    val maxChar = ('a' + numberOfRequiredLetters - 1)
    val unusedChars = ('a'..maxChar).toHashSet()
    val stringArray = Array(sz) {'?'}

    for ((i, j) in (0 until sz).zip(sz - 1 downTo 1)) {
        val first = pattern[i]
        val second = pattern[j]

        if (first == '?' && second == '?') {
            free++
            continue
        }

        if (first == '?') {
            stringArray[i] = second
            stringArray[j] = second
        } else {
            stringArray[i] = first
            stringArray[j] = first
        }

        if (!checkIn(stringArray[i], maxChar)) {
            println("IMPOSSIBLE")
            return
        }
        unusedChars.remove(stringArray[i])
    }

    if (free < unusedChars.size) {
        println("IMPOSSIBLE")
        return
    }

    for ((i, j) in (0 until sz).zip(sz - 1 downTo 1)) {
        if (stringArray[i] != '?') {
            continue
        }

        val unusedCharacter = unusedChars.firstOrNull() ?: 'a'
        stringArray[i] = unusedCharacter
        stringArray[j] = unusedCharacter
        unusedChars.remove(unusedCharacter)
    }

    println(stringArray.joinToString(separator = ""))
}

