import java.util.*

fun main(args: Array<String>) {
    val input = Scanner(System.`in`)
    val k = input.nextInt()
    val pattern: String = input.next()

    val len = pattern.length
    var possible = true
    var free = 0

    val answer = CharArray(len)
    val used = BooleanArray(k)

    loop@ for (symbol in pattern) {
        val number = symbol.minus('a')
        when {
            number < 0 -> continue@loop
            number >= k -> possible = false
            else -> used[number] = true
        }
    }

    for (index in 0..(len - 1) / 2) {
        val left = pattern[index]
        val right = pattern[len - 1 - index]

        when {
            left != '?' && right != '?' && left != right -> possible = false
            left == '?' && right != '?' -> {
                answer[index] = right
                answer[len - 1 - index] = right
            }
            left != '?' && right == '?' -> {
                answer[index] = left
                answer[len - 1 - index] = left
            }
            left == '?' && right == '?' -> free++
            left == right -> {
                answer[index] = left
                answer[len - 1 - index] = right
            }
        }
    }

    val need = k - (used.filter { it }).size
    free -= need

    var currentPosition = 0
    (0..(len - 1) / 2)
            .asSequence()
            .filter { pattern[it] == '?' && pattern[len - 1 - it] == '?' }
            .forEach {
                if (free-- > 0) {
                    answer[it] = 'a'
                    answer[len - 1 - it] = 'a'
                } else {
                    while (currentPosition < k && used[currentPosition]) {
                        currentPosition++
                    }

                    if (currentPosition >= k) {
                        possible = false
                    }
                    val symbol = 'a'.plus(currentPosition++)
                    answer[it] = symbol
                    answer[len - 1 - it] = symbol
                }
            }

    if (possible) {
        println(String(answer))
    } else {
        println("IMPOSSIBLE")
    }
}

package ru.spbau.mit

import java.io.InputStream
import java.util.*

class Solver(k: Int, private val bookTitle: CharArray) {
    companion object {
        fun read(inputStream: InputStream) : Solver {
            val input = Scanner(inputStream)
            val k = input.nextInt()
            val bookTitle = input.next().toCharArray()
            return Solver(k, bookTitle)
        }

        val IMPOSSIBLE = "IMPOSSIBLE".toCharArray()
    }

    private val unusedLetters  = (('a' until 'a' + k) - bookTitle.toSortedSet()).toSortedSet()
    private val halfOfBookTitleSize = bookTitle.size / 2

    fun solve(): CharArray {
        if (!removePairedQuestionMarks())
            return IMPOSSIBLE
        if (!removeSingleQuestionMarks())
            return IMPOSSIBLE
        return bookTitle
    }

    private fun removeSingleQuestionMarks(): Boolean {
        var i = 0
        while (i < halfOfBookTitleSize) {
            val correspondingIndex = getCorrespondingIndex(i)
            if (bookTitle[i] == '?' || bookTitle[correspondingIndex] == '?') {
                if (bookTitle[i] == '?') {
                    bookTitle[i] = bookTitle[correspondingIndex]
                } else {
                    bookTitle[correspondingIndex] = bookTitle[i]
                }
            } else {
                if (bookTitle[i] != bookTitle[correspondingIndex]) {
                    return false
                }
            }
            i++
        }
        return true
    }

    private fun removePairedQuestionMarks(): Boolean {
        var i = halfOfBookTitleSize
        while (i < bookTitle.size) {
            val correspondingIndex = getCorrespondingIndex(i)
            if (bookTitle[i] == '?' && bookTitle[correspondingIndex] == '?') {
                bookTitle[i] = getAndExtractMaxUnusedLetterOrA()
                bookTitle[correspondingIndex] = bookTitle[i]
            }
            i++
        }
        return unusedLetters.isEmpty()
    }

    private fun getAndExtractMaxUnusedLetterOrA(): Char {
        if (unusedLetters.isEmpty())
            return 'a'
        val lastFromUnusedLetters = unusedLetters.last()
        unusedLetters.remove(lastFromUnusedLetters)
        return lastFromUnusedLetters
    }

    private fun getCorrespondingIndex(i: Int): Int = bookTitle.size - i - 1
}

fun main(args: Array<String>) {
    print(Solver.read(System.`in`).solve())
}

package ru.spbau.mit

import java.util.*

class Solver(k: Int, internal val bookTitle: CharArray) {
    companion object {
        private val IMPOSSIBLE = "IMPOSSIBLE".toCharArray()
    }
    private val unusedLetters: ArrayDeque<Char>
    init {
        val firstKLetters = 'a' until 'a' + k
        val usedLetters = bookTitle.toSet()
        unusedLetters = ArrayDeque(firstKLetters - usedLetters)
    }

    fun solve(): CharArray {
        val ok = removePairedQuestionMarks() && removeSingleQuestionMarks()
        return if (ok) bookTitle else IMPOSSIBLE
    }

    internal fun removeSingleQuestionMarks(): Boolean {
        for (i in 0 until bookTitle.size / 2) {
            val currentSymbol = bookTitle[i]
            val correspondingIndex = i.getCorrespondingIndex
            val correspondingSymbol = bookTitle[correspondingIndex]
            when {
                currentSymbol == '?' -> bookTitle[i] = correspondingSymbol
                correspondingSymbol == '?' -> bookTitle[correspondingIndex] = currentSymbol
                currentSymbol != correspondingSymbol -> return false
            }
        }
        return true
    }

    internal fun removePairedQuestionMarks(): Boolean {
        for (i in 0 until bookTitle.size / 2) {
            val currentSymbol = bookTitle[i]
            val correspondingIndex = i.getCorrespondingIndex
            val correspondingSymbol = bookTitle[correspondingIndex]
            if (currentSymbol == '?' && correspondingSymbol == '?') {
                bookTitle[i] = getAndExtractMaxUnusedLetterOrA()
                bookTitle[correspondingIndex] = bookTitle[i]
            }
        }
        return unusedLetters.isEmpty()
    }

    private fun getAndExtractMaxUnusedLetterOrA(): Char {
        return if (unusedLetters.isEmpty()) 'a' else unusedLetters.removeLast()
    }

    private val Int.getCorrespondingIndex:Int get() = bookTitle.size - this - 1
}

fun main(args: Array<String>) {
    val input = Scanner(System.`in`)
    val k = input.nextInt()
    val bookTitle = input.next().toCharArray()
    print(Solver(k, bookTitle).solve())
}

/**
 * Class that solves codeforces problem.
 * It tries to replace wild cards(?) to letters to create lexicographically smallest palindrome.
 */
class PatternHandler(private val pattern: CharArray,
                     private val alphabet: Int) {

    private val IMPOSSIBLE_MESSAGE = "IMPOSSIBLE"
    private val usedChars = BitSet(alphabet)

    init {
        pattern
                .filter { it != '?' }
                .map { getIndex(it) }
                .forEach { usedChars[it] = true }
    }

    /**
     * Returns index of symbol in usedChars array
     */
    private fun getIndex(symbol: Char): Int = symbol - 'a'

    /**
     * Returns index of symbol in usedChars array
     */
    private fun getSymbol(index: Int): Char = 'a' + index

    /**
     * Get index letter that should be on the wild card sign.
     * It's take the most biggest lexicographically letter,
     * because we are starting to remove wild cards from center of the palindrome.
     */
    private fun getAppropriateLetterIndex(): Int {
        val index = usedChars.previousClearBit(alphabet - 1)

        return if (index == -1) {
            0
        } else {
            index
        }
    }

    /**
     * l, r -- indices in pattern.
     * If they are both wild cards they will be replaced by most biggest lexicographically letter.
     */
    private fun removeWildCardPairs(l: Int, r: Int) {
        if (pattern[l] == '?' && pattern[r] == '?') {
            val letterIndex = getAppropriateLetterIndex()
            val letter = getSymbol(letterIndex)
            usedChars[letterIndex] = true
            pattern[l] = letter
            pattern[r] = letter
        }
    }

    /**
     * Cleaning rest of wild cards.
     * If there any of chars at indices l, r equals wild card, then it should be replaced by another char.
     */
    private fun cleanWildCards(l: Int, r: Int) {
        if (pattern[l] == '?') {
            pattern[l] = pattern[r]
        }

        if (pattern[r] == '?') {
            pattern[r] = pattern[l]
        }
    }

    /**
     * Solving codeforces task.
     * It returns processed symmetric palindrome if it's possible.
     * Otherwise it returns IMPOSSIBLE_MESSAGE
     */
    fun solve(): String {
        if (alphabet > pattern.size) {
            return IMPOSSIBLE_MESSAGE
        }

        var r = pattern.size / 2
        while (r < pattern.size) {
            val indent = r - pattern.size / 2
            val l = r - (pattern.size + 1) % 2 - 2 * indent

            // process pattern
            removeWildCardPairs(l, r)
            cleanWildCards(l, r)

            if (pattern[l] != pattern[r]) {
                return IMPOSSIBLE_MESSAGE
            }

            r++
        }

        if (usedChars.cardinality() != alphabet) {
            return IMPOSSIBLE_MESSAGE
        }

        return String(pattern)
    }
}

