import kotlin.math.PI
import kotlin.math.atan

data class Vector(val xCoordinate : Int, val yCoordinate : Int, val identifier : Int)

fun getVectorAngle(vector : Vector) =
        when {
            vector.xCoordinate > 0 -> atan(vector.yCoordinate / vector.xCoordinate.toDouble())
            vector.xCoordinate < 0 -> PI + atan(vector.yCoordinate / vector.xCoordinate.toDouble())
            else ->
                if (vector.yCoordinate > 0) {
                    PI / 2
                } else {
                    -PI / 2
                }
        }

fun readVectors() : ArrayList<Vector> {
    val reader = Scanner(System.`in`)
    val vectorsNumber = reader.nextInt()
    val listOfVectors = ArrayList<Vector>()

    for (identifier in 1..vectorsNumber) {
        val xCoordinate = reader.nextInt()
        val yCoordinate = reader.nextInt()
        val vector = Vector(xCoordinate, yCoordinate, identifier)

        listOfVectors.add(vector)
    }

    return listOfVectors
}

fun getNearliestVectorPair(listOfVectors : ArrayList<Vector>) : Pair<Vector, Vector> {
    listOfVectors.sortWith(compareByDescending { getVectorAngle(it) })

    var bestAngleDifference : Double = 2 * PI + getVectorAngle(listOfVectors.last()) - getVectorAngle(listOfVectors.first())
    var bestFirstIndex = 0
    var bestSecondIndex = listOfVectors.size - 1

    for (i in 0 until listOfVectors.size - 1) {
        val angleDifference = getVectorAngle(listOfVectors[i]) - getVectorAngle(listOfVectors[i + 1])

        if (angleDifference < bestAngleDifference) {
            bestFirstIndex = i
            bestSecondIndex = i + 1
            bestAngleDifference = angleDifference
        }
    }

    return Pair(listOfVectors[bestFirstIndex], listOfVectors[bestSecondIndex])
}

fun getSymbolsFromString(string : String) : HashSet<Char> {
    val stringSymbols = HashSet<Char>()
    for (symbol in string) {
        if (!stringSymbols.contains(symbol)) {
            stringSymbols.add(symbol)
        }
    }

    return stringSymbols
}

fun getStringMissingSymbols(string: String) : ArrayList<Char> {
    val stringSymbols = getSymbolsFromString(string)
    val missingSymbols = ArrayList<Char>()

    for (symbol in 'a'..'z') {
        if (!stringSymbols.contains(symbol)) {
            missingSymbols.add(symbol)
        }
    }

    return missingSymbols
}

fun hasAnswer(string: String) : Boolean {
    for (i in 0..(string.length + 1) / 2) {
        if (string[i] != '?' && string[string.length - 1 - i] != '?') {
            if (string[i] != string[string.length - 1 - i]) {
                return false
            }
        }
    }

    return true
}

fun solveProblem(string: String, mustHaveCharsNumber : Int) : ArrayList<Char>? {
    val chars = ArrayList<Char>()
    val missingSymbols = getStringMissingSymbols(string)
    var index = 0

    if (!hasAnswer(string)) {
        return null
    }

    for (char in string) {
        chars.add(char)
    }

    for (i in 0 until (string.length + 1) / 2) {
        if (string[i] == '?' && string[string.length - 1 - i] == '?') {
            if (index == missingSymbols.size) {
                chars[i] = 'a'
                chars[string.length - 1 - i] = 'a'
            } else {
                chars[i] = missingSymbols[index]
                chars[string.length - 1 - i] = missingSymbols[index]
                index++
            }
        } else if (string[i] == '?') {
            chars[i] = string[string.length - 1 - i]
            chars[string.length - 1 - i] = string[string.length - 1 - i]
        } else {
            chars[i] = string[i]
            chars[string.length - 1 - i] = string[i]
        }
    }

    return if (index < missingSymbols.size && missingSymbols[index] - 'a' <= mustHaveCharsNumber) {
        chars
    } else {
        null
    }
}

fun main() {
    val reader = Scanner(System.`in`)
    val mustHaveCharsNumber = reader.nextInt()
    val string = reader.next()
    val resultString = solveProblem(string, mustHaveCharsNumber)

    if (resultString == null) {
        print("IMPOSSIBLE")
    } else {
        for (char in resultString) {
            print(char)
        }
    }
}

