fun PrintWriter.solve() {
    val n = readInt()

    val P = primeSieve(n/2).toList()
    var ans = 0
    i@ for(i in 0 until P.size - 1) {
        val a = P[i]
        for(j in i+1 until P.size) {
            val b = P[j]
            if(a * b > n) continue@i

            var ak = a
            var k = 1
            var bl = b

            while(ak * a * bl < n) {
                ak *= a
                k++
            }

            do {
                ans += k
                bl *= b
                do {
                    ak /= a
                    k--
                } while(k > 0 && ak * bl > n)
            } while(k > 0)
        }
    }

    println(ans)
}

fun primeSieve(upperLimit: Int): Sequence<Int> = sequence {
    yield(2)
    val source = (3..upperLimit step 2).toMutableSet()

    while(source.isNotEmpty()) {
        val prime = source.first()
        yield(prime)
        source.remove(prime)
        val sq = prime * prime
        if(sq > upperLimit) {
            yieldAll(source)
            break
        }
        source.removeAll(sq .. upperLimit step prime)
    }
}

