fun sportMafia(moves: Int, candiesLeft: Int): Int {
    var left = 0
    var right = moves
    while (true) {
        val current = left + (right - left) / 2
        val broughtIn = sumOf(current)
        val eaten = moves - current
        val resultingCandies = broughtIn - eaten
        when {
            resultingCandies < candiesLeft -> {
                left = current + 1
            }
            resultingCandies == candiesLeft -> return eaten
            resultingCandies > candiesLeft -> {
                right = current - 1
            }
        }
    }
}

fun sumOf(willAdd: Int): Int = (willAdd * (willAdd + 1)) / 2


