data class Key(val moves: Int, val candiesLeft: Int, val currentCandies: Int, val candiesEaten: Int, val lastAdded: Int)

val cache = mutableMapOf<Key, Int>()

fun sportMafia(moves: Int, candiesLeft: Int, currentCandies: Int = 0, candiesEaten: Int = 0, lastAdded: Int = 0): Int {
    val key = Key(moves, candiesLeft, currentCandies, candiesEaten, lastAdded)
    if (cache[key] != null)
        return cache[key]!!
    if (moves == 0) {
        val result = if (candiesLeft == currentCandies) candiesEaten else -1
        cache[key] = result
        return result
    }
    val result = if (currentCandies > 0) {
        // add or eat
        Math.max(
            sportMafia(moves - 1, candiesLeft, currentCandies + lastAdded + 1, candiesEaten, lastAdded + 1),
            sportMafia(moves - 1, candiesLeft, currentCandies - 1, candiesEaten + 1, lastAdded)
        )
    } else {
        // only add
        sportMafia(moves - 1, candiesLeft, currentCandies + lastAdded + 1, candiesEaten, lastAdded + 1)
    }
    cache[key] = result
    return result
}


