fun main() {
    val reader = Scanner(System.`in`)
    var noToHold = reader.nextInt()
    val containersLength = reader.nextInt()
    val containers = mutableMapOf<Int, Int>()
    for (i in 1..containersLength) {
        containers.put(reader.nextInt(), reader.nextInt())
    }
    val sortedContainers = containers.toList()
            .sortedByDescending { (key, value) -> value }
            .toMap()
    var total = 0
    for (container in sortedContainers) {
        if (noToHold != 0) {
            if (container.key <= noToHold) {
                noToHold -= container.key
                total += container.key * container.value
            } else {
                total += noToHold * container.value
                noToHold -= noToHold
            }
        }
        else
            break
    }
    print(total)
}

