fun cnk(n: Long, k: Long): BigInteger {
    var fenzi = BigInteger("1")
    var fenmu = BigInteger("1")
    for (i in n - k + 1..n) {
        fenzi = fenzi.multiply(i.toBigInteger())
    }
    for (j in 1..k) {
        fenmu = fenmu.multiply(j.toBigInteger())
    }
    return fenzi.divide(fenmu)
