fun calcInv(n: Int): LongArray {
    require(n <= MOD)
    val res = LongArray(n) { 1 }
    for (i in 2 until n) {
        res[i] = (MOD - (MOD /i)*res[(MOD%i).toInt()] % MOD) % MOD
    }
    return res
}

