fun choose(n: Int, k: Int): IntMod {
    if (k > n || n <= 0) return 0.moduloArithmetic()
    if (k == 0 || k == n) return 1.moduloArithmetic()

    return n.factorialModulo() / (k.factorialModulo() * (n-k).factorialModulo())
}

const val MOD: Int = 998_244_353

inline class IntMod(private val i: Int) {
    operator fun plus(increment: IntMod): IntMod = IntMod(Math.floorMod(i + increment.i, MOD))
    operator fun plus(increment: Int): IntMod = this + increment.moduloArithmetic()

    operator fun minus(other: IntMod): IntMod = IntMod(Math.floorMod(i - other.i, MOD))
    operator fun minus(decrement: Int): IntMod = this - decrement.moduloArithmetic()

    operator fun times(other: IntMod): IntMod = IntMod(Math.floorMod(i.toLong() * other.i, MOD.toLong()).toInt())
    operator fun times(other: Int): IntMod = this * other.moduloArithmetic()
    operator fun div(other: IntMod): IntMod = this * other.multiplicativeInverse()
    operator fun div(other: Int): IntMod = this / other.moduloArithmetic()

    override fun toString(): String = i.toString()

    private fun multiplicativeInverse(): IntMod = pow(MOD - 2)

    // i^n
    fun pow(n_in: Int): IntMod {
        var x = this
        var y = IntMod(1)
        var n = n_in
        // x^n
        while (n > 0) {
            if (n % 2L != 0L) y *= x
            n /= 2
            x *= x
        }
        return y
    }
}

fun Int.moduloArithmetic() : IntMod = IntMod(this % MOD)

fun Int.factorialModulo(): IntMod {
    var res = 1.moduloArithmetic()
    for (i in 2..this) {
        res *= i
    }
    return res
}

