    val seq = getIntString()

    val costes = ArrayList<Int>()

    for (i in 1 until n) {
        if (checkSeq(seq.subList(0, i)) && checkSeq(seq.subList(i, n))) {
            val cost = Math.abs(seq[i-1] - seq[i])
            costes.add(cost)
        }
    }

    var result = 0
    costes.sorted().forEach {
        if (result + it <= b) {
            b -= it
            result++
        }
    }

    println(result)

}

fun checkSeq(list: List<Int>): Boolean {
    if (list.size % 2 != 0) {
        return false
    }
    var even = 0
    var notEven = 0
    list.forEach {
        if (it % 2 ==0) {
            even++
        } else {
            notEven++
        }
    }
    return even == notEven
}

