fun bestCuts(a: List<Int>, b: Int): Int {
    if (a.size <= 2) return 0

    var ans = 0
    var odds = 0
    var evens = 0
    a.forEachIndexed { index, item ->
        if (item % 2 == 0) evens++
        else odds++

        if (evens == odds && index + 1 < a.size && abs(a[index + 1] - a[index]) <= b) {
            val tempAns = 1 + bestCuts(a.subList(0, index + 1), b - abs(a[index + 1] - a[index])) + bestCuts(a.subList(index + 1, a.size), b - abs(a[index + 1] - a[index]))
            if (tempAns > ans) {
                ans = tempAns
            }
        }
    }

    return ans
}

