    val size = readLine()?.toInt() ?: return
    var swappableCount = 0
    var leftOdd = 0
    var rightOdd = 0
    for (i in 0.until(size)) {
        val values = readLine()?.split(' ') ?: return
        val left = values[0].toInt() % 2 == 0
        val right = values[1].toInt() % 2 == 0
        if (!left) {
            leftOdd++
        }
        if (!right) {
            rightOdd++
        }
        if (left != right) {
            swappableCount++
        }
    }
    // both even
    if (leftOdd % 2 == 0 && rightOdd % 2 == 0) {
        println(0)
        return
    }
    // odd and equal
    if (leftOdd == rightOdd) {
        if (swappableCount > 0) {
            println(1)
            return
        }
        else{
            println(-1)
            return
        }
    }
    val diff = Math.abs(leftOdd - rightOdd)
    if (diff % 2 != 0) {
        println(-1)
        return
    }
    val swapCount = diff / 2
    if (swappableCount >= swapCount) {
        println(swapCount)
        return
    }
    println(-1)
}

