fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val k = scanner.nextInt()
    val a = scanner.nextInt()
    val b = scanner.nextInt()

    tailrec fun gcd(i: Int, j: Int): Int =
            if (i % j == 0) j
            else gcd(j, i % j)

    val m = n * k
    var min = m
    var max = 1

    outer@ for (i in arrayOf(a + b, a - b, -a + b, -a - b)) {
        for (j in 0..n) {
            val s = j * k + i
            if (s in 1..m) {
                val g = gcd(m, s)
                val c = m / g
                min = min(min, c)
                max = max(max, c)
                if (min == 1 && max == m) break@outer
            }
        }
    }

    println("$min $max")
}

