private fun getCount(count: Int, str: String): String {
    val temp = HashMap<String, Int>()
    var maxCounted = 1
    var maxValue = ""
    (0 until count - 1).forEach { index ->
        val two = str.substring(index, index + 2)
        if(index == 0) {
            maxValue = two
        }
        val existed = temp[two]
        if (existed != null) {
            val newCount = existed.plus(1)
            if(maxCounted < newCount) {
            	maxCounted = existed.plus(1)
                maxValue = two
            }
            temp[two] = newCount
        } else {
            temp[two] = 1
        }
    }
    return maxValue
}

