const val B = 31
const val MOD = 998244353

fun readInt(): Int {
    var digit = System.`in`.read()
    while(digit <= 32) {
        digit = System.`in`.read()
    }

    val negative = digit == '-'.toInt()
    if (negative) {
        digit = System.`in`.read()
    }
    var res = 0
    while (digit in '0'.toInt()..'9'.toInt()) {
        res *= 10
        res += digit - '0'.toInt()
        digit = System.`in`.read()
    }
    return if (negative) -res else res
}

fun main() {
    val k = readLine()!!.toInt()

    val dp = Array(B) { Array(B) { Array(2) { 0L } } }

    dp[B - 1][0][1] = 1
    for(i in B - 1 downTo 1) {
        for(j in 0 until B) {
            for(p in 0..1) {
                if(dp[i][j][p] == 0L) continue

//                println("$i $j $p ${dp[i][j][p]}")

                if(p == 0 || ((k shr (i - 1)) and 1) == 1) {
//                    println("$i $j $p")
                    dp[i - 1][j + 1][p] = (dp[i - 1][j + 1][p] + dp[i][j][p]) % MOD
                }

                if(p == 0) {
                    dp[i - 1][j][0] = (dp[i - 1][j][0] + dp[i][j][p] * (1 shl j)) % MOD
                } else if(j == 0) {
                    val newp = if(((k shr (i - 1)) and 1) == 1) 0 else 1
                    dp[i - 1][j][newp] = (dp[i - 1][j][newp] + dp[i][j][p]) % MOD
                } else if(((k shr (i - 1)) and 1) == 1) {
                    dp[i - 1][j][0] = (dp[i - 1][j][0] + dp[i][j][p] * (1 shl (j - 1))) % MOD
                    dp[i - 1][j][1] = (dp[i - 1][j][1] + dp[i][j][p] * (1 shl (j - 1))) % MOD
                } else {
                    dp[i - 1][j][1] = (dp[i - 1][j][1] + dp[i][j][p] * (1 shl (j - 1))) % MOD
                }
            }
        }
    }

    var ans = 0L
    for(j in 0 until B) {
        for(p in 0..1) {
            ans = (ans + dp[0][j][p]) % MOD
        }
    }

    println(ans)
}

