fun findMax(a: Array<IntArray>, startI: Int, startJ: Int, n: Int): Int {
    if (startI == n || startJ == n) {
        return 0
    }
    for (i in startI until n) {
        for (j in startJ until n) {
            a[i][j] = a[i - 1][j] + a[i][j - 1]
            findMax(a, i + 1, j + 1, n)
        }
    }
    return a[n - 1][n - 1]
}

