const val threshold = 50

fun brute(x: Long, y: Long): Char {
    val xy = pow(x.toDouble(), y.toDouble())
    val yx = pow(y.toDouble(), x.toDouble())
    return when {
        xy > yx -> '>'
        xy < yx -> '<'
        else -> '='
    }
}

