val MOD = 1_000_000_007

class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val R = ni()
    val G = ni()
    var H = 0
    while((H + 1) * (H + 2) / 2 <= R + G) H++
    val N = R
    val dp = Array(H + 1){
      val size = if (it == H) 0
      else H * (H + 1) / 2 - it * (it + 1) / 2
      IntArray(size + 1)
    }
    debug{"N:$N H:$H"}
    dp[H][0] = 1
    for (i in H - 1 downTo 0) {
      for (j in dp[i].indices) {
        if (j < dp[i + 1].size) dp[i][j] += dp[i + 1][j]
        val nj = j - (i + 1)
        if ((dp[i + 1].indices).contains(nj)) {
          dp[i][j] += dp[i + 1][nj]
        }
        if (dp[i][j] > MOD) dp[i][j] -= MOD
      }
      debug(dp[i])
    }
    var ans = 0L
    val remain = R + G - H * (H + 1) / 2
    for (r in 0 .. remain) {
      val j = N - r
      ans += dp[0][j]
    }
    out.println(ans % MOD)
  }













































