fun fround(A: Int,B: Int,rounds: Int): Int{
	var meetRound: Int = 0
	var tmpA: Int
	var tmpB: Int

	for (i in rounds downTo 1){
		tmpA = ceil(A/(2.0.pow(i-1))-0.01).toInt()
		tmpB = ceil(B/(2.0.pow(i-1))-0.01).toInt()
		if (abs(tmpA - tmpB) >= 1){
			meetRound = i
			break
		}
	}
	return(meetRound)
}

