import java.util.function.Consumer

fun main() {
    val (peopleNumber, teamsNumber) = readLine()!!.split(" ").map { it.toInt() }

    countMinMaxNumbers(
        BigDecimal(peopleNumber),
        BigDecimal(teamsNumber),
        minVal = { value -> print("$value ") },
        maxVal = { value -> print("$value") }
    )
}

fun countMinMaxNumbers(peopleNumber: BigDecimal, teamsNumber: BigDecimal, minVal: Consumer<BigDecimal>, maxVal: Consumer<BigDecimal>) {
    val minTeam = peopleNumber / teamsNumber
    val remains = peopleNumber % teamsNumber

    if (remains == 0.toBigDecimal()) {
        val pairCount = minTeam.getPairCombNumb()
        val pairSum = pairCount * teamsNumber

        minVal.accept(pairSum)
    } else {
        val sumWithRem = remains * (minTeam + 1.toBigDecimal()).getPairCombNumb()
        val sumOfMain = (teamsNumber - remains) * minTeam.getPairCombNumb()
        val totalSum = sumWithRem + sumOfMain

        minVal.accept(totalSum)
    }

    val maxTeam = peopleNumber - (teamsNumber - 1.toBigDecimal())
    maxVal.accept(maxTeam.getPairCombNumb())
}

fun BigDecimal.getPairCombNumb() = (this * (this - 1.toBigDecimal())) / 2.toBigDecimal()

