class DSU {

    var sizes : IntArray
    var ranks : IntArray
    var parents : IntArray

    constructor(n : Int)
    : this(
            IntArray(n) { 1 }
    )

    constructor(sizes : IntArray) {
        val size = sizes.size
        this.sizes = sizes
        this.ranks = IntArray(size) { 1 }
        this.parents = IntArray(size) { it }
    }

    operator fun get(v : Int) : Int {
        val parent = parents[v]
        if (parent == v) return v
        parents[v] = get(parent)
        return parents[v]
    }

    fun union(aUniting : Int, bUniting : Int) : Boolean {
        var a = get(aUniting)
        var b = get(bUniting)

        if (a == b) return false

        if (ranks[a] < ranks[b]) {
            val tmp = a
            a = b
            b = tmp
        }

        parents[b] = a
        sizes[a] += sizes[b]
        if (ranks[a] == ranks[b]) ++ranks[a]

        return true
    }

    fun size(v : Int) : Int = sizes[get(v)]
}

class FenwickTree(n : Int) {

    val size = n + 1
    val tree = LongArray(size) { 0L }

    fun update(index : Int, delta : Int) {
        var x = index + 1
        while (x < size) {
            tree[x] = tree[x] + delta
            x += x and -x
        }
    }

    operator fun get(start : Int, end : Int) =
            get(end) - get(start - 1)

    operator fun get(index : Int) : Long {
        var result : Long = 0

        var x = index + 1
        while (x > 0) {
            result += tree[x]
            x -= x and -x
        }

        return result
    }
}

