fun solve(ir : Reader, pw : PrintWriter) {

    var n = ir.nextInt()
    val res = IntArray(3)
    val max = IntArray(3)

    for (i in 0..2) {
        res[i] = ir.nextInt()
        n -= res[i]
        max[i] = ir.nextInt()
    }

    for (i in 0..2)
        if (max[i] - res[i] < n) {
            res[i] = max[i]
            n = n - max[i] + res[i]
        } else {
            res[i] += n
            break
        }

    for (i in 0..2)
        pw.print("${res[i]} ")

}

class Reader(stream: InputStream) {
