class RibbonConfiguration(val remainingLength: Int, val nPieces: Int) : Comparable<RibbonConfiguration> {
    val maxPieces = nPieces + (remainingLength / lengthOptions[0]) - 1

    override operator fun compareTo(other: RibbonConfiguration): Int {
        // make it opposite b/c java has LEAST pq by default
        return compareValues(other.maxPieces, maxPieces)
    }

    override fun toString(): String {
        return "$nPieces piece w/ $remainingLength left ($maxPieces max)"
    }



}

