fun ex1(n: Int, a: Int, b: Int, c: Int): Int {
    var answer = 0
    for (ia in 0..n) {
        for (ib in 0..n) {
            val num = n - ib * b - ia * a
            if (num < 0) break
            if (num % c == 0) {
                val ic = num / c
                answer = max(answer, ia + ib + ic)
            }
        }
    }

    return answer
}

