fun getAnswer(inputRaw: List<Int>):Int {
    val length = inputRaw[0]

    val inputSorted = inputRaw.subList(1, inputRaw.size).sorted()
    val a = inputSorted[0]
    val b = inputSorted[1]
    val c = inputSorted[2]
    if (a == 1 || b==1 || c==1) return length
    if (a == length && b==length && c==length) return 1
    return getNumOfPieces(a, b, c, length)
}

fun getNumOfPieces(a:Int, b:Int, c:Int, length:Int):Int {
    if(length == 0) return 0
    if(length < 0) return Int.MIN_VALUE
    if (length % a == 0) return length/a //a is smallest
    return listOf(
            1+getNumOfPieces(a, b, c, length-a),
            1+getNumOfPieces(a, b, c, length-b),
            1+getNumOfPieces(a, b, c, length-c))
            .max()!!
}

