public class EasyNum {
    static boolean[] primes;
    static int[] memo;
    static int mod = (1<<30);
    public static void main(String[] args) {
        MyReader mr = new MyReader();

        int a = mr.nextInt();
        int b = mr.nextInt();
        int c = mr.nextInt();

        memo = new int[a*b*c+1];
        primes = new boolean[a*b*c+1];

        initPrimes();

        int res = 0;

        for (int i = 1; i <= a; i++)
            for(int j = 1; j<=b;j++)
                for(int k = 1; k<=c ;k++){
                    int val = i*j*k;
                    if(memo[val] == 0){
                        memo[val] = findDiv(val);
                    }

                    res+=memo[val];
                    res%=mod;
                }


        System.out.println(res);


    }

    private static int findDiv(int val) {
        int res = 1;
        for (int i = 2;i<=val;i++){
            if(primes[i] && val%i == 0){
                int count = 0;
                while (val%i == 0){
                    count++;
                    val/=i;
                }

                res=res*(count+1);
            }
        }

        return res;
    }

    private static void initPrimes() {
        Arrays.fill(primes,true);
        int n = primes.length;
        for (int i = 2; i < n; i++) {
            if (primes[i]){
                for (int j = 2; j*i < n ; j+=i) {
                    primes[j*i] = false;
                }
            }
        }
    }

