fun qpow(x: Long, exp: Long) : Long {
    var exp_ = exp % (MOD - 1)
    var res : Long = 1L
    var mult = x
    while (exp_ > 0) {
        if (exp_ % 2 == 1L) {
            res = (res * mult) % MOD
        }
        mult = (mult * mult) % MOD
        exp_ /= 2
    }
    return res % MOD
}


fun powmod(x: Long, y: Long) : Long {
    var ret = 1L;
    var y_ = y % (mod - 1)
    var x_ = x
    while( y_ > 0){
        if(1 == (y_ % 2).toInt()) {
            ret = (ret * x_) % mod
        }
        y_ /= 2
        x_ = (x_ * x_) % mod;
    }
    return ret;
}

