private val MOD = 1_000_000_007L

class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val N = ni()
    var best = Array(2){LongArray(N + 10)}
    var next = Array(2){LongArray(N + 10)}
    best[0][0] = 1

    for (i in 0 until N) {
      Arrays.fill(next[0], 0)
      Arrays.fill(next[1], 0)
      for (j in 0 .. N) {
        for (s in 0 until 2) { // reflexiveを満たさない
          for (k in 0 until 2) { // 追加するか
            for (l in 0 until 2) { // 連結するか
              if (k == 0 && l == 1) continue
              val nj = if (k == 1 && l == 0) j + 1 else j
              val ns = if (s == 0 && k == 1) 0 else 1
              val c = if (l == 1) j else 1
              next[ns][nj] = (next[ns][nj] + best[s][j] * c) % MOD
            }
          }
        }
      }
      val tmp = best
      best = next
      next = tmp
    }

    debug(best[0])
    debug(best[1])

    out.println(best[1].sum() % MOD)
  }













































  private val isDebug = try {
    // なんか本番でエラーでる
    System.getenv("MY_DEBUG") != null
  } catch (t: Throwable) {
    false
  }

  private var tokenizer: StringTokenizer? = null
  private val reader = BufferedReader(InputStreamReader(stream), 32768)
  private fun next(): String {
    while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
      tokenizer = StringTokenizer(reader.readLine())
    }
    return tokenizer!!.nextToken()
  }

  private fun ni() = next().toInt()
  private fun nl() = next().toLong()
  private fun ns() = next()
  private fun na(n: Int, offset: Int = 0): IntArray {
    return map(n) { ni() + offset }
  }
  private fun nal(n: Int, offset: Int = 0): LongArray {
    val res = LongArray(n)
    for (i in 0 until n) {
      res[i] = nl() + offset
    }
    return res
  }

  private fun na2(n: Int, offset: Int = 0): Array<IntArray> {
    val a  = Array(2){IntArray(n)}
    for (i in 0 until n) {
      for (e in a) {
        e[i] = ni() + offset
      }
    }
    return a
  }

  private inline fun map(n: Int, f: (Int) -> Int): IntArray {
    val res = IntArray(n)
    for (i in 0 until n) {
      res[i] = f(i)
    }
    return res
  }

