    if (a != 0 && b != 0) {
        if (a > b) return gcd(a % b, b)
        else return gcd(b % a, a)
    }

    return a + b
}

fun gcde(a: Int, b: Int): Triple<Int, Int, Int> {
    if (a == 0) {
        return Triple(b, 0, 1)
    }

    val (d, x1, y1) = gcde(b % a, a)

    return Triple(d, y1 - (b / a) * x1, x1)
}

