data class Point(val row: Int, val col: Int)

fun main() {
    val (n, m) = readSomeInts()

    fun neighbors(p: Point): List<Point> {
        val acc = mutableListOf<Point>()
        if (p.row > 0) {
            acc.add(Point(p.row - 1, p.col))
        }
        if (p.col > 0) {
            acc.add(Point(p.row, p.col - 1))
        }
        if (p.col < m - 1) {
            acc.add(Point(p.row, p.col + 1))
        }
        if (p.row < n - 1) {
            acc.add(Point(p.row + 1, p.col))
        }
        return acc
    }

    val field = mutableListOf<String>().apply {
        repeat(n) {
            val s = readString()
            this.add(s)
        }
    }.toList()

    fun hasWolf(p: Point) = field[p.row][p.col] == 'W'

    val wolfNotHangry = Array<BooleanArray>(n) { BooleanArray(m) }

    var countEatenPigs = 0
    for (i in 0 until n) {
        for (j in 0 until m) {
            if (field[i][j] == 'P') {
                val pigPt = Point(i, j)
                val anyWolf = neighbors(pigPt)
                        .firstOrNull { pt -> hasWolf(pt) && wolfNotHangry[pt.row][pt.col] }
                if (anyWolf != null) {
                    wolfNotHangry[anyWolf.row][anyWolf.col] = true
                    countEatenPigs++
                }
            }
        }
    }
    println(countEatenPigs)
}

fun main() {
    val table = Table()

    val notEatenPig: (Cell) -> Boolean = { it is PigCell && !it.eaten }

    // eat variant pig
    fun eatPig(nearbyCount: Int): Int {
        println("eat for $nearbyCount pigs")
        var eatCount = 0
        table.forEachIndexed { x, y, cell ->
            if (cell is WolfeCell && !cell.eat) {
                val nearbyPigs = table.nearby(x, y, notEatenPig)
                if (nearbyPigs.size == nearbyCount) {
                    cell.eat = true
                    (nearbyPigs.first() as PigCell).eaten = true
                    eatCount += 1
                    println("wolf on ($x, $y) eat pig")
                }
            }
        }
        return eatCount
    }

    println((1..4).fold(0) { acc, count -> acc + eatPig(count) })
}

class Table {
    private val matrix: List<List<Cell>>
    private val n: Int
    private val m: Int

    init {
        readLine()!!.split(" ")
            .map(String::toInt)
            .also {
                n = it[0]
                m = it[1]
            }

        matrix = (0 until n).map {
            readLine()!!.toCharArray().take(m)
                .map {
                    when (it) {
                        'P' -> PigCell()
                        'W' -> WolfeCell()
                        '.' -> EmptyCell
                        else -> throw IllegalArgumentException("Unknown animal")
                    }
                }
        }
    }

    fun forEachIndexed(action: (x: Int, y: Int, cell: Cell) -> Unit) {
        matrix.forEachIndexed { i, row ->
            row.forEachIndexed { j, cell -> action(i, j, cell) }
        }
    }

    private fun inRange(x: Int, y: Int) = x in 0 until n && y in 0 until m

    fun nearby(x: Int, y: Int, predicate: (Cell) -> Boolean): List<Cell> {
        return listOf(
            Pair(x - 1, y),  // left
            Pair(x + 1, y),  // right
            Pair(x, y - 1),  // top
            Pair(x, y + 1)   // bottom
        )
            .filter { (x, y) -> inRange(x, y) }
            .map { (x, y) -> matrix[x][y] }
            .filter(predicate)
    }
}

