class ClickSequence(val currentDisplay: Int, val target: Int, val currentClicks: Int) : Comparable<ClickSequence> {
    private val predictedClicks = getNaiveClicks(currentDisplay, target) + currentClicks

    override fun compareTo(other: ClickSequence): Int {
        return this.predictedClicks.compareTo(other.predictedClicks)
    }
}

fun getNaiveClicks(currentDisplay: Int, target: Int) : Int {
    if (currentDisplay >= target)
        return currentDisplay - target
    else {
        return 1 + getNaiveClicks(2*currentDisplay, target)
    }
}

fun getMinimumClicks(displayNumber: Int, targetNumber: Int) : Int {
    if (displayNumber >= targetNumber)
        return displayNumber - targetNumber

    val pq = PriorityQueue<ClickSequence>()
    pq.add(ClickSequence(displayNumber - 1, targetNumber, 1))
    pq.add(ClickSequence(displayNumber * 2, targetNumber, 1))

    var curElement = pq.poll()
    while (curElement.currentDisplay != curElement.target) {
        pq.add(ClickSequence(curElement.currentDisplay - 1, curElement.target, curElement.currentClicks + 1))
        pq.add(ClickSequence(curElement.currentDisplay * 2, curElement.target, curElement.currentClicks + 1))
        curElement = pq.poll()
    }

    return curElement.currentClicks
}

