var best = Long.MAX_VALUE

fun find(n : Long, m : Long, steps : Int) : Long{
    if (m <= n){
        best = min(steps + n - m, best)
        return best
    }

    if (steps < best){
        return min(find( n * 2, m, steps + 1), find(n - 1, m, steps + 1) )
    }else return best
}

