class PropagatingSegmentTree(
    val size: Int
) {
    inline fun combiner(a: Long, b: Long): Long = min(a, b)
    inline fun updateCombiner(a: Long, b: Long): Long = a + b
    inline fun updater(t: Long, u: Long): Long = t + u

    private inline fun treeSize() = if(size == 0) 0 else Integer.highestOneBit(size.shl(2) - 1)

    private val tree = LongArray(treeSize()) { Long.MAX_VALUE }
    private val lazy = LongArray(tree.size)

    fun build(list: LongArray) {
        if(size == 0) return
        build(list, 1, 0, size-1)
    }

    fun build(generator: (Int) -> Long) { build(LongArray(size, generator)) }

    private inline fun mid(low: Int, high: Int) = (low + high) shr 1
    private fun build(list: LongArray, node: Int, a: Int, b: Int) {
        if(a == b) {
            tree[node] = list[a]
            return
        }

        build(list, node shl 1, a, mid(a, b))
        build(list, node shl 1 or 1, 1 + mid(a, b), b)
        updateNode(node)
    }

    private inline fun updateNode(i: Int) {
        tree[i] = combiner(tree[i shl 1], tree[i shl 1 or 1])
    }

    fun update(first: Int, last: Int, value: Long) {
        update(1, 0, size-1, first, last, value)
    }
    fun update(range: IntRange, value: Long) {
        update(range.first, range.last, value)
    }

    private inline fun updateLazy(i: Int, u: Long) {
        lazy[i] = updateCombiner(lazy[i], u)
    }

    private fun propagate(node: Int, a: Int, b: Int) {
        tree[node] = updater(tree[node], lazy[node])
        if(a != b) {
            updateLazy(node shl 1, lazy[node])
            updateLazy(node shl 1 or 1, lazy[node])
        }
        lazy[node] = 0L
    }

    private fun update(node: Int, a: Int, b: Int, i: Int, j: Int, u: Long) {
        if(lazy[node] != 0L) {
            propagate(node, a, b)
        }

        if(a > b || a > j || b < i) return

        if(a >= i && b <= j) {
            lazy[node] = u
            propagate(node, a, b)
            return
        }

        update(node shl 1, a, mid(a, b), i, j, u)
        update(node shl 1 or 1, 1 + mid(a, b), b, i, j, u)

        updateNode(node)
    }

    fun query(first: Int, last: Int) =
        query(1, 0, size-1, first, last)
    fun query(range: IntRange) =
        query(range.first, range.last)

    private fun query(node: Int, a: Int, b: Int, i: Int, j: Int): Long {
        if(a > b || a > j || b < i) return Long.MAX_VALUE
        if(lazy[node] != 0L) {
            propagate(node, a, b)
        }

        if(a >= i && b <= j) {
            return tree[node]
        }

        val l = query(node shl 1, a, mid(a, b), i, j)
        val r = query(node shl 1 or 1, 1 + mid(a, b), b, i, j)

        return combiner(l, r)
