/**
 * Точки на прямой
 */
fun taskA() {
    val s = Scanner(System.`in`)
    val n = s.nextInt()
    val desiredDiameter = s.nextInt()
    val numbers = Array(n, { _ -> 0 })

    for (i in 0..n-1) {
        numbers[i] = s.nextInt()
    }

    numbers.sort()

    var from = 0
    var to = 0
    var optimalRemoved = Int.MAX_VALUE
    while (to <= numbers.lastIndex) {
        val d = numbers[to] - numbers[from]

        if (d <= desiredDiameter) {
            optimalRemoved = minOf(from + (numbers.size - to - 1), optimalRemoved)
        }

        if (d <= desiredDiameter) {
            to++
        } else {
            from++
        }
    }

    println(optimalRemoved)
}

/**
 * Наша Таня громко плачет
 */
fun taskB() {
    val s = Scanner(System.`in`)
    val n = s.nextInt()
    val k = s.nextInt()
    val subPrice = s.nextInt()
    val divPrice = s.nextInt()

    var curN = n
    var totalPrice = 0
    while (curN != 1) {
        val r = curN % k
        when {
            k == 1 -> {
                totalPrice = (curN - 1) * subPrice
                curN = 1
            }
            r == 0 -> {
                val subTotal = subPrice * (curN/k) * (k-1)
                if (subTotal < divPrice) {
                    totalPrice += subTotal
                } else {
                    totalPrice += divPrice
                }
                curN /= k
            }
            else -> {
                totalPrice += subPrice * r
                curN -= r

                // ugly check if curN under k so we could get zero
                if (curN == 0) {
                    curN = 1
                    totalPrice -= subPrice
                }
            }
        }
    }
    println(totalPrice)
}

