    val divisor = readLong()
    val subtractCost = readLong()
    val divideCost = readLong()
    var cost = BigInteger.ZERO
    val mod = x % divisor
    if (mod != 0L) {
        cost += BigInteger.valueOf(mod * subtractCost)
        x -= mod
    }
    while (x >= divisor && divideCost <= subtractCost * (x - x/divisor)) {
        cost += BigInteger.valueOf(divideCost)
        x /= divisor
    }
    cost += BigInteger.valueOf(subtractCost * (x - 1))
    print(cost.toString())
