package contest612


var n: Int = 0
var lights = emptyList<Int>()


var save = Array(102) { Array(102) { Array(102) { IntArray(2) { -1 } } } }
fun dp(index: Int, odd: Int, even: Int, isOdd: Boolean): Int {
    if (index >= lights.size) {
        return 0
    }
    val oddIndex: Int = if (isOdd) 0 else 1
    if (save[index][odd][even][oddIndex] != -1) return save[index][odd][even][oddIndex]
    var min = Int.MAX_VALUE
    if (lights[index] == 0) {
        if (odd > 0) {
            min = Math.min(min, getCom(isOdd, true) + dp(index + 1, odd - 1, even, true))
        }
        if (even > 0) {
            min = Math.min(min, getCom(isOdd, false) + dp(index + 1, odd, even - 1, false))
        }
    } else {
        val curIsOdd = lights[index] % 2 != 1
        min = getCom(isOdd, curIsOdd) + dp(index + 1, odd, even, curIsOdd)
    }
    save[index][odd][even][oddIndex] = min
    return min
}

fun getCom(odd: Boolean, odd2: Boolean): Int {
    return if (odd == odd2) {
        0
    } else {
        1
    }
}


