        if (p[j] != 0 && p[j - 1] != 0 && (p[j] + p[j - 1]) % 2 != 0) {
            answer++
        }
    }
    //println("alpha $answer")
    val remOdd = mutableSetOf<Int>()
    val remEven = mutableSetOf<Int>()
    for (j in 1..n) {
        if (j % 2 == 0) {
            remEven.add(j)
        } else {
            remOdd.add(j)
        }
    }
    for (a in p) {
        remEven.remove(a)
        remOdd.remove(a)
    }
    val evenLengths = mutableListOf<Int>()
    val oddLengths = mutableListOf<Int>()
    var j = 0
    while (true) {
        while (j < n - 1 && (p[j] == 0 || p[j + 1] != 0)) {
            j++
        }
        if (j == n - 1) {
            break
        }
        //println("j = $j")
        var left = p[j] % 2
        j++
        while (j < n && p[j] == 0) {
            j++
        }
        if (j == n) {
            break
        }
        //println("now j = $j")
        var right = p[j] % 2
        if (left == right) {
            j--
            val chosenRem = if (right == 0) remEven else remOdd
            val otherRem = if (right == 1) remEven else remOdd
            while (p[j] == 0) {
                if (chosenRem.isNotEmpty()) {
                    p[j] = chosenRem.first()
                    chosenRem.remove(p[j])
                } else {
                    p[j] = otherRem.first()
                    otherRem.remove(p[j])
                    answer += 2
                }
                j--
            }
        } else {
            answer++
        }
    }
    //println("beta $answer")
    j = 0
    while (j < n && p[j] == 0) {
        j++
    }
    if (j == n) {
        println(1)
        return
    }
    var chosenRem = if (p[j] % 2 == 0) remEven else remOdd
    var otherRem = if (p[j] % 2 == 1) remEven else remOdd
    j--
    while (j >= 0) {
        if (chosenRem.isNotEmpty()) {
            p[j] = chosenRem.first()
            chosenRem.remove(p[j])
        } else {
            p[j] = otherRem.first()
            otherRem.remove(p[j])
            answer++
        }
        j--
    }
    //println("gamma $answer")
    j = n - 1
    while (j >= 0 && p[j] == 0) {
        j--
    }
    chosenRem = if (p[j] % 2 == 0) remEven else remOdd
    otherRem = if (p[j] % 2 == 1) remEven else remOdd
    j++
    while (j < n) {
        if (chosenRem.isNotEmpty()) {
            p[j] = chosenRem.first()
            chosenRem.remove(p[j])
        } else {
            p[j] = otherRem.first()
            otherRem.remove(p[j])
            answer++
        }
        j++
    }
