fun main(args: Array<String>) {
	var n = readInt()
	var p = readInts().map{it-1}
	var used = BooleanArray(n)
	for(i in p)
		if(i!=-1)
			used[i]=true
	var gaps = Array(2){Array(2){ArrayList<Int>()}}
	var numCnt = Array<Int>(2){0}
	for(i in 0..n-1)
		if(!used[i])
			numCnt[i%2]++

	var prv = -1
	var cnt = 0
	for(i in p)
		if(i!=-1) {
			if(prv==-1)
				prv=i
			if(cnt!=0) {
				gaps[prv%2][i%2].add(cnt)
			}
			cnt=0
			prv=i
		}
		else
			cnt++
	if(cnt!=0) {
		if(prv==-1)
			prv=0
		gaps[prv%2][prv%2].add(cnt)
	}
	var res = 0
	for(i in 1..n-1)
		if(p[i]!=-1 && p[i-1]!=-1 && p[i-1]%2!=p[i]%2)
			res++

	res+=gaps[1][0].size+gaps[0][1].size

	for(i in 0..1) {
		gaps[i][i].sort()
		for(j in gaps[i][i])
			if(numCnt[i]>=j) {
				numCnt[i]-=j
			}
			else
				res++
	}

	println(res)
}

import java.lang.Integer.max
import java.util.*

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    var minElement = Int.MAX_VALUE
    var maxElement = Int.MIN_VALUE
    var minElementPos = -1
    var maxElementPos = -1

    repeat (n) {
        val current = scanner.nextInt()
        if (current < minElement) {
            minElement = current
            minElementPos = it
        } else if (current > maxElement) {
            maxElement = current
            maxElementPos = it
        }
    }

    if (minElementPos < maxElementPos) {
        println(max(maxElementPos, n - 1 - minElementPos))
    } else {
        println(max(minElementPos, n - 1 - maxElementPos))
    }
}

