// 25 50 75 00
fun main(args: Array<String>) = with(Scanner(System.`in`)) {
    val n = nextLine()
    val l = n.length
    val ref = ArrayList<Int>()

    var flag = false

    val _0 = n.count { it == '0' }
    val _2 = n.count { it == '2' }
    val _5 = n.count { it == '5' }
    val _7 = n.count { it == '7' }

    var leadingZeros = 0
    for (i in 1 until l) {
        if (n[i] == '0') {
            leadingZeros++
        } else {
            break
        }
    }

    if (_0 >= 2) { // ..00
        flag = true

        val i0a = n.lastIndexOf('0')
        val i0b = n.substring(0 until i0a).lastIndexOf('0')

        ref.add(2 * l - i0a - i0b - 3)
    }

    if (_2 >= 1 && _5 >= 1) if (leadingZeros != l - 2 || l == 2) { // ..25
        flag = true

        val i2 = n.lastIndexOf('2')
        val i5 = n.lastIndexOf('5')

        var r = 2 * l - i2 - i5 - 3
        if (i2 > i5) {
            if (i5 == 0) r += leadingZeros
            r += 1
        } else {
            if (i2 == 0) r += leadingZeros
        }

        ref.add(r)
    }

    if (_5 >= 1 && _0 >= 1) if (leadingZeros != l - 1) { // ..50
        flag = true
        var _leadingZeros = leadingZeros

        val i5 = n.lastIndexOf('5')
        val i0 = n.lastIndexOf('0')

        if (i0 == _leadingZeros) _leadingZeros--

        var r = 2 * l - i5 - i0 - 3
        if (i5 > i0) {
            r += 1
        } else {
            if (i5 == 0) r += _leadingZeros
        }

        ref.add(r)
    }

    if (_7 >= 1 && _5 >= 1) if (leadingZeros != l - 2 || l == 2) { // ..75
        flag = true

        val i7 = n.lastIndexOf('7')
        val i5 = n.lastIndexOf('5')

        var r = 2 * l - i7 - i5 - 3
        if (i7 > i5) {
            if (i5 == 0) r += leadingZeros
            r += 1
        } else {
            if (i7 == 0) r += leadingZeros
        }

        ref.add(r)
    }

    if (flag) {
        println(ref.min())
    } else {
        println(-1)
    }
}

