fun solve(a: Long, b: Long): Int {
    if(a == 0L && b == 0L) return 1

    var res = b % 10

    for(i in b - 1 downTo a + 1) {
        res = (res * (i % 10)) % 10
        if(res % 10 == 0L) return 0
    }
    return res.toInt()
}

