fun calcMaxLen(s: String, t: String): Int {
    val sLen = s.length
    val tLen = t.length
    if (sLen == tLen)
        return 0

    val relIdxs: MutableList<MutableList<Int>> = mutableListOf()
    for (j: Int in 0 until tLen) {
        val c = t[j]
        val idxs = s.withIndex().filter { it.value == c }.map { it.index }
        relIdxs.add(idxs.toMutableList())
    }

    var prevBgnIdx = -1
    for (j: Int in 0 until tLen) {
        relIdxs[j].removeAll { it <= prevBgnIdx }
        prevBgnIdx = relIdxs[j][0]
    }

    var prevEndIdx = sLen
    for (j: Int in tLen - 1 downTo 0) {
        relIdxs[j].removeAll { it >= prevEndIdx }
        prevEndIdx = relIdxs[j].last()
    }

    val m0 = relIdxs[0].last()
    val mz = sLen - relIdxs.last().first() - 1
    val m0z = if (mz > m0) mz else m0


    val mp = relIdxs.fold(Pair(m0z, relIdxs[0])) { (z, prev), xs ->
        val mx = xs.last() - prev.first() - 1
        Pair(if (mx > m0) mx else m0, xs)
    }

    return mp.first
}

