class DP(val n1 : Int, val n2 : Int, val k1 : Int,val  k2 : Int){


    val map = Array(201) { Array(101) { Array(11) { IntArray(11) { -1 } } } }

    fun dp(pos : Int, horses : Int, lastHorses : Int, lastMen : Int) : Int {
        //dp[pos][horses already placed][last placed horsed][last placed men]  200*100*10*10 ~ 2 million states , should be okay
        //possible optimisation if we get TLE dp[pos][horses already placed][last placed whom ?][quantity] 200*100*2*10  ~ 0.4 million states

        if (pos == n1 + n2 + 1) return 1

        if (map[pos][horses][lastHorses][lastMen] != -1) return map[pos][horses][lastHorses][lastMen]
        val horsesRemaingToBePlaced = n2 - horses
        val footMenRemainingToBePlaced = n1 - (pos - 1 - horses)

        var ways= 0

        if (horsesRemaingToBePlaced != 0 && lastHorses < k2){
            //horse can be placed
            ways+= dp(pos + 1, horses + 1, lastHorses + 1, 0 )
        }
        if (footMenRemainingToBePlaced != 0 && lastMen < k1){
            ways+= dp(pos + 1, horses, 0, lastMen + 1)
        }

        map[pos][horses][lastHorses][lastMen] = ways
        return ways
    }
}

