fun main() {
    val r = System.`in`.bufferedReader()
    val s = StringBuilder()
    val (n, changeTime) = r.readLine()!!.split(" ").map { it.toInt() }
    val v = r.readLine()!!
    val t = r.readLine()!!
    // dp[i][j][k] i mean ith char( start from 0 ), j mean change times, k mean number of t[0] in front
    val dp = List(n) { List(changeTime + 1) { MutableList(n + 1) { -1 } } }
    if (v[0]==t[0]){
        dp[0][0][1] = 0
    } else{
        dp[0][0][0] = 0
        dp[0][1][1] = 0
    }
    // Start with character 0, end with n-1. this build next, not prev build this
    for (i in 0 until n-1) {
        // Loop through change time, vary from 0 to c,
        for (j in 0 until changeTime + 1) {
            // Loop through how many t[0] include ith character in the front, not include ith char
            for (k in 0 until n) {
                // Is not start state came from
                if (dp[i][j][k]==-1) continue
                // current char is t[0]
                val t0 = if (v[i + 1] == t[0]) 1 else 0
                // current char is t[1]
                val t1 = if (v[i + 1] == t[1]) 1 else 0
                // do not change ith char
                dp[i + 1][j][k + t0] =
                    maxOf(dp[i + 1][j][k + t0], dp[i][j][k] + if (t1 == 1) k else 0)
                //println("i is $i")
                //println("do not change, i: $i, j: $j, k: $k, before: ${dp[i][j][k]}, after: ${dp[i + 1][j][k + t0]}")
                // change ith character
                //println("dp[$i][$j][$k] is ${dp[i][j][k]}, if not change, ${dp[i + 1][j][k + t0]}")
                if (j < changeTime) {
                    val same = if (t[0] == t[1]) 1 else 0
                    // change to t[0], even it is t[0]
                    dp[i + 1][j + 1][k + 1] =
                        maxOf(dp[i + 1][j + 1][k + 1], dp[i][j][k] + if (same == 1) k else 0)
                    // change to t[1], even it is t[1]
                    dp[i + 1][j + 1][k] = maxOf(dp[i + 1][j + 1][k], dp[i][j][k] + k)
                    //println("change to t[0], ${dp[i + 1][j + 1][k + 1]}, change to t[1], ${dp[i + 1][j + 1][k]}")
                }
            }
        }
    }
    var max = 0
    //dp.forEach { println(it) }
    for (i in 0 until changeTime + 1) {
        for (j in 0 until n + 1) {
            max = maxOf(max, dp[n-1][i][j])
        }
    }
    print(max)
}

