fun main() {
    val (n, k) = readIntArray(2)

    val s = read()
    val t = read()

    if (t[0] == t[1]) {
        val count = min(s.count { it == t[0] } + k, n).toLong()
        println(count*(count - 1) / 2)
    } else {
        val dp = Array(n) {Array(n) {LongArray(k + 1) {-1L} } }

        fun solve(pos: Int, fstCount: Int, k: Int): Long {
            if (pos >= n) {
                return 0
            }

            if (dp[pos][fstCount][k] == -1L) {
                var res = 0L
                if (s[pos] == t[0]) {
                    res = solve(pos + 1, fstCount + 1, k)
                    if (k > 0) {
                        res = max(res, solve(pos + 1, fstCount, k - 1) + fstCount)
                    }
                } else if (s[pos] == t[1]) {
                    res = fstCount + solve(pos + 1, fstCount, k)
                    if (k > 0) {
                        res = max(res, solve(pos + 1, fstCount + 1, k - 1))
                    }
                } else {
                    res = solve(pos + 1, fstCount, k)
                    if (k > 0) {
                        res = max(solve(pos + 1, fstCount, k - 1) + fstCount, solve(pos + 1, fstCount + 1, k - 1))
                    }
                }

                dp[pos][fstCount][k] = res
            }

            return dp[pos][fstCount][k]
        }

        println(solve(0, 0, k))
    }
}

