    private fun sieve(max: Int): BitSet {
        val primeMap = BitSet(max)
        primeMap.set(0, primeMap.size() - 1)
        primeMap.set(0, false)

        for (i in 2..primeMap.size()) {
            if (primeMap[i - 1]) {
                for (j in i + i..primeMap.size() step i) {
                    primeMap.set(j - 1, false)
                }
            }
        }

        return primeMap
    }
}

