    if (args.size > 0) System.setIn(FileInputStream(args[0]))
    val br = BufferedReader(InputStreamReader(System.`in`))
    val bw = BufferedWriter(OutputStreamWriter(System.out))

    var st = StringTokenizer(br.readLine())
    val a = st.nextToken().toInt()
    var b = st.nextToken().toInt()
    val arr = mutableListOf(b)
    while (a < b) {
        if (b and 1 == 0) {
            b /= 2
        } else {
            b -= 1
            b /= 10
        }
        arr.add(b)
    }
    if (a == b) {
        bw.write("YES\n${arr.size}\n")
        bw.write(arr.reversed().joinToString(separator = " "))
    }
    else bw.write("NO")
    bw.newLine()
    bw.flush()
}

import java.util.*
import java.util.Queue

fun main(){
    var scanner : Scanner = Scanner(System.`in`)
    var a : Int = scanner.nextInt()
    var b : Int = scanner.nextInt()
    var visited : MutableMap<Int, Boolean> = mutableMapOf(
            a to true
    )
    var parent : MutableMap<Int,Int> = mutableMapOf()
    var done : Boolean = false
    var bfs_q : Queue<Int> = LinkedList<Int>()
    bfs_q.add(a)
    parent[a] = a
    while(!bfs_q.isEmpty()){
        var curr : Int = bfs_q.peek()
        bfs_q.remove()

        if (curr == b){
            done = true
            break
        }

        var c1 : Int = curr * 2
        var c2 : Int = 10 * curr + 1

        if(c1 >= 0 && c1 <= 1e9 && !visited.containsKey(c1)){
            visited[c1] = true
            bfs_q.add(c1)
            parent[c1] = curr
        }
        if(c2 >= 0 && c2 <= 1e9 && !visited.containsKey(c2)){
            visited[c2] = true
            bfs_q.add(c2)
            parent[c2] = curr
        }
    }

    if(!done){
        print("NO")
    } else {
        println("YES")
        var steps : Stack<Int> = Stack<Int>()

        var currStep : Int = b
        while(currStep != a) {
            steps.push(currStep)
            currStep = parent[currStep]!!
        }
        steps.push(a)
        println(steps.size)
        while(!steps.isEmpty()){
            print("${steps.peek()} ")
            steps.pop()
        }
    }

}

