    val dx = arrayOf(-1, -1, -1, 0, 0, 1, 1, 1)
    val dy = arrayOf(-1, 0, 1, -1, 1, -1, 0, 1)
    for(i in 0 until 4) {
        for(j in 0 until 4) {
            for(k in 0 until dx.size) {
                var good = 0
                var valid = true
                for(l in 0 until 3) {
                    var nx = i + dx[k] * l
                    var ny = j + dy[k] * l
                    if(nx < 0 || nx >= 4 || ny < 0 || ny >= 4) valid = false
                    if(valid && g[nx][ny] == 'x') good++
                }
                if(good == 2 && valid) {
                    println("YES")
                    System.exit(0);
                }
            }
        }
    }
    println("NO")
}

