const val MOD = 1000000007L

fun main() {
    val n = readLine()!!.toInt()
    val factorial = LongArray(n + 1)
    factorial[0] = 1L
    for (j in 1..n) {
        factorial[j] = (j.toLong() * factorial[j - 1]) % MOD
    }
    val factInv = LongArray(n + 1) { factorial[it] pow -1 }
    fun permute(a: Int, b: Int) = if (b < 0L || b > a) 0L else ((factorial[a] * factInv[b]) % MOD)
    fun arrange(a: Int, b: Int): Long {
        val here = n / a
        val above = here / b
        return ((here - above).toLong() * permute(n - above - 1, n - here)) % MOD
    }
    var lg = 0
    while (1 shl lg <= n) {
        lg++
    }
    lg--
    var curr = factorial[n - (n / 2)]
    for (e in 1..lg) {
        curr *= arrange(1 shl e, 2)
    }
    var answer = curr
    if (n >= 3 * (1 shl (lg - 1))) {
        for (e in lg downTo 1) {
            curr *= arrange(1 shl e, 3) pow -1
            curr %= MOD
            curr *= arrange(3 * (1 shl (e - 1)), 2)
            curr %= MOD
            if (e > 1) {
                curr *= arrange(1 shl (e - 1), 2) pow -1
                curr %= MOD
                curr *= arrange(1 shl (e - 1), 3)
                curr %= MOD
            } else {
                curr *= factInv[n - (n / 2)]
                curr %= MOD
                curr *= factorial[n - (n / 3)]
                curr %= MOD
            }
            answer += curr
        }
        answer %= MOD
    }
    println(answer)
}

val MOD_TOTIENT = (MOD - 1).toInt()

infix fun Long.pow(power: Int): Long {
    var e = power
    e %= MOD_TOTIENT
    if (e < 0) {
        e += MOD_TOTIENT
    }
    if (e == 0 && this == 0L) {
        return this
    }
    var b = this % MOD
    var res = 1L
    while (e > 0) {
        if (e and 1 != 0) {
            res *= b
            res %= MOD
        }
        b *= b
        b %= MOD
        e = e shr 1
    }
    return res
}

