class B {
    fun run() {
        val sc = Scanner(systemIn())
        val n=sc.nextInt()
        val s=sqrt(n.toDouble()).toInt()
        var r=n-s*s

        var ans=s
        var nextS=s
        var flip=true
        val seq= generateSequence {
            val tmp=nextS
            if(flip)
                nextS++
            flip=!flip
            tmp
        }.iterator()

        while(r>0) {
            ans++
            r-=seq.next()
        }

        println("$ans")
    }

    companion object {
        var inputStr: String? = null

        fun systemIn(): InputStream {
            if (inputStr != null)
                return ByteArrayInputStream(inputStr!!.toByteArray())
            else
                return System.`in`
        }

        var printLog = false
        fun log(str: String) {
            if (printLog)
                println(str)
        }
    }
}

