fun ex1(n: Int): Pair<Int, Int> {
    var a = n / 2
    var b = n - a

    if (a == b) {
        a--
        b++
    }

    while(a != 1) {
        if (nod(a, b) == 1) return a to b
        a--
        b++
    }

    return a to b
}

fun nod(a: Int, b: Int): Int {
    var tmp: Int
    var valA = a
    var valB = b

    while(valB != 0) {
        tmp = valB
        valB = valA % valB
        valA = tmp
    }

    return valA
}

