fun solve(input: InputStream, output: OutputStream) {
    val reader = InputReader(BufferedInputStream(input))
    val writer = PrintWriter(BufferedOutputStream(output))

    solve(reader, writer)
    writer.close()
}

fun solve(reader: InputReader, writer: PrintWriter) {
    val n = reader.nextInt()
    val d = reader.nextInt()

    val a = mutableMapOf<Int, Int>().toSortedMap()
    for (i in 0 until n) {
        val x = reader.nextInt()
        a.put(x, a.getOrDefault(x, 0) + 1)
    }

    if (a.size == 1) {
        writer.print("0")
        return
    }

    var ans = n
    var v = a.map { it.key }
    for (i in 0 until v.lastIndex) {
        val c = a.filter { it.key < v[i] || it.key > v[i] + d }.map { it.value }.sum()
        ans = min(ans, c)
    }

    writer.print(ans)
}

class InputReader(stream: InputStream) {
    val reader: BufferedReader
    var tokenizer: StringTokenizer? = null

    init {
        reader = BufferedReader(InputStreamReader(stream), 32768)
        tokenizer = null
    }

    operator fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        }
        return tokenizer!!.nextToken()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

    fun nextArrayInt(count: Int): IntArray {
        return nextArrayInt(0, count)
    }

    fun nextArrayInt(start: Int, count: Int): IntArray {
        val a = IntArray(start + count)
        for (i in start until start + count) {
            a[i] = nextInt()
        }
        return a
    }

    fun nextArrayLong(count: Int): LongArray {
        val a = LongArray(count)
        for (i in 0 until count) {
            a[i] = nextLong()
        }
        return a
    }
}

fun main() {
    fun readInts() = readLine()!!.split(" ").map(String::toInt)

    fun List<Int>.bsRight(value: Int): Int {
        var left = 0
        var right = this.lastIndex
        var pivot: Int
        while (left <= right) {
            pivot = (left + right) / 2
            if (this[pivot] > value) right = pivot - 1 else left = pivot + 1
        }
        return left - 1
    }

    val (numPoints, diameter) = readInts()
    val arr = readInts().sorted()
    val stop = arr.last() - diameter
    if (stop <= arr[0]) {
        print(0)
        return
    }
    var result = Integer.MAX_VALUE
    var left = -1
    var right: Int
    while (++left < numPoints && arr[left] <= stop) {
        right = arr.bsRight(arr[left] + diameter)
        val candidate = numPoints - right + left - 1
        if (candidate < result) result = candidate
    }
    print(result)
}

