fun binExp(a: Int, n: Int): Int{
    tailrec fun go(a: Int, n: Int, a1: Int): Int{
        if (n == 0) return 1
        if (n == 1) return a * a1

        if (n % 2 == 0) return go(a * a, n/2, a1)
        else return go(a * a, (n - 1)/2, a * a1)
    }
    return go(a, n, 1)
}

