fun Long.sqrtFloor() = sqrt(toDouble()).toLong()

fun primeSieve(upperLimit: Long): Sequence<Long> = sequence {
    yield(2L)
    val source = (3..upperLimit step 2).toMutableSet()

    while(source.isNotEmpty()) {
        val prime = source.first()
        yield(prime)
        source.remove(prime)
        source.removeAll(prime * prime .. upperLimit step prime)
    }
}

