fun move(candies: MutableList<Int>, previous: Int): Int {
    var size = 0
    if (candies.sum() > previous) {
        while (size <= previous) {
            size += candies[0]
            candies.removeAt(0)
        }
    } else {
        size = candies.sum()
        candies.clear()
    }

    return size
}

