fun simulateGame(candyList: List<Int>): Triple<Int, Int, Int> {
    var a = 0
    var b = 0
    var step = 0

    var lastSum = 0
    val currentCandyList = candyList.toMutableList()

    while (currentCandyList.isNotEmpty()) {
        var currentSum = 0

        while (currentSum <= lastSum && currentCandyList.isNotEmpty()) {
            if (!step.isOdd()) {
                val candy = currentCandyList.removeFirst()
                currentSum += candy
                a += candy
            } else {
                val candy = currentCandyList.removeLast()
                currentSum += candy
                b += candy
            }
        }

        lastSum = currentSum
        step++
    }

    return Triple(step, a, b)
}

fun Int.isOdd(): Boolean = this % 2 != 0

