private fun solve() {
    var n = readInt();
    var a1 = readInts();
    val q = ArrayDeque<Int>(a1);

    var numMoves = 0;
    var a = 0;
    var b = 0;
    var prevA = 0;
    var prevB = 0;
    while (q.isNotEmpty()) {
        var curA = 0;
        while (curA <= prevB && q.isNotEmpty()) {
            curA += q.removeFirst();
        }
        a += curA;
        prevA = curA;
        if (curA > 0) {
            numMoves++;
        }

        var curB = 0;
        while (curB <= prevA && q.isNotEmpty()) {
            curB += q.removeLast();
        }
        b += curB;
        prevB = curB;
        if (curB > 0) {
            numMoves++;
        }
    }
    println("$numMoves $a $b");
}

