fun getAnswer(n : Long, k : Long) : Long {
    var result = 0L

    if (k <= n) {
        result = k / 2
    } else {
        val maxPossible = n
        val minPossible = k - n

        val count = Math.max(0L, (maxPossible - minPossible + 1))
        result = count / 2
    }

    if (k % 2 == 0L) {
        val half = k / 2
        if (half <= n) result = Math.max(result - 1, 0)
    }

    return result
}

class FenwickTree(n : Int) {

    val size = n + 1
    val tree = LongArray(size) { 0L }

    fun update(index : Int, delta : Int) {
        var x = index + 1
        while (x < size) {
            tree[x] = tree[x] + delta
            x += x and -x
        }
    }

    fun get(start : Int, end : Int) =
            get(end) - get(start - 1)

    fun get(index : Int) : Long {
        var result : Long = 0

        var x = index + 1
        while (x > 0) {
            result += tree[x]
            x -= x and -x
        }

        return result
    }
}

