fun readGraph(n: Int, m : Int,
              undirected : Boolean = true,
              indexing : Int = 1) : Graph {
    val builder = GraphBuilder()

    for (i in 1..m) {
        var (from, to) = readInts()

        from -= indexing
        to -= indexing

        if (undirected) builder.addEdge(from, to)
        else builder.addDirectedEdge(from, to)
    }

    return builder.build(n)
}

class GraphBuilder {

    val froms : MutableList<Int>
    val tos : MutableList<Int>

    init {
        this.froms = ArrayList<Int>()
        this.tos = ArrayList<Int>()
    }

    fun addEdge(from : Int, to : Int) {
        addDirectedEdge(from, to)
        addDirectedEdge(to, from)
    }

    fun addDirectedEdge(from : Int, to : Int) {
        froms.add(from)
        tos.add(to)
    }

    fun build(n : Int) : Graph {
        val sizes = IntArray(n) { 0 }
        froms.forEach { ++sizes[it] }

        val graph = Array<IntArray>(n) { IntArray(sizes[it]) { 0 } }

        for (i in 0 until n) {
            sizes[i] = 0
        }

        for (i in 0 until froms.size) {
            val from = froms[i]
            val to = tos[i]

            graph[from][sizes[from]++] = to
        }

        return graph
    }
}

