class DSU {

    var sizes : IntArray
    var ranks : IntArray
    var parents : IntArray

    constructor(n : Int)
    : this(
            IntArray(n) { 1 }
    )

    constructor(sizes : IntArray) {
        val size = sizes.size
        this.sizes = sizes
        this.ranks = IntArray(size) { 1 }
        this.parents = IntArray(size) { it }
    }

    operator fun get(v : Int) : Int {
        val parent = parents[v]
        if (parent == v) return v
        parents[v] = get(parent)
        return parents[v]
    }

    fun union(aUniting : Int, bUniting : Int) {
        var a = get(aUniting)
        var b = get(bUniting)

        if (a == b) return

        if (ranks[a] < ranks[b]) {
            val tmp = a
            a = b
            b = tmp
        }

        parents[b] = a
        sizes[a] += sizes[b]
        if (ranks[a] == ranks[b]) ++ranks[a]
    }

    fun size(v : Int) : Int = sizes[get(v)]
}

