fun <T: Comparable<T>> Iterable<T>.kths(k : Int) : T {

    val array = ArrayList<T>()
    array.addAll(this)

    if (k !in 1..array.size) {
        throw IllegalArgumentException()
    }

    fun MutableList<T>.swap(i : Int, j : Int) {
        val temp = this[i]
        this[i] = this[j]
        this[j] = temp
    }

    fun search(l : Int, r : Int, n : Int) : T {

        if (l + 1 >= r) {

            if (array[l] > array[r])
                array.swap(l, r)

            return if (n == 1) array[l] else array[r]
        }

        val pivot = array[(l + r) / 2]
        array.swap((l + r) / 2, l)

        var i = l + 1
        var last = i
        while (i <= r) {

            if (array[i] < pivot) {
                array.swap(i, last)
                last += 1
            }

            i += 1
        }

        array.swap(l, last - 1)

        return when {
            last - l == n -> array[last - 1]
            last - l > n -> search(l, last - 2, k)
            else -> search(last, r, n - last - l)
        }
    }


    return search(0, array.size - 1, k)
}

