fun getOrnamentNumber(b: Int, r: Int): Int {
    if (b != 0) {
        return (b - 1) + b + (b + 1)
    }
    if (r != 0) {
        return (r - 2) + (r - 1) + r
    }

    return 0
}

fun findOrnamentNumber(y: Int, b: Int, r: Int): Int {
    return when (maxOf(y, b, r)) {
        y -> findOrnamentNumber(-1, b, r)
        b -> getOrnamentNumber(0, r)
        r -> getOrnamentNumber(b, 0)
        else -> 0
    }
}

