fun findSolve(yellow : Int, blue : Int, red : Int) : Int {
    val minValue = min(yellow, min(blue, red))
    if (minValue == yellow) {
        var temp = yellow
        while (true) {
            if (temp + 1 <= blue && temp + 2 <= red) {
                return temp * 3 + 3
            }
            temp -= 1
        }
    } else if (minValue == blue) {
        var temp = blue
        while (true) {
            if (temp - 1 <= yellow && temp + 1 <= red) {
                return temp * 3
            }
            temp -= 1
        }
    }
    else {
        var temp = red
        while (true) {
            if (temp - 2 == yellow && temp -1 == blue) {
                return temp * 3 - 3
            }
        }
    }
}

