private class Configuration(var yellow: Int, var blue: Int, var red: Int) {
    fun findPerfectConfiguration(): Configuration {
        val perfectConfiguration = Configuration(this.red - 2, this.red - 1, this.red)

        while (!this.hasEnoughOrnaments(perfectConfiguration)) {
            perfectConfiguration.reduce()
        }

        return perfectConfiguration
    }

    fun sum() = this.yellow + this.blue + this.red

	private fun hasEnoughOrnaments(configuration: Configuration): Boolean {
    	return configuration.yellow <= this.yellow
    		&& configuration.blue <= this.blue
	    	&& configuration.red <= this.red
	}

    private fun reduce() {
        this.yellow--
        this.blue--
        this.red--
    }
}

