object CodeForceIncorrectMinus {

    fun execute(n: String, k: String): String {

        val na = n.toCharArray().mapTo(LinkedList()) { it.toString().toInt() }

        for (ki in 1..k.toInt()) {

            if (na.isEmpty()) {
                break
            }

            val last = na.last
            if (last == 0) {
                na.removeLast()
            } else {
                val lastIndex = na.lastIndex
                na[lastIndex] = last - 1
            }

        }

        return na.fold(StringBuilder()) { sb, i -> sb.append(i.toString()) }.toString()
    }


}

