fun subtractResult(value: ULong, subOp: Int): ULong {
    if (subOp == 0) {
        return value
    } else {
       if ((value % 10UL) == 0UL) {
            return subtractResult((value/10UL),subOp-1)
        } else {
            return subtractResult((value-1UL),subOp-1)
        }
    }
}

