import kotlin.math.max

fun main() {
    var insideParenthesis = false
    readLine()
    var countInside = 0
    var maxOutside = 0
    var count = 0
    for (c in readLine()!!)
        when (c) {
            '_' -> {
                if (insideParenthesis) {
                    if (count > 0) countInside++
                } else maxOutside = max(maxOutside, count)
                count = 0
            }
            '(' -> {
                maxOutside = max(maxOutside, count)
                count = 0
                insideParenthesis = true
            }
            ')' -> {
                if (count > 0) countInside++
                count = 0
                insideParenthesis = false
            }
            else -> count++
        }
    print("$maxOutside $countInside")
}

