const val CODE_0 = '0'.toByte()
const val CODE_1 = '9'.toByte()

var s: String = ""
var n: Int = 0
val dp = Array(500) { IntArray(500) }

class Main {
    companion object {
        @JvmStatic
        private fun ans(l: Int, r: Int): Int {
            dp[l][r] = when {
                dp[l][r] > 0 -> dp[l][r]
                l == r -> 1
                l > r -> 0
                else -> ((l + 1)..r).fold(1 + ans(l + 1, r)) { acc, i ->
                    if (s[i] != s[l]) acc else min(acc, ans(l + 1, i - 1) + ans(i, r))
                }
            }
            return dp[l][r]
        }

        @JvmStatic
        fun main(args: Array<String>) = with(Scanner(System.`in`)) {
            n = nextInt()
            s = next()
            println(ans(0, n - 1))
        }
    }


    // -----------------------------------------------------------------------------------------------------------------

    private class FastScanner(private val iss: InputStream = System.`in`) {
        fun nextInt(): Int {
            var v = 0
            var begin = false
            while (true) {
                val c = iss.read()
                if (c in CODE_0..CODE_1) {
                    begin = true
                    v *= 10
                    v += c - CODE_0
                } else if (begin) {
                    return v
                }
            }
        }
    }
}

import kotlin.math.*

fun procrust(inp: String): List<String>{
		val retList = mutableListOf<String>()
		for (j in 0..inp.length-1){
			val tmpS = inp.substring(0..j-1) + inp.substring(j+1)
			if (tmpS[0] != '0') retList.add(tmpS)
		}
		return retList
	}

fun main(args: Array<String>){
	fun checkQ(inp: String): Int{
		//println(inp)
		var reslt: Int
		val cand = sqrt(inp.toDouble()).roundToInt()
		if (inp.toInt().rem(cand) == 0){
			reslt = inp.length
		}else{
			if (inp.length > 1) {
				reslt = procrust(inp).map{checkQ(it)}.max()!!.toInt()
				//println(reslt)
			}else{
				reslt = -1
			}
		}
		return reslt
	}

	var inp = readLine().toString()
	val initL = inp.length
	val checked = checkQ(inp)
	if (checked == -1) println(-1) else println(initL-checked)
}

