    val max: Int = Math.sqrt(n.toDouble()).toInt()
    for (i in 1..max) {
        squares.add((i*i).toString())
    }

    println(containsSubstring(n.toString()))
}

fun containsSubstring(n: String): String {

    for (square in squares.reversed()) {
        var indexOf = 0

        var winner = true
        for (char in square.toCharArray()) {
            indexOf = n.indexOf(char, indexOf, true)
            if (indexOf == -1){
                winner = false
                break
            }
        }
        if (winner) {
            return (n.length - square.length).toString()
        }
    }

    return "-1"
}

