import java.io.*
import java.util.*

fun main(args : Array<String>) {
  //====== Input preparations ========================================================
//  val fin = BufferedReader(FileReader("c.in"))
  val fin = BufferedReader(InputStreamReader(System.`in`))
  val fout = PrintWriter (System.out)
  var tokenizer = StringTokenizer("")
  fun next() : String {
    while (!tokenizer.hasMoreTokens())
      tokenizer = StringTokenizer(fin.readLine())
    return tokenizer.nextToken()
  }
  fun nextInt() = next().toInt()
  fun nextLong() = next().toLong()
  fun nextPair() = nextInt() to nextInt()
  fun nextPairDec() = nextInt()-1 to nextInt()-1
  //====== Solution below ============================================================
  val (n,m) = nextPair()
  val k = nextLong()
  val (x,y) = nextPairDec()
  val p = (n-1) * m
  if (p == 0) {
    val d = k / m
    val rem = k % m
    val max = d + (if (rem > 0) 1 else 0)
    val min = d
    val cnt = d + if (rem > y) 1 else 0
    fout.print("$max $min $cnt")
  } else {
    val d = k / p
    val rem = k % p
    val max = d + (if (d == 0L || rem > m) 1 else 0)
    val min = d / 2 + (if (d % 2 == 1L || rem >= m) 1 else 0)
    val (x1,y1) = if (d % 2 == 0L) (x to y) else (n - x - 1 to y)
    var cnt = if (x1 == 0) d/2 else if (x1 == n-1) (d+1)/2 else d
//    println("$x $y")
    if (x1 * m + y1 + 1 <= rem)
      cnt++
    fout.print("$max $min $cnt")
  }

  fout.close()
  fin.close()
}

